INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C1','math',3,2,'u1',2,'(세 자리 수) × (한 자리 수) 올림 없음 — 세 자리 수를 백·십·일로 갈라 자리마다 곱해 자기 자리에 놓고, 0이 있는 자리는 0으로 쓰기',ARRAY['4수01-04']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C2','math',3,2,'u1',3,'올림이 한 번 있는 (세 자리 수) × (한 자리 수) — 일의 자리나 십의 자리 곱이 10을 넘으면 윗자리로 올려 그 자리를 곱한 다음에 더하기',ARRAY['4수01-04']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C3','math',3,2,'u1',3,'곱셈 어림하기 — 곱해지는 수·곱하는 수를 몇백·몇십으로 어림해 곱의 크기와 곱이 놓일 사이를 미리 가늠하고, 계산한 답과 견주어 확인하기',ARRAY['4수01-08']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C4','math',3,2,'u1',4,'올림이 여러 번 있는 (세 자리 수) × (한 자리 수) — 올림이 이어져 네 자리 곱이 되는 계산, 수 카드로 곱이 가장 큰·작은 곱셈식 만들기',ARRAY['4수01-04']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C5','math',3,2,'u1',5,'(몇십) × (몇십), (몇십몇) × (몇십) — 곱하는 수가 몇십이면 (몇)을 곱한 곱의 10배임을 알고 계산하기',ARRAY['4수01-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C6','math',3,2,'u1',6,'(몇) × (몇십몇) — 곱하는 수를 몇십과 몇으로 갈라 각각 곱해 더하고, 두 수의 순서를 바꾸어 곱해도 곱이 같음을 알기',ARRAY['4수01-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C7','math',3,2,'u1',7,'(몇십몇) × (몇십몇) — 모눈을 네 덩이나 두 덩이로 갈라 곱해 더하고, 세로셈에서 십의 자리를 곱한 값을 한 자리 밀어 쓰기',ARRAY['4수01-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C8','math',3,2,'u1',8,'올림이 여러 번 있는 (몇십몇) × (몇십몇) — 두 줄 세로셈으로 네 자리 곱을 구하고, 앞 줄의 올림을 다음 줄에 섞지 않으며 어림한 사이에 드는지 확인하기',ARRAY['4수01-04']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C9','math',3,2,'u1',9,'곱셈으로 문제 해결하기 — 「몇 배가 필요하다」를 곱셈식으로 세우고, 두 가지를 더하거나 견주는 두 단계 문제 해결하기',ARRAY['4수01-04']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X01','math',3,'u1',ARRAY['M3-2-u1-C1','M3-2-u1-C2','M3-2-u1-C4']::text[],'한 자리만 곱하고 다른 자리 숫자는 그대로 내려 쓴다(213 × 3 = 219)','자리마다 모두 곱하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X02','math',3,'u1',ARRAY['M3-2-u1-C2','M3-2-u1-C4','M3-2-u1-C8']::text[],'올림한 수를 윗자리에 더하지 않는다(217 × 2 = 424)','작게 적은 수에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X03','math',3,'u1',ARRAY['M3-2-u1-C2','M3-2-u1-C4']::text[],'올림한 수를 윗자리 숫자에 먼저 더한 뒤 곱한다(217 × 2 → (1 + 1) × 2)','곱한 다음에 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X04','math',3,'u1',ARRAY['M3-2-u1-C4']::text[],'자리별 곱을 올림하지 않고 그대로 이어 붙여 쓴다(274 × 7 → 144928)','10이 넘으면 윗자리로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X05','math',3,'u1',ARRAY['M3-2-u1-C1','M3-2-u1-C2']::text[],'0이 있는 자리에 곱하는 수를 그대로 쓴다(0 × 3 = 3, 307 × 3 = 931)','0에 곱하면 0') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X06','math',3,'u1',ARRAY['M3-2-u1-C5','M3-2-u1-C9']::text[],'몇십을 곱할 때 10배를 빠뜨리거나 0을 더 붙인다(30 × 30 = 90·9000)','0을 떼고 곱한 뒤 10배') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X07','math',3,'u1',ARRAY['M3-2-u1-C6','M3-2-u1-C7','M3-2-u1-C8']::text[],'곱하는 수의 십의 자리를 곱한 값을 한 자리 밀어 쓰지 않는다(7 × 16 = 7 + 42 = 49)','십의 자리 곱은 몇십 곱') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X08','math',3,'u1',ARRAY['M3-2-u1-C6','M3-2-u1-C7','M3-2-u1-C8']::text[],'갈라 곱한 두 곱 가운데 하나만 답으로 쓰고 더하지 않는다(24 × 13 = 72)','두 덩이를 모두 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X09','math',3,'u1',ARRAY['M3-2-u1-C7','M3-2-u1-C8']::text[],'일의 자리끼리, 십의 자리끼리만 곱한다(24 × 13 = 200 + 12 = 212)','네 덩이를 모두 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X10','math',3,'u1',ARRAY['M3-2-u1-C8']::text[],'앞 줄에서 올림한 수를 다음 줄 곱에 다시 더한다(39 × 26의 둘째 줄 39 × 2에 5를 더함)','줄마다 올림은 따로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X11','math',3,'u1',ARRAY['M3-2-u1-C1','M3-2-u1-C2','M3-2-u1-C4','M3-2-u1-C5','M3-2-u1-C6','M3-2-u1-C7','M3-2-u1-C8','M3-2-u1-C9']::text[],'곱셈구구나 더하는 계산에서 실수해 곱이 조금 크거나 작다','어림한 값과 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X12','math',3,'u1',ARRAY['M3-2-u1-C3']::text[],'어림할 때 가까운 몇백·몇십이 아닌 쪽으로 어림하거나 어림한 수끼리 곱하지 않는다','가까운 쪽으로 어림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X13','math',3,'u1',ARRAY['M3-2-u1-C9']::text[],'「몇 배」·「몇씩 몇 묶음」 상황에서 곱셈 대신 두 수를 더하거나 식을 잘못 세운다(31장의 20배 → 31 + 20)','「몇 배」는 곱셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X14','math',3,'u1',ARRAY['M3-2-u1-C4']::text[],'곱을 가장 크게 만들 때 가장 큰 수를 곱해지는 수 맨 앞(백의 자리)에 놓는다','가장 큰 수는 곱하는 수 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X15','math',3,'u1',ARRAY['M3-2-u1-C1','M3-2-u1-C2','M3-2-u1-C3','M3-2-u1-C4','M3-2-u1-C5','M3-2-u1-C6','M3-2-u1-C7','M3-2-u1-C8','M3-2-u1-C9']::text[],'묻는 말을 거꾸로 읽는다 — 틀린↔바른, 아닌↔맞는, 큰↔작은','물음의 「틀린·아닌」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X16','math',3,'u1',ARRAY['M3-2-u1-C6']::text[],'곱하는 두 수의 순서를 바꾸면 곱이 달라진다고 생각한다','순서를 바꾸어도 곱은 같다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_basic#1','math',3,2,'u1','L02','g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',1,'sa','auto','143 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C1","difficulty":1,"kind":"sa","stem":"143 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["286"],"explanation":["143을 100, 40, 3으로 갈라 곱해요: 100 × 2 = 200, 40 × 2 = 80, 3 × 2 = 6.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요.","200 + 80 + 6 = 286 — 어림한 100 × 2 = 200과 가까워요."],"variant_rule":{"alt":[{"stem":"322 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["966"],"explanation":["322를 300, 20, 2로 갈라 곱해요: 300 × 3 = 900, 20 × 3 = 60, 2 × 3 = 6.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요.","900 + 60 + 6 = 966 — 어림한 300 × 3 = 900과 가까워요."],"asset":null},{"stem":"414 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["828"],"explanation":["414를 400, 10, 4로 갈라 곱해요: 400 × 2 = 800, 10 × 2 = 20, 4 × 2 = 8.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요.","800 + 20 + 8 = 828 — 어림한 400 × 2 = 800과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_basic#2','math',3,2,'u1','L02','g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',1,'mc','auto','200 × 4는 얼마인가요?',ARRAY['M3-2-u1-X05','M3-2-u1-X01']::text[],true,'{"seq":2,"concept":"M3-2-u1-C1","difficulty":1,"kind":"mc","stem":"200 × 4는 얼마인가요?","options":[{"t":"800","correct":true},{"t":"840","mis":"M3-2-u1-X05"},{"t":"804","mis":"M3-2-u1-X05"},{"t":"200","mis":"M3-2-u1-X01"}],"explanation":["200을 200, 0, 0으로 갈라 곱해요: 200 × 4 = 800, 0 × 4 = 0, 0 × 4 = 0.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","800 + 0 + 0 = 800 — 어림한 200 × 4 = 800과 가까워요."],"variant_rule":{"alt":[{"stem":"310 × 2는 얼마인가요?","options":[{"t":"620","correct":true},{"t":"622","mis":"M3-2-u1-X05"},{"t":"310","mis":"M3-2-u1-X01"},{"t":"610","mis":"M3-2-u1-X01"}],"explanation":["310을 300, 10, 0으로 갈라 곱해요: 300 × 2 = 600, 10 × 2 = 20, 0 × 2 = 0.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","600 + 20 + 0 = 620 — 어림한 300 × 2 = 600과 가까워요."],"asset":null},{"stem":"320 × 3은 얼마인가요?","options":[{"t":"960","correct":true},{"t":"963","mis":"M3-2-u1-X05"},{"t":"320","mis":"M3-2-u1-X01"},{"t":"920","mis":"M3-2-u1-X01"}],"explanation":["320을 300, 20, 0으로 갈라 곱해요: 300 × 3 = 900, 20 × 3 = 60, 0 × 3 = 0.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","900 + 60 + 0 = 960 — 어림한 300 × 3 = 900과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_basic#3','math',3,2,'u1','L02','g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',1,'sa','auto','143 × 2를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C1","difficulty":1,"kind":"sa","stem":"143 × 2를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["80"],"explanation":["143을 100, 40, 3으로 갈라요.","□는 40 × 2 = 80이에요.","200 + 80 + 6 = 286 — 143 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["100 × 2","=","200"],["40 × 2","=",null],["3 × 2","=","6"],["200 + □ + 6","=","286"]]},"variant_rule":{"alt":[{"stem":"301 × 3을 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["301을 300, 0, 1로 갈라요.","□는 1 × 3 = 3이에요.","900 + 0 + 3 = 903 — 301 × 3의 곱이에요."],"asset":{"type":"expr_grid","rows":[["300 × 3","=","900"],["0 × 3","=","0"],["1 × 3","=",null],["900 + 0 + □","=","903"]]}},{"stem":"111 × 8을 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["800"],"explanation":["111을 100, 10, 1로 갈라요.","□는 100 × 8 = 800이에요.","800 + 80 + 8 = 888 — 111 × 8의 곱이에요."],"asset":{"type":"expr_grid","rows":[["100 × 8","=",null],["10 × 8","=","80"],["1 × 8","=","8"],["□ + 80 + 8","=","888"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_basic#4','math',3,2,'u1','L02','g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C3',1,'mc','auto','213 × 3을 어림하면 약 얼마인가요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],true,'{"seq":4,"concept":"M3-2-u1-C3","difficulty":1,"kind":"mc","stem":"213 × 3을 어림하면 약 얼마인가요?","options":[{"t":"약 600","correct":true},{"t":"약 300","mis":"M3-2-u1-X12"},{"t":"약 203","mis":"M3-2-u1-X12"},{"t":"약 6000","mis":"M3-2-u1-X06"}],"explanation":["213은 가까운 몇백 200으로 어림해요.","200 × 3 = 600이에요.","그래서 약 600이에요 — 실제 곱 639와 가까워요."],"variant_rule":{"alt":[{"stem":"331 × 3을 어림하면 약 얼마인가요?","options":[{"t":"약 900","correct":true},{"t":"약 600","mis":"M3-2-u1-X12"},{"t":"약 303","mis":"M3-2-u1-X12"},{"t":"약 9000","mis":"M3-2-u1-X06"}],"explanation":["331은 가까운 몇백 300으로 어림해요.","300 × 3 = 900이에요.","그래서 약 900이에요 — 실제 곱 993과 가까워요."],"asset":null},{"stem":"103 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 200","correct":true},{"t":"약 102","mis":"M3-2-u1-X12"},{"t":"약 2000","mis":"M3-2-u1-X06"},{"t":"약 100","mis":"M3-2-u1-X12"}],"explanation":["103은 가까운 몇백 100으로 어림해요.","100 × 2 = 200이에요.","그래서 약 200이에요 — 실제 곱 206과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_basic#5','math',3,2,'u1','L02','g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',2,'sa','auto','421 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C1","difficulty":2,"kind":"sa","stem":"421 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["세로셈은 일의 자리부터 곱해요.","백의 자리: 4 × 2 = 8 → 8을 써요.","421 × 2 = 842 — 백의 자리 숫자는 8이에요."],"asset":{"type":"expr_grid","rows":[["","","4","2","1"],["×","","","","2"],["","",null,"4","2"]]},"variant_rule":{"alt":[{"stem":"111 × 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 1 × 4 = 4 → 4를 써요.","111 × 4 = 444 — 일의 자리 숫자는 4예요."],"asset":{"type":"expr_grid","rows":[["","","1","1","1"],["×","","","","4"],["","","4","4",null]]}},{"stem":"134 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 4 × 2 = 8 → 8을 써요.","134 × 2 = 268 — 일의 자리 숫자는 8이에요."],"asset":{"type":"expr_grid","rows":[["","","1","3","4"],["×","","","","2"],["","","2","6",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_basic#6','math',3,2,'u1','L02','g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',2,'mc','auto','방울토마토를 한 상자에 143개씩 2상자에 담았어요. 방울토마토는 모두 몇 개인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X01']::text[],true,'{"seq":6,"concept":"M3-2-u1-C1","difficulty":2,"kind":"mc","stem":"방울토마토를 한 상자에 143개씩 2상자에 담았어요. 방울토마토는 모두 몇 개인가요?","options":[{"t":"286개","correct":true},{"t":"145개","mis":"M3-2-u1-X13"},{"t":"146개","mis":"M3-2-u1-X01"},{"t":"243개","mis":"M3-2-u1-X01"}],"explanation":["143개씩 2번(묶음) — 곱셈식 143 × 2로 세워요.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요.","143 × 2 = 286 — 모두 286개예요."],"variant_rule":{"alt":[{"stem":"하루에 202쪽씩 2일 동안 책을 읽었어요. 모두 몇 쪽을 읽었나요?","options":[{"t":"404쪽","correct":true},{"t":"204쪽","mis":"M3-2-u1-X13"},{"t":"424쪽","mis":"M3-2-u1-X05"},{"t":"402쪽","mis":"M3-2-u1-X01"}],"explanation":["202쪽씩 2번(묶음) — 곱셈식 202 × 2로 세워요.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","202 × 2 = 404 — 모두 404쪽이에요."],"asset":null},{"stem":"한 개에 314원인 지우개를 2개 샀어요. 모두 얼마인가요?","options":[{"t":"628원","correct":true},{"t":"316원","mis":"M3-2-u1-X13"},{"t":"318원","mis":"M3-2-u1-X01"},{"t":"614원","mis":"M3-2-u1-X01"}],"explanation":["314원씩 2번(묶음) — 곱셈식 314 × 2로 세워요.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요.","314 × 2 = 628 — 모두 628원이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_basic#7','math',3,2,'u1','L02','g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',2,'ox','auto','320 × 3을 계산하는데 일의 자리 0에 3을 곱해 3을 쓰고 963이라고 했어요. 바르게 계산했어요.',ARRAY['M3-2-u1-X05']::text[],true,'{"seq":7,"concept":"M3-2-u1-C1","difficulty":2,"kind":"ox","stem":"320 × 3을 계산하는데 일의 자리 0에 3을 곱해 3을 쓰고 963이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"0에 어떤 수를 곱해도 0이라서","correct":true},{"t":"0 자리에는 곱하는 수를 그대로 써야 해서","mis":"M3-2-u1-X05"}],"mis":"M3-2-u1-X05","explanation":["0 × 3 = 0이에요.","일의 자리는 0 — 320 × 3 = 960이에요.","963은 0 자리에 3을 써서 틀렸어요."],"variant_rule":{"alt":[{"stem":"230 × 2를 계산하는데 일의 자리 0에 2를 곱해 2를 쓰고 462라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"0에 어떤 수를 곱해도 0이라서","correct":true},{"t":"0 자리에는 곱하는 수를 그대로 써야 해서","mis":"M3-2-u1-X05"}],"explanation":["0 × 2 = 0이에요.","일의 자리는 0 — 230 × 2 = 460이에요.","462는 0 자리에 2를 써서 틀렸어요."],"asset":null},{"stem":"110 × 7을 계산하는데 일의 자리 0에 7을 곱해 7을 쓰고 777이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"0에 어떤 수를 곱해도 0이라서","correct":true},{"t":"0 자리에는 곱하는 수를 그대로 써야 해서","mis":"M3-2-u1-X05"}],"explanation":["0 × 7 = 0이에요.","일의 자리는 0 — 110 × 7 = 770이에요.","777은 0 자리에 7을 써서 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_basic#8','math',3,2,'u1','L02','g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',2,'sa','auto','314 × 2를 계산할 때 300 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u1-C1","difficulty":2,"kind":"sa","stem":"314 × 2를 계산할 때 300 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["600"],"explanation":["314의 백의 자리 숫자 3은 300을 나타내요.","3 × 2 = 6 — 그 100배라 300 × 2 = 600이에요.","여기에 10 × 2, 4 × 2를 더하면 314 × 2 = 628이에요."],"variant_rule":{"alt":[{"stem":"123 × 2를 계산할 때 100 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["200"],"explanation":["123의 백의 자리 숫자 1은 100을 나타내요.","1 × 2 = 2 — 그 100배라 100 × 2 = 200이에요.","여기에 20 × 2, 3 × 2를 더하면 123 × 2 = 246이에요."],"asset":null},{"stem":"111 × 9를 계산할 때 100 × 9는 얼마인가요? 숫자로 쓰세요.","answer":["900"],"explanation":["111의 백의 자리 숫자 1은 100을 나타내요.","1 × 9 = 9 — 그 100배라 100 × 9 = 900이에요.","여기에 10 × 9, 1 × 9를 더하면 111 × 9 = 999예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_basic#9','math',3,2,'u1','L02','g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',2,'match','auto','곱셈식과 곱을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u1-C1","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"231 × 3","r":"693"},{"l":"323 × 3","r":"969"},{"l":"444 × 2","r":"888"}],"mis":"M3-2-u1-X01","explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","231 × 3 = 693, 323 × 3 = 969, 444 × 2 = 888.","어림한 값과 가까운지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"101 × 4","r":"404"},{"l":"322 × 3","r":"966"},{"l":"313 × 3","r":"939"}],"explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","101 × 4 = 404, 322 × 3 = 966, 313 × 3 = 939.","어림한 값과 가까운지 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"422 × 2","r":"844"},{"l":"201 × 4","r":"804"},{"l":"420 × 2","r":"840"}],"explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","422 × 2 = 844, 201 × 4 = 804, 420 × 2 = 840.","어림한 값과 가까운지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_basic#10','math',3,2,'u1','L02','g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',3,'error','auto','213 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X01','M3-2-u1-X15']::text[],true,'{"seq":10,"concept":"M3-2-u1-C1","difficulty":3,"kind":"error","stem":"213 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「213 × 3 = 219야」","correct":true,"mis_target":"M3-2-u1-X01"},{"t":"하랑 — 「213 × 3 = 639야」","mis":"M3-2-u1-X15"},{"t":"하린 — 「어림하면 약 600이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요.","213 × 3 = 639예요.","태오는 219로 잘못 구했어요 — 자리마다 모두 곱하기."],"variant_rule":{"alt":[{"stem":"102 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「102 × 4 = 448이야」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"하린 — 「102 × 4 = 408이야」","mis":"M3-2-u1-X15"},{"t":"태오 — 「4 × 102 = 408이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","102 × 4 = 408이에요.","은우는 448로 잘못 구했어요 — 0에 곱하면 0."],"asset":null},{"stem":"242 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「242 × 2 = 244야」","correct":true,"mis_target":"M3-2-u1-X01"},{"t":"시우 — 「242 × 2 = 484야」","mis":"M3-2-u1-X15"},{"t":"태오 — 「어림하면 약 400이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요.","242 × 2 = 484예요.","하린은 244로 잘못 구했어요 — 자리마다 모두 곱하기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_challenge#1','math',3,2,'u1','L02','g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',2,'ox','auto','213 × 3을 계산하는데 일의 자리만 3 × 3 = 9로 곱하고 백·십의 자리 숫자는 그대로 내려 써서 219라고 했어요. 바르게 계산했어요.',ARRAY['M3-2-u1-X01']::text[],true,'{"seq":1,"concept":"M3-2-u1-C1","difficulty":2,"kind":"ox","stem":"213 × 3을 계산하는데 일의 자리만 3 × 3 = 9로 곱하고 백·십의 자리 숫자는 그대로 내려 써서 219라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"모든 자리에 3을 곱해야 해서","correct":true},{"t":"일의 자리만 곱하면 되어서","mis":"M3-2-u1-X01"}],"mis":"M3-2-u1-X01","explanation":["213은 백·십·일 세 자리가 모두 3묶음이에요.","200 × 3 = 600, 10 × 3 = 30, 3 × 3 = 9.","213 × 3 = 639예요."],"variant_rule":{"alt":[{"stem":"330 × 3을 계산하는데 일의 자리만 0 × 3 = 0으로 곱하고 백·십의 자리 숫자는 그대로 내려 써서 330이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"모든 자리에 3을 곱해야 해서","correct":true},{"t":"일의 자리만 곱하면 되어서","mis":"M3-2-u1-X01"}],"explanation":["330은 백·십·일 세 자리가 모두 3묶음이에요.","300 × 3 = 900, 30 × 3 = 90, 0 × 3 = 0.","330 × 3 = 990이에요."],"asset":null},{"stem":"231 × 3을 계산하는데 일의 자리만 1 × 3 = 3으로 곱하고 백·십의 자리 숫자는 그대로 내려 써서 233이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"모든 자리에 3을 곱해야 해서","correct":true},{"t":"일의 자리만 곱하면 되어서","mis":"M3-2-u1-X01"}],"explanation":["231은 백·십·일 세 자리가 모두 3묶음이에요.","200 × 3 = 600, 30 × 3 = 90, 1 × 3 = 3.","231 × 3 = 693이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_challenge#2','math',3,2,'u1','L02','g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C3',2,'ox','auto','312 × 3을 계산했더니 316이 나왔어요. 어림해 보면 알맞은 답이에요.',ARRAY['M3-2-u1-X12']::text[],true,'{"seq":2,"concept":"M3-2-u1-C3","difficulty":2,"kind":"ox","stem":"312 × 3을 계산했더니 316이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 900과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u1-X12"}],"mis":"M3-2-u1-X12","explanation":["312 × 3을 어림하면 300 × 3 = 900이에요.","316은 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 312 × 3 = 936이에요."],"variant_rule":{"alt":[{"stem":"303 × 3을 계산했더니 309가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 900과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u1-X12"}],"explanation":["303 × 3을 어림하면 300 × 3 = 900이에요.","309는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 303 × 3 = 909예요."],"asset":null},{"stem":"331 × 3을 계산했더니 333이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 900과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u1-X12"}],"explanation":["331 × 3을 어림하면 300 × 3 = 900이에요.","333은 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 331 × 3 = 993이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_challenge#3','math',3,2,'u1','L02','g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',3,'mc','auto','곱을 견주어 ○ 안에 알맞은 것을 고르세요. 342 × 2 ○ 230 × 3',ARRAY['M3-2-u1-X11','M3-2-u1-X15']::text[],true,'{"seq":3,"concept":"M3-2-u1-C1","difficulty":3,"kind":"mc","stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 342 × 2 ○ 230 × 3","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["342 × 2 = 684예요.","230 × 3 = 690이에요.","684 < 690 — 알맞은 것은 <예요."],"variant_rule":{"alt":[{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 101 × 9 ○ 311 × 3","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["101 × 9 = 909예요.","311 × 3 = 933이에요.","909 < 933 — 알맞은 것은 <예요."],"asset":null},{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 230 × 3 ○ 303 × 2","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["230 × 3 = 690이에요.","303 × 2 = 606이에요.","690 > 606 — 알맞은 것은 >예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_challenge#4','math',3,2,'u1','L02','g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',3,'sa','auto','210, 120, 121 가운데 한 수에 3을 곱해 가장 큰 값을 만들려고 해요. 그 값은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u1-C1","difficulty":3,"kind":"sa","stem":"210, 120, 121 가운데 한 수에 3을 곱해 가장 큰 값을 만들려고 해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["630"],"explanation":["곱하는 수가 같으면 곱해지는 수가 클수록 곱이 커요.","가장 큰 수는 210 — 210 × 3 = 630.","나머지는 120 × 3 = 360, 121 × 3 = 363."],"variant_rule":{"alt":[{"stem":"302, 230, 203 가운데 한 수에 3을 곱해 가장 큰 값을 만들려고 해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["906"],"explanation":["곱하는 수가 같으면 곱해지는 수가 클수록 곱이 커요.","가장 큰 수는 302 — 302 × 3 = 906.","나머지는 230 × 3 = 690, 203 × 3 = 609."],"asset":null},{"stem":"112, 211, 121 가운데 한 수에 4를 곱해 가장 큰 값을 만들려고 해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["844"],"explanation":["곱하는 수가 같으면 곱해지는 수가 클수록 곱이 커요.","가장 큰 수는 211 — 211 × 4 = 844.","나머지는 112 × 4 = 448, 121 × 4 = 484."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_challenge#5','math',3,2,'u1','L02','g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',3,'sa','auto','21□ × 3 = 639 — □에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C1","difficulty":3,"kind":"sa","stem":"21□ × 3 = 639 — □에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["곱 639의 일의 자리를 봐요.","□ × 3이 일의 자리 곱 9가 되어야 해요.","□ = 3 — 213 × 3 = 639예요."],"variant_rule":{"alt":[{"stem":"30□ × 2 = 606 — □에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["곱 606의 일의 자리를 봐요.","□ × 2가 일의 자리 곱 6이 되어야 해요.","□ = 3 — 303 × 2 = 606이에요."],"asset":null},{"stem":"□32 × 3 = 396 — □에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["곱 396의 백의 자리를 봐요.","□ × 3이 백의 자리 곱 3이 되어야 해요.","□ = 1 — 132 × 3 = 396이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_challenge#6','math',3,2,'u1','L02','g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',3,'sa','auto','블루베리가 한 바구니에 302개씩 3바구니 있어요. 블루베리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u1-C1","difficulty":3,"kind":"sa","stem":"블루베리가 한 바구니에 302개씩 3바구니 있어요. 블루베리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["906"],"explanation":["302개씩 3번(묶음) — 곱셈식 302 × 3으로 세워요.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","302 × 3 = 906 — 모두 906개예요."],"variant_rule":{"alt":[{"stem":"체험관에 하루에 320명씩 3일 동안 어린이가 다녀갔어요. 모두 몇 명이 다녀갔나요? 숫자로 쓰세요.","answer":["960"],"explanation":["320명씩 3번(묶음) — 곱셈식 320 × 3으로 세워요.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","320 × 3 = 960 — 모두 960명이에요."],"asset":null},{"stem":"방울토마토를 한 상자에 130개씩 3상자에 담았어요. 방울토마토는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["390"],"explanation":["130개씩 3번(묶음) — 곱셈식 130 × 3으로 세워요.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","130 × 3 = 390 — 모두 390개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_challenge#7','math',3,2,'u1','L02','g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',3,'error','auto','402 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X05','M3-2-u1-X15']::text[],true,'{"seq":7,"concept":"M3-2-u1-C1","difficulty":3,"kind":"error","stem":"402 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「402 × 2 = 824야」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"시우 — 「402 × 2 = 804야」","mis":"M3-2-u1-X15"},{"t":"하랑 — 「어림하면 약 800이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","402 × 2 = 804예요.","태오는 824로 잘못 구했어요 — 0에 곱하면 0."],"variant_rule":{"alt":[{"stem":"330 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「330 × 3 = 993이야」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"시우 — 「330 × 3 = 990이야」","mis":"M3-2-u1-X15"},{"t":"하랑 — 「3 × 330 = 990이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","330 × 3 = 990이에요.","하린은 993으로 잘못 구했어요 — 0에 곱하면 0."],"asset":null},{"stem":"110 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「110 × 8 = 888이야」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"은우 — 「110 × 8 = 880이야」","mis":"M3-2-u1-X15"},{"t":"지유 — 「어림하면 약 800이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","110 × 8 = 880이에요.","하린은 888로 잘못 구했어요 — 0에 곱하면 0."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_challenge#8','math',3,2,'u1','L02','g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',4,'essay','teacher','고구마가 143개씩 든 자루가 2개 있어요. 143 × 2를 수 모형으로 구하는 방법과 자리마다 곱하는 방법으로 각각 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C1","difficulty":4,"kind":"essay","stem":"고구마가 143개씩 든 자루가 2개 있어요. 143 × 2를 수 모형으로 구하는 방법과 자리마다 곱하는 방법으로 각각 설명해 보세요.","answer_guide":{"answer":"예: ① 백 모형 1개, 십 모형 4개, 일 모형 3개가 두 묶음이면 백 모형 2개, 십 모형 8개, 일 모형 6개이므로 286이다. ② 100 × 2 = 200, 40 × 2 = 80, 3 × 2 = 6을 더하면 286이다. 고구마는 286개이다.","scoring_points":["수 모형을 자리별로 모아 286을 구했는가","200 + 80 + 6으로 자리마다 곱해 더했는가","고구마 286개라고 답했는가"]},"explanation":["백 2개·십 8개·일 6개 = 286.","200 + 80 + 6 = 286.","143 × 2 = 286."],"asset":{"type":"expr_grid","rows":[["100 × 2","=","200"],["40 × 2","=","80"],["3 × 2","=","6"],["200 + 80 + 6","=","286"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_challenge#9','math',3,2,'u1','L02','g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',4,'essay','teacher','은우는 307 × 3을 931이라고 했어요. 은우의 답이 맞는지 판단하고, 무엇을 잘못했는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u1-C1","difficulty":4,"kind":"essay","stem":"은우는 307 × 3을 931이라고 했어요. 은우의 답이 맞는지 판단하고, 무엇을 잘못했는지 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 십의 자리 0에 3을 곱하면 0인데 은우는 3을 썼다. 300 × 3 = 900, 0 × 3 = 0, 7 × 3 = 21이므로 바른 답은 921이다.","scoring_points":["틀렸다고 판단했는가","0 × 3 = 0이라고 설명했는가","바른 답 921을 구했는가"]},"explanation":["0에 어떤 수를 곱해도 0이에요.","900 + 0 + 21 = 921.","은우는 0 자리에 3을 써서 931이 되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L02_challenge#10','math',3,2,'u1','L02','g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',4,'sa','auto','□31 × 3 = 693 — □에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u1-C1","difficulty":4,"kind":"sa","stem":"□31 × 3 = 693 — □에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["곱 693의 백의 자리를 봐요.","□ × 3이 백의 자리 곱 6이 되어야 해요.","□ = 2 — 231 × 3 = 693이에요."],"variant_rule":{"alt":[{"stem":"□22 × 2 = 444 — □에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["곱 444의 백의 자리를 봐요.","□ × 2가 백의 자리 곱 4가 되어야 해요.","□ = 2 — 222 × 2 = 444예요."],"asset":null},{"stem":"□21 × 3 = 363 — □에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["곱 363의 백의 자리를 봐요.","□ × 3이 백의 자리 곱 3이 되어야 해요.","□ = 1 — 121 × 3 = 363이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_basic#1','math',3,2,'u1','L03','g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C2',1,'sa','auto','217 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C2","difficulty":1,"kind":"sa","stem":"217 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["434"],"explanation":["217을 200, 10, 7로 갈라 곱해요: 200 × 2 = 400, 10 × 2 = 20, 7 × 2 = 14.","일의 자리 7 × 2 = 14 → 1 올림.","400 + 20 + 14 = 434 — 어림한 200 × 2 = 400과 가까워요."],"variant_rule":{"alt":[{"stem":"317 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["634"],"explanation":["317을 300, 10, 7로 갈라 곱해요: 300 × 2 = 600, 10 × 2 = 20, 7 × 2 = 14.","일의 자리 7 × 2 = 14 → 1 올림.","600 + 20 + 14 = 634 — 어림한 300 × 2 = 600과 가까워요."],"asset":null},{"stem":"105 × 7은 얼마인가요? 숫자로 쓰세요.","answer":["735"],"explanation":["105를 100, 0, 5로 갈라 곱해요: 100 × 7 = 700, 0 × 7 = 0, 5 × 7 = 35.","일의 자리 5 × 7 = 35 → 3 올림.","700 + 0 + 35 = 735 — 어림한 100 × 7 = 700과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_basic#2','math',3,2,'u1','L03','g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C2',1,'sa','auto','217 × 2에서 일의 자리 7 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u1-C2","difficulty":1,"kind":"sa","stem":"217 × 2에서 일의 자리 7 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["일의 자리끼리 7 × 2 = 14예요.","4를 일의 자리에 쓰고 1을 십의 자리로 올려요.","217 × 2 = 434예요."],"variant_rule":{"alt":[{"stem":"209 × 3에서 일의 자리 9 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["일의 자리끼리 9 × 3 = 27이에요.","7을 일의 자리에 쓰고 2를 십의 자리로 올려요.","209 × 3 = 627이에요."],"asset":null},{"stem":"106 × 7에서 일의 자리 6 × 7은 얼마인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["일의 자리끼리 6 × 7 = 42예요.","2를 일의 자리에 쓰고 4를 십의 자리로 올려요.","106 × 7 = 742예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_basic#3','math',3,2,'u1','L03','g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C2',1,'mc','auto','132 × 4는 얼마인가요?',ARRAY['M3-2-u1-X02','M3-2-u1-X03','M3-2-u1-X01']::text[],true,'{"seq":3,"concept":"M3-2-u1-C2","difficulty":1,"kind":"mc","stem":"132 × 4는 얼마인가요?","options":[{"t":"528","correct":true},{"t":"428","mis":"M3-2-u1-X02"},{"t":"828","mis":"M3-2-u1-X03"},{"t":"138","mis":"M3-2-u1-X01"}],"explanation":["132를 100, 30, 2로 갈라 곱해요: 100 × 4 = 400, 30 × 4 = 120, 2 × 4 = 8.","십의 자리 3 × 4 = 12 → 1 올림.","400 + 120 + 8 = 528 — 어림한 100 × 4 = 400과 가까워요."],"variant_rule":{"alt":[{"stem":"360 × 2는 얼마인가요?","options":[{"t":"720","correct":true},{"t":"620","mis":"M3-2-u1-X02"},{"t":"820","mis":"M3-2-u1-X03"},{"t":"360","mis":"M3-2-u1-X01"}],"explanation":["360을 300, 60, 0으로 갈라 곱해요: 300 × 2 = 600, 60 × 2 = 120, 0 × 2 = 0.","십의 자리 6 × 2 = 12 → 1 올림.","600 + 120 + 0 = 720 — 어림한 400 × 2 = 800과 가까워요."],"asset":null},{"stem":"140 × 4는 얼마인가요?","options":[{"t":"560","correct":true},{"t":"460","mis":"M3-2-u1-X02"},{"t":"860","mis":"M3-2-u1-X03"},{"t":"140","mis":"M3-2-u1-X01"}],"explanation":["140을 100, 40, 0으로 갈라 곱해요: 100 × 4 = 400, 40 × 4 = 160, 0 × 4 = 0.","십의 자리 4 × 4 = 16 → 1 올림.","400 + 160 + 0 = 560 — 어림한 100 × 4 = 400과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_basic#4','math',3,2,'u1','L03','g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C3',1,'mc','auto','217 × 2를 어림하면 약 얼마인가요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],true,'{"seq":4,"concept":"M3-2-u1-C3","difficulty":1,"kind":"mc","stem":"217 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 400","correct":true},{"t":"약 200","mis":"M3-2-u1-X12"},{"t":"약 202","mis":"M3-2-u1-X12"},{"t":"약 4000","mis":"M3-2-u1-X06"}],"explanation":["217은 가까운 몇백 200으로 어림해요.","200 × 2 = 400이에요.","그래서 약 400이에요 — 실제 곱 434와 가까워요."],"variant_rule":{"alt":[{"stem":"247 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 400","correct":true},{"t":"약 200","mis":"M3-2-u1-X12"},{"t":"약 202","mis":"M3-2-u1-X12"},{"t":"약 4000","mis":"M3-2-u1-X06"}],"explanation":["247은 가까운 몇백 200으로 어림해요.","200 × 2 = 400이에요.","그래서 약 400이에요 — 실제 곱 494와 가까워요."],"asset":null},{"stem":"409 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 800","correct":true},{"t":"약 600","mis":"M3-2-u1-X12"},{"t":"약 402","mis":"M3-2-u1-X12"},{"t":"약 8000","mis":"M3-2-u1-X06"}],"explanation":["409는 가까운 몇백 400으로 어림해요.","400 × 2 = 800이에요.","그래서 약 800이에요 — 실제 곱 818과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_basic#5','math',3,2,'u1','L03','g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C2',2,'sa','auto','217 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C2","difficulty":2,"kind":"sa","stem":"217 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 7 × 2 = 14 → 4를 써요.","217 × 2 = 434 — 일의 자리 숫자는 4예요."],"asset":{"type":"expr_grid","rows":[["올림","","","1",""],["","","2","1","7"],["×","","","","2"],["","","4","3",null]]},"variant_rule":{"alt":[{"stem":"227 × 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 2 × 3 + 올림 2 = 8 → 8을 써요.","227 × 3 = 681 — 십의 자리 숫자는 8이에요."],"asset":{"type":"expr_grid","rows":[["올림","","","2",""],["","","2","2","7"],["×","","","","3"],["","","6",null,"1"]]}},{"stem":"417 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 1 × 2 + 올림 1 = 3 → 3을 써요.","417 × 2 = 834 — 십의 자리 숫자는 3이에요."],"asset":{"type":"expr_grid","rows":[["올림","","","1",""],["","","4","1","7"],["×","","","","2"],["","","8",null,"4"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_basic#6','math',3,2,'u1','L03','g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C2',2,'mc','auto','체험관에 하루에 114명씩 6일 동안 어린이가 다녀갔어요. 모두 몇 명이 다녀갔나요?',ARRAY['M3-2-u1-X13','M3-2-u1-X02','M3-2-u1-X03']::text[],true,'{"seq":6,"concept":"M3-2-u1-C2","difficulty":2,"kind":"mc","stem":"체험관에 하루에 114명씩 6일 동안 어린이가 다녀갔어요. 모두 몇 명이 다녀갔나요?","options":[{"t":"684명","correct":true},{"t":"120명","mis":"M3-2-u1-X13"},{"t":"664명","mis":"M3-2-u1-X02"},{"t":"784명","mis":"M3-2-u1-X03"}],"explanation":["114명씩 6번(묶음) — 곱셈식 114 × 6으로 세워요.","일의 자리 4 × 6 = 24 → 2 올림.","114 × 6 = 684 — 모두 684명이에요."],"variant_rule":{"alt":[{"stem":"방울토마토를 한 상자에 215개씩 4상자에 담았어요. 방울토마토는 모두 몇 개인가요?","options":[{"t":"860개","correct":true},{"t":"219개","mis":"M3-2-u1-X13"},{"t":"840개","mis":"M3-2-u1-X02"},{"t":"920개","mis":"M3-2-u1-X03"}],"explanation":["215개씩 4번(묶음) — 곱셈식 215 × 4로 세워요.","일의 자리 5 × 4 = 20 → 2 올림.","215 × 4 = 860 — 모두 860개예요."],"asset":null},{"stem":"하루에 108쪽씩 2일 동안 책을 읽었어요. 모두 몇 쪽을 읽었나요?","options":[{"t":"216쪽","correct":true},{"t":"110쪽","mis":"M3-2-u1-X13"},{"t":"206쪽","mis":"M3-2-u1-X02"},{"t":"226쪽","mis":"M3-2-u1-X03"}],"explanation":["108쪽씩 2번(묶음) — 곱셈식 108 × 2로 세워요.","일의 자리 8 × 2 = 16 → 1 올림.","108 × 2 = 216 — 모두 216쪽이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_basic#7','math',3,2,'u1','L03','g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C2',2,'ox','auto','217 × 2를 계산하는데 일의 자리에서 십의 자리로 올림한 1을 더하지 않고 424라고 했어요. 바르게 계산했어요.',ARRAY['M3-2-u1-X02']::text[],true,'{"seq":7,"concept":"M3-2-u1-C2","difficulty":2,"kind":"ox","stem":"217 × 2를 계산하는데 일의 자리에서 십의 자리로 올림한 1을 더하지 않고 424라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수는 윗자리를 곱한 다음 꼭 더해야 해서","correct":true},{"t":"올림한 수는 작게 적어 두기만 하면 되어서","mis":"M3-2-u1-X02"}],"mis":"M3-2-u1-X02","explanation":["일의 자리 7 × 2 = 14 → 1 올림.","217 × 2 = 434예요.","424는 올림한 1을 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["올림","","","1",""],["","","2","1","7"],["×","","","","2"],["","",null,null,null]]},"variant_rule":{"alt":[{"stem":"108 × 6을 계산하는데 일의 자리에서 십의 자리로 올림한 4를 더하지 않고 608이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수는 윗자리를 곱한 다음 꼭 더해야 해서","correct":true},{"t":"올림한 수는 작게 적어 두기만 하면 되어서","mis":"M3-2-u1-X02"}],"explanation":["일의 자리 8 × 6 = 48 → 4 올림.","108 × 6 = 648이에요.","608은 올림한 4를 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["올림","","","4",""],["","","1","0","8"],["×","","","","6"],["","",null,null,null]]}},{"stem":"316 × 2를 계산하는데 일의 자리에서 십의 자리로 올림한 1을 더하지 않고 622라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수는 윗자리를 곱한 다음 꼭 더해야 해서","correct":true},{"t":"올림한 수는 작게 적어 두기만 하면 되어서","mis":"M3-2-u1-X02"}],"explanation":["일의 자리 6 × 2 = 12 → 1 올림.","316 × 2 = 632예요.","622는 올림한 1을 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["올림","","","1",""],["","","3","1","6"],["×","","","","2"],["","",null,null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
