INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_basic#9','math',3,2,'u1','L03','g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C3',2,'mc','auto','328 × 3을 계산하기 전에 어림하려고 해요. 어떻게 어림하는 것이 알맞은가요?',ARRAY['M3-2-u1-X06','M3-2-u1-X13','M3-2-u1-X12']::text[],true,'{"seq":9,"concept":"M3-2-u1-C3","difficulty":2,"kind":"mc","stem":"328 × 3을 계산하기 전에 어림하려고 해요. 어떻게 어림하는 것이 알맞은가요?","options":[{"t":"300 × 3 = 900쯤으로 봐요","correct":true},{"t":"3 × 3 = 9쯤으로 봐요","mis":"M3-2-u1-X06"},{"t":"328 + 3 = 331쯤으로 봐요","mis":"M3-2-u1-X13"},{"t":"400 × 3 = 1200쯤으로 봐요","mis":"M3-2-u1-X12"}],"explanation":["328에 가까운 몇백은 300이에요.","300 × 3 = 900이에요.","실제 곱 984는 어림한 900과 가까워요."],"variant_rule":{"alt":[{"stem":"207 × 2를 계산하기 전에 어림하려고 해요. 어떻게 어림하는 것이 알맞은가요?","options":[{"t":"200 × 2 = 400쯤으로 봐요","correct":true},{"t":"2 × 2 = 4쯤으로 봐요","mis":"M3-2-u1-X06"},{"t":"207 + 2 = 209쯤으로 봐요","mis":"M3-2-u1-X13"},{"t":"300 × 2 = 600쯤으로 봐요","mis":"M3-2-u1-X12"}],"explanation":["207에 가까운 몇백은 200이에요.","200 × 2 = 400이에요.","실제 곱 414는 어림한 400과 가까워요."],"asset":null},{"stem":"116 × 5를 계산하기 전에 어림하려고 해요. 어떻게 어림하는 것이 알맞은가요?","options":[{"t":"100 × 5 = 500쯤으로 봐요","correct":true},{"t":"1 × 5 = 5쯤으로 봐요","mis":"M3-2-u1-X06"},{"t":"116 + 5 = 121쯤으로 봐요","mis":"M3-2-u1-X13"},{"t":"200 × 5 = 1000쯤으로 봐요","mis":"M3-2-u1-X12"}],"explanation":["116에 가까운 몇백은 100이에요.","100 × 5 = 500이에요.","실제 곱 580은 어림한 500과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_basic#10','math',3,2,'u1','L03','g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C2',3,'error','auto','132 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X02','M3-2-u1-X15']::text[],true,'{"seq":10,"concept":"M3-2-u1-C2","difficulty":3,"kind":"error","stem":"132 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「132 × 4 = 428이야」","correct":true,"mis_target":"M3-2-u1-X02"},{"t":"하랑 — 「132 × 4 = 528이야」","mis":"M3-2-u1-X15"},{"t":"지유 — 「어림하면 약 400이야」","mis":"M3-2-u1-X15"}],"explanation":["십의 자리 3 × 4 = 12 → 1 올림.","132 × 4 = 528이에요.","시우는 428로 잘못 구했어요 — 작게 적은 수에 동그라미."],"variant_rule":{"alt":[{"stem":"180 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「180 × 2 = 260이야」","correct":true,"mis_target":"M3-2-u1-X02"},{"t":"도윤 — 「180 × 2 = 360이야」","mis":"M3-2-u1-X15"},{"t":"지유 — 「2 × 180 = 360이야」","mis":"M3-2-u1-X15"}],"explanation":["십의 자리 8 × 2 = 16 → 1 올림.","180 × 2 = 360이에요.","하린은 260으로 잘못 구했어요 — 작게 적은 수에 동그라미."],"asset":null},{"stem":"283 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「283 × 3 = 649야」","correct":true,"mis_target":"M3-2-u1-X02"},{"t":"도윤 — 「283 × 3 = 849야」","mis":"M3-2-u1-X15"},{"t":"서윤 — 「어림하면 약 900이야」","mis":"M3-2-u1-X15"}],"explanation":["십의 자리 8 × 3 = 24 → 2 올림.","283 × 3 = 849예요.","하랑은 649로 잘못 구했어요 — 작게 적은 수에 동그라미."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_challenge#1','math',3,2,'u1','L03','g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',2,'sa','auto','132 × 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C2","difficulty":2,"kind":"sa","stem":"132 × 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 3 × 4 = 12 → 2를 써요.","132 × 4 = 528 — 십의 자리 숫자는 2예요."],"asset":{"type":"expr_grid","rows":[["올림","","1","",""],["","","1","3","2"],["×","","","","4"],["","","5",null,"8"]]},"variant_rule":{"alt":[{"stem":"274 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 7 × 2 = 14 → 4를 써요.","274 × 2 = 548 — 십의 자리 숫자는 4예요."],"asset":{"type":"expr_grid","rows":[["올림","","1","",""],["","","2","7","4"],["×","","","","2"],["","","5",null,"8"]]}},{"stem":"453 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["9"],"explanation":["세로셈은 일의 자리부터 곱해요.","백의 자리: 4 × 2 + 올림 1 = 9 → 9를 써요.","453 × 2 = 906 — 백의 자리 숫자는 9예요."],"asset":{"type":"expr_grid","rows":[["올림","","1","",""],["","","4","5","3"],["×","","","","2"],["","",null,"0","6"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_challenge#2','math',3,2,'u1','L03','g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C3',2,'ox','auto','106 × 8을 계산했더니 148이 나왔어요. 어림해 보면 알맞은 답이에요.',ARRAY['M3-2-u1-X12']::text[],true,'{"seq":2,"concept":"M3-2-u1-C3","difficulty":2,"kind":"ox","stem":"106 × 8을 계산했더니 148이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 800과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u1-X12"}],"mis":"M3-2-u1-X12","explanation":["106 × 8을 어림하면 100 × 8 = 800이에요.","148은 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 106 × 8 = 848이에요."],"variant_rule":{"alt":[{"stem":"105 × 6을 계산했더니 130이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 600과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u1-X12"}],"explanation":["105 × 6을 어림하면 100 × 6 = 600이에요.","130은 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 105 × 6 = 630이에요."],"asset":null},{"stem":"108 × 8을 계산했더니 164가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 800과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u1-X12"}],"explanation":["108 × 8을 어림하면 100 × 8 = 800이에요.","164는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 108 × 8 = 864예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_challenge#3','math',3,2,'u1','L03','g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',3,'sa','auto','282 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C2","difficulty":3,"kind":"sa","stem":"282 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["564"],"explanation":["282를 200, 80, 2로 갈라 곱해요: 200 × 2 = 400, 80 × 2 = 160, 2 × 2 = 4.","십의 자리 8 × 2 = 16 → 1 올림.","400 + 160 + 4 = 564 — 어림한 300 × 2 = 600과 가까워요."],"variant_rule":{"alt":[{"stem":"460 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["920"],"explanation":["460을 400, 60, 0으로 갈라 곱해요: 400 × 2 = 800, 60 × 2 = 120, 0 × 2 = 0.","십의 자리 6 × 2 = 12 → 1 올림.","800 + 120 + 0 = 920 — 어림한 500 × 2 = 1000과 가까워요."],"asset":null},{"stem":"142 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["568"],"explanation":["142를 100, 40, 2로 갈라 곱해요: 100 × 4 = 400, 40 × 4 = 160, 2 × 4 = 8.","십의 자리 4 × 4 = 16 → 1 올림.","400 + 160 + 8 = 568 — 어림한 100 × 4 = 400과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_challenge#4','math',3,2,'u1','L03','g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',3,'mc','auto','곱을 견주어 ○ 안에 알맞은 것을 고르세요. 316 × 3 ○ 108 × 8',ARRAY['M3-2-u1-X11','M3-2-u1-X15']::text[],true,'{"seq":4,"concept":"M3-2-u1-C2","difficulty":3,"kind":"mc","stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 316 × 3 ○ 108 × 8","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["316 × 3 = 948이에요.","108 × 8 = 864예요.","948 > 864 — 알맞은 것은 >예요."],"variant_rule":{"alt":[{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 109 × 4 ○ 217 × 2","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["109 × 4 = 436이에요.","217 × 2 = 434예요.","436 > 434 — 알맞은 것은 >예요."],"asset":null},{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 213 × 4 ○ 416 × 2","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["213 × 4 = 852예요.","416 × 2 = 832예요.","852 > 832 — 알맞은 것은 >예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_challenge#5','math',3,2,'u1','L03','g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',3,'error','auto','217 × 2를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?',ARRAY['M3-2-u1-X03','M3-2-u1-X15']::text[],true,'{"seq":5,"concept":"M3-2-u1-C2","difficulty":3,"kind":"error","stem":"217 × 2를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"지유 — 「올림한 1을 십의 자리 1에 먼저 더해 2 × 2 — 답은 444야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"하랑 — 「200, 10, 7 자리마다 2를 곱해 더하면 434야」","mis":"M3-2-u1-X15"},{"t":"하린 — 「일의 자리부터 곱하고 올림한 수는 윗자리를 곱한 다음 더해 434야」","mis":"M3-2-u1-X15"}],"explanation":["올림한 수는 윗자리를 곱한 다음에 더해요.","일의 자리 7 × 2 = 14 → 1 올림.","지유는 먼저 더하고 곱해 444가 나왔어요 — 바른 답은 434예요."],"variant_rule":{"alt":[{"stem":"207 × 3을 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"서윤 — 「올림한 2를 십의 자리 0에 먼저 더해 2 × 3 — 답은 661이야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"하랑 — 「200, 0, 7 자리마다 3을 곱해 더하면 621이야」","mis":"M3-2-u1-X15"},{"t":"하린 — 「일의 자리부터 곱하고 올림한 수는 윗자리를 곱한 다음 더해 621이야」","mis":"M3-2-u1-X15"}],"explanation":["올림한 수는 윗자리를 곱한 다음에 더해요.","일의 자리 7 × 3 = 21 → 2 올림.","서윤은 먼저 더하고 곱해 661이 나왔어요 — 바른 답은 621이에요."],"asset":null},{"stem":"108 × 2를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하린 — 「올림한 1을 십의 자리 0에 먼저 더해 1 × 2 — 답은 226이야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"시우 — 「100, 0, 8 자리마다 2를 곱해 더하면 216이야」","mis":"M3-2-u1-X15"},{"t":"태오 — 「일의 자리부터 곱하고 올림한 수는 윗자리를 곱한 다음 더해 216이야」","mis":"M3-2-u1-X15"}],"explanation":["올림한 수는 윗자리를 곱한 다음에 더해요.","일의 자리 8 × 2 = 16 → 1 올림.","하린은 먼저 더하고 곱해 226이 나왔어요 — 바른 답은 216이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, h