INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_challenge#6','math',3,2,'u1','L03','g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',3,'sa','auto','□14 × 6 = 684 — □에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u1-C2","difficulty":3,"kind":"sa","stem":"□14 × 6 = 684 — □에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["곱 684의 백의 자리를 봐요.","□ × 6이 백의 자리 곱 6이 되어야 해요.","□ = 1 — 114 × 6 = 684예요."],"variant_rule":{"alt":[{"stem":"10□ × 2 = 216 — □에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["곱 216의 일의 자리를 봐요.","□ × 2가 일의 자리 곱 16이 되어야 해요.","□ = 8 — 108 × 2 = 216이에요."],"asset":null},{"stem":"1□5 × 4 = 460 — □에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["곱 460의 십의 자리를 봐요.","□ × 4가 십의 자리 곱 4가 되어야 해요.","□ = 1 — 115 × 4 = 460이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_challenge#7','math',3,2,'u1','L03','g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',3,'match','auto','곱셈식과 곱을 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u1-C2","difficulty":3,"kind":"match","stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"241 × 3","r":"723"},{"l":"260 × 3","r":"780"},{"l":"182 × 4","r":"728"}],"mis":"M3-2-u1-X02","explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","241 × 3 = 723, 260 × 3 = 780, 182 × 4 = 728.","어림한 값과 가까운지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"140 × 6","r":"840"},{"l":"180 × 2","r":"360"},{"l":"191 × 4","r":"764"}],"explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","140 × 6 = 840, 180 × 2 = 360, 191 × 4 = 764.","어림한 값과 가까운지 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"191 × 4","r":"764"},{"l":"260 × 2","r":"520"},{"l":"141 × 7","r":"987"}],"explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","191 × 4 = 764, 260 × 2 = 520, 141 × 7 = 987.","어림한 값과 가까운지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_challenge#8','math',3,2,'u1','L03','g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',4,'essay','teacher','블루베리가 한 상자에 217개씩 2상자 있어요. 217 × 2를 계산하기 전에 어림하고, 세로셈으로 계산하는 방법을 쓴 뒤 어림한 값과 견주어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C2","difficulty":4,"kind":"essay","stem":"블루베리가 한 상자에 217개씩 2상자 있어요. 217 × 2를 계산하기 전에 어림하고, 세로셈으로 계산하는 방법을 쓴 뒤 어림한 값과 견주어 보세요.","answer_guide":{"answer":"예: 217을 200쯤으로 보면 200 × 2 = 400이다. 일의 자리 7 × 2 = 14에서 4를 쓰고 1을 십의 자리 위에 작게 적는다. 십의 자리 1 × 2 = 2에 1을 더해 3, 백의 자리 2 × 2 = 4를 쓴다. 답은 434개이고 어림한 400과 가깝다.","scoring_points":["200 × 2 = 400으로 어림했는가","7 × 2 = 14에서 1을 올려 십의 자리 곱에 더했는가","434를 구하고 어림과 견주었는가"]},"explanation":["어림 약 400.","7 × 2 = 14 → 4 쓰고 1 올림, 1 × 2 + 1 = 3.","217 × 2 = 434 — 400과 가까워요."],"asset":{"type":"expr_grid","rows":[["올림","","","1",""],["","","2","1","7"],["×","","","","2"],["","","4","3","4"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_challenge#9','math',3,2,'u1','L03','g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',4,'essay','teacher','하린이는 132 × 4를 428이라고 했어요. 하린이가 무엇을 빠뜨렸는지 찾고 바른 답을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u1-C2","difficulty":4,"kind":"essay","stem":"하린이는 132 × 4를 428이라고 했어요. 하린이가 무엇을 빠뜨렸는지 찾고 바른 답을 구해 보세요.","answer_guide":{"answer":"예: 십의 자리 3 × 4 = 12에서 백의 자리로 올림한 1을 백의 자리 곱 1 × 4 = 4에 더하지 않았다. 4 + 1 = 5이므로 바른 답은 528이다. 어림하면 100 × 4 = 400보다 크다.","scoring_points":["십의 자리에서 올림한 1을 빠뜨렸다고 찾았는가","백의 자리를 4 + 1 = 5로 고쳤는가","528을 구했는가"]},"explanation":["3 × 4 = 12 → 백의 자리로 1 올림.","1 × 4 + 1 = 5.","132 × 4 = 528."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L03_challenge#10','math',3,2,'u1','L03','g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',4,'sa','auto','하루에 241쪽씩 3일 동안 책을 읽었어요. 모두 몇 쪽을 읽었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u1-C2","difficulty":4,"kind":"sa","stem":"하루에 241쪽씩 3일 동안 책을 읽었어요. 모두 몇 쪽을 읽었나요? 숫자로 쓰세요.","answer":["723"],"explanation":["241쪽씩 3번(묶음) — 곱셈식 241 × 3으로 세워요.","십의 자리 4 × 3 = 12 → 1 올림.","241 × 3 = 723 — 모두 723쪽이에요."],"variant_rule":{"alt":[{"stem":"한 개에 283원인 지우개를 2개 샀어요. 모두 얼마인가요? 숫자로 쓰세요.","answer":["566"],"explanation":["283원씩 2번(묶음) — 곱셈식 283 × 2로 세워요.","십의 자리 8 × 2 = 16 → 1 올림.","283 × 2 = 566 — 모두 566원이에요."],"asset":null},{"stem":"감자를 한 자루에 461개씩 2자루에 담았어요. 감자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["922"],"explanation":["461개씩 2번(묶음) — 곱셈식 461 × 2로 세워요.","십의 자리 6 × 2 = 12 → 1 올림.","461 × 2 = 922 — 모두 922개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_basic#1','math',3,2,'u1','L04','g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',1,'sa','auto','426 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C4","difficulty":1,"kind":"sa","stem":"426 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["1278"],"explanation":["426을 400, 20, 6으로 갈라 곱해요: 400 × 3 = 1200, 20 × 3 = 60, 6 × 3 = 18.","일의 자리 6 × 3 = 18 → 1 올림, 백의 자리 4 × 3 = 12 → 천의 자리.","1200 + 60 + 18 = 1278 — 어림한 400 × 3 = 1200과 가까워요."],"variant_rule":{"alt":[{"stem":"718 × 7은 얼마인가요? 숫자로 쓰세요.","answer":["5026"],"explanation":["718을 700, 10, 8로 갈라 곱해요: 700 × 7 = 4900, 10 × 7 = 70, 8 × 7 = 56.","일의 자리 8 × 7 = 56 → 5 올림, 십의 자리 1 × 7 + 5 = 12 → 1 올림, 백의 자리 7 × 7 + 1 = 50 → 천의 자리.","4900 + 70 + 56 = 5026 — 어림한 700 × 7 = 4900과 가까워요."],"asset":null},{"stem":"972 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["2916"],"explanation":["972를 900, 70, 2로 갈라 곱해요: 900 × 3 = 2700, 70 × 3 = 210, 2 × 3 = 6.","십의 자리 7 × 3 = 21 → 2 올림, 백의 자리 9 × 3 + 2 = 29 → 천의 자리.","2700 + 210 + 6 = 2916 — 어림한 1000 × 3 = 3000과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_basic#2','math',3,2,'u1','L04','g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',1,'mc','auto','274 × 7은 얼마인가요?',ARRAY['M3-2-u1-X03','M3-2-u1-X02']::text[],true,'{"seq":2,"concept":"M3-2-u1-C4","difficulty":1,"kind":"mc","stem":"274 × 7은 얼마인가요?","options":[{"t":"1918","correct":true},{"t":"2038","mis":"M3-2-u1-X03"},{"t":"4918","mis":"M3-2-u1-X03"},{"t":"1898","mis":"M3-2-u1-X02"}],"explanation":["274를 200, 70, 4로 갈라 곱해요: 200 × 7 = 1400, 70 × 7 = 490, 4 × 7 = 28.","일의 자리 4 × 7 = 28 → 2 올림, 십의 자리 7 × 7 + 2 = 51 → 5 올림, 백의 자리 2 × 7 + 5 = 19 → 천의 자리.","1400 + 490 + 28 = 1918 — 어림한 300 × 7 = 2100과 가까워요."],"variant_rule":{"alt":[{"stem":"623 × 9는 얼마인가요?","options":[{"t":"5607","correct":true},{"t":"5767","mis":"M3-2-u1-X03"},{"t":"7207","mis":"M3-2-u1-X03"},{"t":"5587","mis":"M3-2-u1-X02"}],"explanation":["623을 600, 20, 3으로 갈라 곱해요: 600 × 9 = 5400, 20 × 9 = 180, 3 × 9 = 27.","일의 자리 3 × 9 = 27 → 2 올림, 십의 자리 2 × 9 + 2 = 20 → 2 올림, 백의 자리 6 × 9 + 2 = 56 → 천의 자리.","5400 + 180 + 27 = 5607 — 어림한 600 × 9 = 5400과 가까워요."],"asset":null},{"stem":"986 × 8은 얼마인가요?","options":[{"t":"7888","correct":true},{"t":"8168","mis":"M3-2-u1-X03"},{"t":"12088","mis":"M3-2-u1-X03"},{"t":"7848","mis":"M3-2-u1-X02"}],"explanation":["986을 900, 80, 6으로 갈라 곱해요: 900 × 8 = 7200, 80 × 8 = 640, 6 × 8 = 48.","일의 자리 6 × 8 = 48 → 4 올림, 십의 자리 8 × 8 + 4 = 68 → 6 올림, 백의 자리 9 × 8 + 6 = 78 → 천의 자리.","7200 + 640 + 48 = 7888 — 어림한 1000 × 8 = 8000과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_basic#3','math',3,2,'u1','L04','g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',1,'sa','auto','426 × 3의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C4","difficulty":1,"kind":"sa","stem":"426 × 3의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["백의 자리 곱 4 × 3 = 12예요.","10을 넘은 1이 천의 자리로 가요.","426 × 3 = 1278 — 천의 자리 숫자는 1이에요."],"variant_rule":{"alt":[{"stem":"437 × 7의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["백의 자리 곱 4 × 7 + 올림 2 = 30이에요.","10을 넘은 3이 천의 자리로 가요.","437 × 7 = 3059 — 천의 자리 숫자는 3이에요."],"asset":null},{"stem":"791 × 5의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["백의 자리 곱 7 × 5 + 올림 4 = 39예요.","10을 넘은 3이 천의 자리로 가요.","791 × 5 = 3955 — 천의 자리 숫자는 3이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_basic#4','math',3,2,'u1','L04','g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C3',1,'mc','auto','426 × 3을 어림하면 약 얼마인가요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],true,'{"seq":4,"concept":"M3-2-u1-C3","difficulty":1,"kind":"mc","stem":"426 × 3을 어림하면 약 얼마인가요?","options":[{"t":"약 1200","correct":true},{"t":"약 900","mis":"M3-2-u1-X12"},{"t":"약 403","mis":"M3-2-u1-X12"},{"t":"약 12000","mis":"M3-2-u1-X06"}],"explanation":["426은 가까운 몇백 400으로 어림해요.","400 × 3 = 1200이에요.","그래서 약 1200이에요 — 실제 곱 1278과 가까워요."],"variant_rule":{"alt":[{"stem":"390 × 6을 어림하면 약 얼마인가요?","options":[{"t":"약 2400","correct":true},{"t":"약 3000","mis":"M3-2-u1-X12"},{"t":"약 406","mis":"M3-2-u1-X12"},{"t":"약 24000","mis":"M3-2-u1-X06"}],"explanation":["390은 가까운 몇백 400으로 어림해요.","400 × 6 = 2400이에요.","그래서 약 2400이에요 — 실제 곱 2340과 가까워요."],"asset":null},{"stem":"867 × 6을 어림하면 약 얼마인가요?","options":[{"t":"약 5400","correct":true},{"t":"약 6000","mis":"M3-2-u1-X12"},{"t":"약 906","mis":"M3-2-u1-X12"},{"t":"약 54000","mis":"M3-2-u1-X06"}],"explanation":["867은 가까운 몇백 900으로 어림해요.","900 × 6 = 5400이에요.","그래서 약 5400이에요 — 실제 곱 5202와 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_basic#5','math',3,2,'u1','L04','g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',2,'sa','auto','274 × 7의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C4","difficulty":2,"kind":"sa","stem":"274 × 7의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["세로셈은 일의 자리부터 곱해요.","백의 자리 2 × 7 + 5 = 19가 10을 넘어 천의 자리에 1을 써요.","274 × 7 = 1918 — 천의 자리 숫자는 1이에요."],"asset":{"type":"expr_grid","rows":[["올림","","5","2",""],["","","2","7","4"],["×","","","","7"],["",null,"9","1","8"]]},"variant_rule":{"alt":[{"stem":"976 × 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 7 × 3 + 올림 1 = 22 → 2를 써요.","976 × 3 = 2928 — 십의 자리 숫자는 2예요."],"asset":{"type":"expr_grid","rows":[["올림","","2","1",""],["","","9","7","6"],["×","","","","3"],["","2","9",null,"8"]]}},{"stem":"575 × 6의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["5"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 7 × 6 + 올림 3 = 45 → 5를 써요.","575 × 6 = 3450 — 십의 자리 숫자는 5예요."],"asset":{"type":"expr_grid","rows":[["올림","","4","3",""],["","","5","7","5"],["×","","","","6"],["","3","4",null,"0"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_basic#6','math',3,2,'u1','L04','g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',2,'mc','auto','방울토마토를 한 상자에 136개씩 4상자에 담았어요. 방울토마토는 모두 몇 개인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X03']::text[],true,'{"seq":6,"concept":"M3-2-u1-C4","difficulty":2,"kind":"mc","stem":"방울토마토를 한 상자에 136개씩 4상자에 담았어요. 방울토마토는 모두 몇 개인가요?","options":[{"t":"544개","correct":true},{"t":"140개","mis":"M3-2-u1-X13"},{"t":"604개","mis":"M3-2-u1-X03"},{"t":"844개","mis":"M3-2-u1-X03"}],"explanation":["136개씩 4번(묶음) — 곱셈식 136 × 4로 세워요.","일의 자리 6 × 4 = 24 → 2 올림, 십의 자리 3 × 4 + 2 = 14 → 1 올림.","136 × 4 = 544 — 모두 544개예요."],"variant_rule":{"alt":[{"stem":"하루에 863쪽씩 5일 동안 책을 읽었어요. 모두 몇 쪽을 읽었나요?","options":[{"t":"4315쪽","correct":true},{"t":"868쪽","mis":"M3-2-u1-X13"},{"t":"4355쪽","mis":"M3-2-u1-X03"},{"t":"5515쪽","mis":"M3-2-u1-X03"}],"explanation":["863쪽씩 5번(묶음) — 곱셈식 863 × 5로 세워요.","일의 자리 3 × 5 = 15 → 1 올림, 십의 자리 6 × 5 + 1 = 31 → 3 올림, 백의 자리 8 × 5 + 3 = 43 → 천의 자리.","863 × 5 = 4315 — 모두 4315쪽이에요."],"asset":null},{"stem":"한 개에 292원인 지우개를 6개 샀어요. 모두 얼마인가요?","options":[{"t":"1752원","correct":true},{"t":"298원","mis":"M3-2-u1-X13"},{"t":"1802원","mis":"M3-2-u1-X03"},{"t":"4252원","mis":"M3-2-u1-X03"}],"explanation":["292원씩 6번(묶음) — 곱셈식 292 × 6으로 세워요.","일의 자리 2 × 6 = 12 → 1 올림, 십의 자리 9 × 6 + 1 = 55 → 5 올림, 백의 자리 2 × 6 + 5 = 17 → 천의 자리.","292 × 6 = 1752 — 모두 1752원이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_basic#7','math',3,2,'u1','L04','g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',2,'ox','auto','274 × 7을 계산하는데 2 × 7 = 14, 7 × 7 = 49, 4 × 7 = 28을 차례로 이어 붙여 144928이라고 했어요. 바르게 계산했어요.',ARRAY['M3-2-u1-X04']::text[],true,'{"seq":7,"concept":"M3-2-u1-C4","difficulty":2,"kind":"ox","stem":"274 × 7을 계산하는데 2 × 7 = 14, 7 × 7 = 49, 4 × 7 = 28을 차례로 이어 붙여 144928이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"10이 넘는 곱은 윗자리로 올려 더해야 해서","correct":true},{"t":"자리마다 곱한 값을 그대로 이어 쓰면 되어서","mis":"M3-2-u1-X04"}],"mis":"M3-2-u1-X04","explanation":["일의 자리 4 × 7 = 28 → 2 올림, 십의 자리 7 × 7 + 2 = 51 → 5 올림, 백의 자리 2 × 7 + 5 = 19 → 천의 자리.","274 × 7 = 1918이에요.","어림하면 약 2100 — 144928은 터무니없이 커요."],"variant_rule":{"alt":[{"stem":"657 × 2를 계산하는데 6 × 2 = 12, 5 × 2 = 10, 7 × 2 = 14를 차례로 이어 붙여 121014라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"10이 넘는 곱은 윗자리로 올려 더해야 해서","correct":true},{"t":"자리마다 곱한 값을 그대로 이어 쓰면 되어서","mis":"M3-2-u1-X04"}],"explanation":["일의 자리 7 × 2 = 14 → 1 올림, 십의 자리 5 × 2 + 1 = 11 → 1 올림, 백의 자리 6 × 2 + 1 = 13 → 천의 자리.","657 × 2 = 1314예요.","어림하면 약 1400 — 121014는 터무니없이 커요."],"asset":null},{"stem":"795 × 8을 계산하는데 7 × 8 = 56, 9 × 8 = 72, 5 × 8 = 40을 차례로 이어 붙여 567240이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"10이 넘는 곱은 윗자리로 올려 더해야 해서","correct":true},{"t":"자리마다 곱한 값을 그대로 이어 쓰면 되어서","mis":"M3-2-u1-X04"}],"explanation":["일의 자리 5 × 8 = 40 → 4 올림, 십의 자리 9 × 8 + 4 = 76 → 7 올림, 백의 자리 7 × 8 + 7 = 63 → 천의 자리.","795 × 8 = 6360이에요.","어림하면 약 6400 — 567240은 터무니없이 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_basic#8','math',3,2,'u1','L04','g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',2,'mc','auto','417 × 5를 자리마다 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?',ARRAY['M3-2-u1-X08','M3-2-u1-X04']::text[],true,'{"seq":8,"concept":"M3-2-u1-C4","difficulty":2,"kind":"mc","stem":"417 × 5를 자리마다 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?","options":[{"t":"2085","correct":true},{"t":"2000","mis":"M3-2-u1-X08"},{"t":"2050","mis":"M3-2-u1-X08"},{"t":"20535","mis":"M3-2-u1-X04"}],"explanation":["자리마다 곱한 세 값을 모두 더해요.","2000 + 50 + 35 = 2085예요.","하나라도 빠뜨리면 417 × 5의 일부만 구한 거예요."],"asset":{"type":"expr_grid","rows":[["400 × 5","=","2000"],["10 × 5","=","50"],["7 × 5","=","35"],["2000 + 50 + 35","=",null]]},"variant_rule":{"alt":[{"stem":"424 × 9를 자리마다 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?","options":[{"t":"3816","correct":true},{"t":"3600","mis":"M3-2-u1-X08"},{"t":"3780","mis":"M3-2-u1-X08"},{"t":"361836","mis":"M3-2-u1-X04"}],"explanation":["자리마다 곱한 세 값을 모두 더해요.","3600 + 180 + 36 = 3816이에요.","하나라도 빠뜨리면 424 × 9의 일부만 구한 거예요."],"asset":{"type":"expr_grid","rows":[["400 × 9","=","3600"],["20 × 9","=","180"],["4 × 9","=","36"],["3600 + 180 + 36","=",null]]}},{"stem":"443 × 9를 자리마다 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?","options":[{"t":"3987","correct":true},{"t":"3600","mis":"M3-2-u1-X08"},{"t":"3960","mis":"M3-2-u1-X08"},{"t":"363627","mis":"M3-2-u1-X04"}],"explanation":["자리마다 곱한 세 값을 모두 더해요.","3600 + 360 + 27 = 3987이에요.","하나라도 빠뜨리면 443 × 9의 일부만 구한 거예요."],"asset":{"type":"expr_grid","rows":[["400 × 9","=","3600"],["40 × 9","=","360"],["3 × 9","=","27"],["3600 + 360 + 27","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_basic#9','math',3,2,'u1','L04','g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',2,'mc','auto','곱이 네 자리 수인 것은 어느 것인가요?',ARRAY['M3-2-u1-X02']::text[],true,'{"seq":9,"concept":"M3-2-u1-C4","difficulty":2,"kind":"mc","stem":"곱이 네 자리 수인 것은 어느 것인가요?","options":[{"t":"426 × 3","correct":true},{"t":"330 × 2","mis":"M3-2-u1-X02"},{"t":"301 × 2","mis":"M3-2-u1-X02"},{"t":"109 × 5","mis":"M3-2-u1-X02"}],"explanation":["백의 자리 곱(올림 더해)이 10 이상이면 천의 자리가 생겨요.","426 × 3 = 1278 — 네 자리예요.","나머지는 330 × 2 = 660, 301 × 2 = 602, 109 × 5 = 545 — 세 자리예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱이 네 자리 수인 것은 어느 것인가요?","options":[{"t":"301 × 5","correct":true},{"t":"130 × 2","mis":"M3-2-u1-X02"},{"t":"332 × 3","mis":"M3-2-u1-X02"},{"t":"115 × 2","mis":"M3-2-u1-X02"}],"explanation":["백의 자리 곱(올림 더해)이 10 이상이면 천의 자리가 생겨요.","301 × 5 = 1505 — 네 자리예요.","나머지는 130 × 2 = 260, 332 × 3 = 996, 115 × 2 = 230 — 세 자리예요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱이 네 자리 수인 것은 어느 것인가요?","options":[{"t":"404 × 6","correct":true},{"t":"221 × 3","mis":"M3-2-u1-X02"},{"t":"330 × 3","mis":"M3-2-u1-X02"},{"t":"304 × 3","mis":"M3-2-u1-X02"}],"explanation":["백의 자리 곱(올림 더해)이 10 이상이면 천의 자리가 생겨요.","404 × 6 = 2424 — 네 자리예요.","나머지는 221 × 3 = 663, 330 × 3 = 990, 304 × 3 = 912 — 세 자리예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_basic#10','math',3,2,'u1','L04','g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',3,'error','auto','359 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X03','M3-2-u1-X15']::text[],true,'{"seq":10,"concept":"M3-2-u1-C4","difficulty":3,"kind":"error","stem":"359 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「359 × 7 = 2873이야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"지유 — 「359 × 7 = 2513이야」","mis":"M3-2-u1-X15"},{"t":"하랑 — 「7 × 359 = 2513이야」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 9 × 7 = 63 → 6 올림, 십의 자리 5 × 7 + 6 = 41 → 4 올림, 백의 자리 3 × 7 + 4 = 25 → 천의 자리.","359 × 7 = 2513이에요.","시우는 2873으로 잘못 구했어요 — 곱한 다음에 더하기."],"variant_rule":{"alt":[{"stem":"328 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「328 × 7 = 2596이야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"하랑 — 「328 × 7 = 2296이야」","mis":"M3-2-u1-X15"},{"t":"지유 — 「어림하면 약 2100이야」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 8 × 7 = 56 → 5 올림, 십의 자리 2 × 7 + 5 = 19 → 1 올림, 백의 자리 3 × 7 + 1 = 22 → 천의 자리.","328 × 7 = 2296이에요.","은우는 2596으로 잘못 구했어요 — 곱한 다음에 더하기."],"asset":null},{"stem":"529 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「529 × 8 = 4722야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"은우 — 「529 × 8 = 4232야」","mis":"M3-2-u1-X15"},{"t":"시우 — 「8 × 529 = 4232야」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 9 × 8 = 72 → 7 올림, 십의 자리 2 × 8 + 7 = 23 → 2 올림, 백의 자리 5 × 8 + 2 = 42 → 천의 자리.","529 × 8 = 4232예요.","하랑은 4722로 잘못 구했어요 — 곱한 다음에 더하기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_challenge#1','math',3,2,'u1','L04','g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',2,'ox','auto','136 × 4를 계산하는데 일의 자리에서 십의 자리로 올림한 2를 더하지 않고 524라고 했어요. 바르게 계산했어요.',ARRAY['M3-2-u1-X02']::text[],true,'{"seq":1,"concept":"M3-2-u1-C4","difficulty":2,"kind":"ox","stem":"136 × 4를 계산하는데 일의 자리에서 십의 자리로 올림한 2를 더하지 않고 524라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수는 윗자리를 곱한 다음 꼭 더해야 해서","correct":true},{"t":"올림한 수는 작게 적어 두기만 하면 되어서","mis":"M3-2-u1-X02"}],"mis":"M3-2-u1-X02","explanation":["일의 자리 6 × 4 = 24 → 2 올림, 십의 자리 3 × 4 + 2 = 14 → 1 올림.","136 × 4 = 544예요.","524는 올림한 2를 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["올림","","1","2",""],["","","1","3","6"],["×","","","","4"],["","",null,null,null]]},"variant_rule":{"alt":[{"stem":"936 × 3을 계산하는데 일의 자리에서 십의 자리로 올림한 1을 더하지 않고 2798이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수는 윗자리를 곱한 다음 꼭 더해야 해서","correct":true},{"t":"올림한 수는 작게 적어 두기만 하면 되어서","mis":"M3-2-u1-X02"}],"explanation":["일의 자리 6 × 3 = 18 → 1 올림, 십의 자리 3 × 3 + 1 = 10 → 1 올림, 백의 자리 9 × 3 + 1 = 28 → 천의 자리.","936 × 3 = 2808이에요.","2798은 올림한 1을 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["올림","","1","1",""],["","","9","3","6"],["×","","","","3"],["",null,null,null,null]]}},{"stem":"264 × 5를 계산하는데 일의 자리에서 십의 자리로 올림한 2를 더하지 않고 1300이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수는 윗자리를 곱한 다음 꼭 더해야 해서","correct":true},{"t":"올림한 수는 작게 적어 두기만 하면 되어서","mis":"M3-2-u1-X02"}],"explanation":["일의 자리 4 × 5 = 20 → 2 올림, 십의 자리 6 × 5 + 2 = 32 → 3 올림, 백의 자리 2 × 5 + 3 = 13 → 천의 자리.","264 × 5 = 1320이에요.","1300은 올림한 2를 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["올림","","3","2",""],["","","2","6","4"],["×","","","","5"],["",null,null,null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_challenge#2','math',3,2,'u1','L04','g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',2,'match','auto','곱셈식과 곱을 알맞게 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u1-C4","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"417 × 5","r":"2085"},{"l":"907 × 8","r":"7256"},{"l":"616 × 2","r":"1232"}],"mis":"M3-2-u1-X02","explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","417 × 5 = 2085, 907 × 8 = 7256, 616 × 2 = 1232.","어림한 값과 가까운지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"390 × 6","r":"2340"},{"l":"910 × 5","r":"4550"},{"l":"360 × 8","r":"2880"}],"explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","390 × 6 = 2340, 910 × 5 = 4550, 360 × 8 = 2880.","어림한 값과 가까운지 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"797 × 8","r":"6376"},{"l":"666 × 4","r":"2664"},{"l":"179 × 4","r":"716"}],"explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","797 × 8 = 6376, 666 × 4 = 2664, 179 × 4 = 716.","어림한 값과 가까운지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_challenge#3','math',3,2,'u1','L04','g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',3,'error','auto','189 × 2를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?',ARRAY['M3-2-u1-X03','M3-2-u1-X15']::text[],true,'{"seq":3,"concept":"M3-2-u1-C4","difficulty":3,"kind":"error","stem":"189 × 2를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하린 — 「올림한 1을 십의 자리 8에 먼저 더해 9 × 2 — 답은 388이야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"서윤 — 「100, 80, 9 자리마다 2를 곱해 더하면 378이야」","mis":"M3-2-u1-X15"},{"t":"지유 — 「일의 자리부터 곱하고 올림한 수는 윗자리를 곱한 다음 더해 378이야」","mis":"M3-2-u1-X15"}],"explanation":["올림한 수는 윗자리를 곱한 다음에 더해요.","일의 자리 9 × 2 = 18 → 1 올림, 십의 자리 8 × 2 + 1 = 17 → 1 올림.","하린은 먼저 더하고 곱해 388이 나왔어요 — 바른 답은 378이에요."],"variant_rule":{"alt":[{"stem":"925 × 9를 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"시우 — 「올림한 4를 십의 자리 2에 먼저 더해 6 × 9 — 답은 8645야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"하린 — 「900, 20, 5 자리마다 9를 곱해 더하면 8325야」","mis":"M3-2-u1-X15"},{"t":"태오 — 「일의 자리부터 곱하고 올림한 수는 윗자리를 곱한 다음 더해 8325야」","mis":"M3-2-u1-X15"}],"explanation":["올림한 수는 윗자리를 곱한 다음에 더해요.","일의 자리 5 × 9 = 45 → 4 올림, 십의 자리 2 × 9 + 4 = 22 → 2 올림, 백의 자리 9 × 9 + 2 = 83 → 천의 자리.","시우는 먼저 더하고 곱해 8645가 나왔어요 — 바른 답은 8325예요."],"asset":null},{"stem":"987 × 7을 세로셈으로 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"태오 — 「올림한 4를 십의 자리 8에 먼저 더해 12 × 7 — 답은 7149야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"하랑 — 「900, 80, 7 자리마다 7을 곱해 더하면 6909야」","mis":"M3-2-u1-X15"},{"t":"서윤 — 「일의 자리부터 곱하고 올림한 수는 윗자리를 곱한 다음 더해 6909야」","mis":"M3-2-u1-X15"}],"explanation":["올림한 수는 윗자리를 곱한 다음에 더해요.","일의 자리 7 × 7 = 49 → 4 올림, 십의 자리 8 × 7 + 4 = 60 → 6 올림, 백의 자리 9 × 7 + 6 = 69 → 천의 자리.","태오는 먼저 더하고 곱해 7149가 나왔어요 — 바른 답은 6909예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_challenge#4','math',3,2,'u1','L04','g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',3,'mc','auto','곱이 가장 큰 것은 어느 것인가요?',ARRAY['M3-2-u1-X15','M3-2-u1-X11']::text[],true,'{"seq":4,"concept":"M3-2-u1-C4","difficulty":3,"kind":"mc","stem":"곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"391 × 4","correct":true},{"t":"756 × 2","mis":"M3-2-u1-X15"},{"t":"343 × 4","mis":"M3-2-u1-X11"},{"t":"251 × 4","mis":"M3-2-u1-X11"}],"explanation":["하나씩 곱을 구해요.","391 × 4 = 1564, 756 × 2 = 1512, 343 × 4 = 1372, 251 × 4 = 1004.","곱이 가장 큰 것은 391 × 4 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"273 × 6","correct":true},{"t":"346 × 4","mis":"M3-2-u1-X11"},{"t":"294 × 3","mis":"M3-2-u1-X11"},{"t":"397 × 2","mis":"M3-2-u1-X15"}],"explanation":["하나씩 곱을 구해요.","273 × 6 = 1638, 346 × 4 = 1384, 294 × 3 = 882, 397 × 2 = 794.","곱이 가장 큰 것은 273 × 6 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"971 × 2","correct":true},{"t":"920 × 2","mis":"M3-2-u1-X15"},{"t":"517 × 2","mis":"M3-2-u1-X11"},{"t":"429 × 4","mis":"M3-2-u1-X11"}],"explanation":["하나씩 곱을 구해요.","971 × 2 = 1942, 920 × 2 = 1840, 517 × 2 = 1034, 429 × 4 = 1716.","곱이 가장 큰 것은 971 × 2 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_challenge#5','math',3,2,'u1','L04','g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',3,'mc','auto','수 카드 6, 4, 2, 3을 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 큰 곱셈식은 어느 것인가요?',ARRAY['M3-2-u1-X14','M3-2-u1-X15','M3-2-u1-X11']::text[],true,'{"seq":5,"concept":"M3-2-u1-C4","difficulty":3,"kind":"mc","stem":"수 카드 6, 4, 2, 3을 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 큰 곱셈식은 어느 것인가요?","options":[{"t":"432 × 6","correct":true},{"t":"643 × 2","mis":"M3-2-u1-X14"},{"t":"346 × 2","mis":"M3-2-u1-X15"},{"t":"342 × 6","mis":"M3-2-u1-X11"}],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 6을 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 432를 만들어요.","432 × 6 = 2592 — 큰 수를 백의 자리에 놓은 643 × 2 = 1286보다 커요."],"variant_rule":{"alt":[{"stem":"수 카드 5, 7, 4, 3을 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 큰 곱셈식은 어느 것인가요?","options":[{"t":"543 × 7","correct":true},{"t":"754 × 3","mis":"M3-2-u1-X14"},{"t":"457 × 3","mis":"M3-2-u1-X15"},{"t":"453 × 7","mis":"M3-2-u1-X11"}],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 7을 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 543을 만들어요.","543 × 7 = 3801 — 큰 수를 백의 자리에 놓은 754 × 3 = 2262보다 커요."],"asset":null},{"stem":"수 카드 8, 2, 4, 6을 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 큰 곱셈식은 어느 것인가요?","options":[{"t":"642 × 8","correct":true},{"t":"864 × 2","mis":"M3-2-u1-X14"},{"t":"468 × 2","mis":"M3-2-u1-X15"},{"t":"462 × 8","mis":"M3-2-u1-X11"}],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 8을 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 642를 만들어요.","642 × 8 = 5136 — 큰 수를 백의 자리에 놓은 864 × 2 = 1728보다 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_challenge#6','math',3,2,'u1','L04','g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C3',3,'ox','auto','359 × 7을 계산했더니 413이 나왔어요. 어림해 보면 알맞은 답이에요.',ARRAY['M3-2-u1-X12']::text[],true,'{"seq":6,"concept":"M3-2-u1-C3","difficulty":3,"kind":"ox","stem":"359 × 7을 계산했더니 413이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 2800과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u1-X12"}],"mis":"M3-2-u1-X12","explanation":["359 × 7을 어림하면 400 × 7 = 2800이에요.","413은 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 359 × 7 = 2513이에요."],"variant_rule":{"alt":[{"stem":"524 × 6을 계산했더니 544가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 3000과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u1-X12"}],"explanation":["524 × 6을 어림하면 500 × 6 = 3000이에요.","544는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 524 × 6 = 3144예요."],"asset":null},{"stem":"971 × 2를 계산했더니 972가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 2000과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u1-X12"}],"explanation":["971 × 2를 어림하면 1000 × 2 = 2000이에요.","972는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 971 × 2 = 1942예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_challenge#7','math',3,2,'u1','L04','g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',3,'sa','auto','하루에 359쪽씩 7일 동안 책을 읽었어요. 모두 몇 쪽을 읽었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u1-C4","difficulty":3,"kind":"sa","stem":"하루에 359쪽씩 7일 동안 책을 읽었어요. 모두 몇 쪽을 읽었나요? 숫자로 쓰세요.","answer":["2513"],"explanation":["359쪽씩 7번(묶음) — 곱셈식 359 × 7로 세워요.","일의 자리 9 × 7 = 63 → 6 올림, 십의 자리 5 × 7 + 6 = 41 → 4 올림, 백의 자리 3 × 7 + 4 = 25 → 천의 자리.","359 × 7 = 2513 — 모두 2513쪽이에요."],"variant_rule":{"alt":[{"stem":"한 개에 777원인 지우개를 6개 샀어요. 모두 얼마인가요? 숫자로 쓰세요.","answer":["4662"],"explanation":["777원씩 6번(묶음) — 곱셈식 777 × 6으로 세워요.","일의 자리 7 × 6 = 42 → 4 올림, 십의 자리 7 × 6 + 4 = 46 → 4 올림, 백의 자리 7 × 6 + 4 = 46 → 천의 자리.","777 × 6 = 4662 — 모두 4662원이에요."],"asset":null},{"stem":"감자를 한 자루에 293개씩 9자루에 담았어요. 감자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2637"],"explanation":["293개씩 9번(묶음) — 곱셈식 293 × 9로 세워요.","일의 자리 3 × 9 = 27 → 2 올림, 십의 자리 9 × 9 + 2 = 83 → 8 올림, 백의 자리 2 × 9 + 8 = 26 → 천의 자리.","293 × 9 = 2637 — 모두 2637개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_challenge#8','math',3,2,'u1','L04','g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',4,'essay','teacher','수 카드 6, 4, 2, 3을 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 크게 되는 곱셈식을 쓰고, 그렇게 놓은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C4","difficulty":4,"kind":"essay","stem":"수 카드 6, 4, 2, 3을 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 크게 되는 곱셈식을 쓰고, 그렇게 놓은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 432 × 6 = 2592. 곱하는 수는 세 자리 수의 모든 자리에 곱해지므로 가장 큰 수 6을 곱하는 수 자리에 놓고, 남은 4, 3, 2로 가장 큰 세 자리 수 432를 만든다. 643 × 2 = 1286보다 크다.","scoring_points":["432 × 6을 썼는가","가장 큰 수를 곱하는 수 자리에 놓은 까닭을 설명했는가","2592를 구했는가"]},"explanation":["곱하는 수는 모든 자리에 곱해져요.","6을 곱하는 수로, 남은 수로 432.","432 × 6 = 2592."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_challenge#9','math',3,2,'u1','L04','g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',4,'essay','teacher','274 × 7을 세로셈으로 계산하는 방법을 쓰고, 어느 자리에서 올림이 생기는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u1-C4","difficulty":4,"kind":"essay","stem":"274 × 7을 세로셈으로 계산하는 방법을 쓰고, 어느 자리에서 올림이 생기는지 설명해 보세요.","answer_guide":{"answer":"예: 일의 자리 4 × 7 = 28에서 8을 쓰고 2를 올린다. 십의 자리 7 × 7 = 49에 2를 더해 51, 1을 쓰고 5를 올린다. 백의 자리 2 × 7 = 14에 5를 더해 19, 9를 쓰고 천의 자리에 1을 쓴다. 답은 1918이다.","scoring_points":["일의 자리·십의 자리 올림을 차례로 처리했는가","올림한 수를 윗자리 곱 다음에 더했는가","1918을 구했는가"]},"explanation":["4 × 7 = 28 → 2 올림.","7 × 7 + 2 = 51 → 5 올림, 2 × 7 + 5 = 19.","274 × 7 = 1918."],"asset":{"type":"expr_grid","rows":[["올림","","5","2",""],["","","2","7","4"],["×","","","","7"],["","1","9","1","8"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L04_challenge#10','math',3,2,'u1','L04','g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',4,'sa','auto','수 카드 3, 5, 2, 7을 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u1-C4","difficulty":4,"kind":"sa","stem":"수 카드 3, 5, 2, 7을 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.","answer":["3724"],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 7을 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 532를 만들어요.","532 × 7 = 3724 — 큰 수를 백의 자리에 놓은 753 × 2 = 1506보다 커요."],"variant_rule":{"alt":[{"stem":"수 카드 4, 3, 6, 8을 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.","answer":["5144"],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 8을 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 643을 만들어요.","643 × 8 = 5144 — 큰 수를 백의 자리에 놓은 864 × 3 = 2592보다 커요."],"asset":null},{"stem":"수 카드 9, 2, 5, 3을 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.","answer":["4788"],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 9를 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 532를 만들어요.","532 × 9 = 4788 — 큰 수를 백의 자리에 놓은 953 × 2 = 1906보다 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_basic#1','math',3,2,'u1','L05','g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',1,'sa','auto','30 × 30은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C5","difficulty":1,"kind":"sa","stem":"30 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["900"],"explanation":["3 × 3 = 9예요.","30 × 3 = 90, 곱하는 수가 3에서 30으로 10배가 되면 곱도 10배예요.","30 × 30 = 90의 10배 = 900이에요."],"variant_rule":{"alt":[{"stem":"80 × 80은 얼마인가요? 숫자로 쓰세요.","answer":["6400"],"explanation":["8 × 8 = 64예요.","80 × 8 = 640, 곱하는 수가 8에서 80으로 10배가 되면 곱도 10배예요.","80 × 80 = 640의 10배 = 6400이에요."],"asset":null},{"stem":"80 × 70은 얼마인가요? 숫자로 쓰세요.","answer":["5600"],"explanation":["8 × 7 = 56이에요.","80 × 7 = 560, 곱하는 수가 7에서 70으로 10배가 되면 곱도 10배예요.","80 × 70 = 560의 10배 = 5600이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_basic#2','math',3,2,'u1','L05','g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',1,'sa','auto','14 × 2 = 28이에요. 그러면 14 × 20은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u1-C5","difficulty":1,"kind":"sa","stem":"14 × 2 = 28이에요. 그러면 14 × 20은 얼마인가요? 숫자로 쓰세요.","answer":["280"],"explanation":["곱하는 수 20은 2의 10배예요.","곱하는 수가 10배가 되면 곱도 10배가 돼요.","28의 10배 — 14 × 20 = 280이에요."],"variant_rule":{"alt":[{"stem":"72 × 8 = 576이에요. 그러면 72 × 80은 얼마인가요? 숫자로 쓰세요.","answer":["5760"],"explanation":["곱하는 수 80은 8의 10배예요.","곱하는 수가 10배가 되면 곱도 10배가 돼요.","576의 10배 — 72 × 80 = 5760이에요."],"asset":null},{"stem":"86 × 5 = 430이에요. 그러면 86 × 50은 얼마인가요? 숫자로 쓰세요.","answer":["4300"],"explanation":["곱하는 수 50은 5의 10배예요.","곱하는 수가 10배가 되면 곱도 10배가 돼요.","430의 10배 — 86 × 50 = 4300이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_basic#3','math',3,2,'u1','L05','g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',1,'sa','auto','32 × 30은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C5","difficulty":1,"kind":"sa","stem":"32 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["960"],"explanation":["곱하는 수 30의 0을 잠시 떼고 32 × 3 = 96이에요.","곱하는 수가 3에서 30으로 10배가 되면 곱도 10배예요.","32 × 30 = 96의 10배 = 960이에요."],"variant_rule":{"alt":[{"stem":"42 × 70은 얼마인가요? 숫자로 쓰세요.","answer":["2940"],"explanation":["곱하는 수 70의 0을 잠시 떼고 42 × 7 = 294예요.","곱하는 수가 7에서 70으로 10배가 되면 곱도 10배예요.","42 × 70 = 294의 10배 = 2940이에요."],"asset":null},{"stem":"33 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["990"],"explanation":["곱하는 수 30의 0을 잠시 떼고 33 × 3 = 99예요.","곱하는 수가 3에서 30으로 10배가 되면 곱도 10배예요.","33 × 30 = 99의 10배 = 990이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_basic#4','math',3,2,'u1','L05','g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',1,'mc','auto','40 × 20은 얼마인가요?',ARRAY['M3-2-u1-X06']::text[],true,'{"seq":4,"concept":"M3-2-u1-C5","difficulty":1,"kind":"mc","stem":"40 × 20은 얼마인가요?","options":[{"t":"800","correct":true},{"t":"80","mis":"M3-2-u1-X06"},{"t":"8","mis":"M3-2-u1-X06"},{"t":"8000","mis":"M3-2-u1-X06"}],"explanation":["4 × 2 = 8이에요.","40 × 2 = 80, 곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","40 × 20 = 80의 10배 = 800이에요."],"variant_rule":{"alt":[{"stem":"70 × 80은 얼마인가요?","options":[{"t":"5600","correct":true},{"t":"560","mis":"M3-2-u1-X06"},{"t":"56","mis":"M3-2-u1-X06"},{"t":"56000","mis":"M3-2-u1-X06"}],"explanation":["7 × 8 = 56이에요.","70 × 8 = 560, 곱하는 수가 8에서 80으로 10배가 되면 곱도 10배예요.","70 × 80 = 560의 10배 = 5600이에요."],"asset":null},{"stem":"40 × 60은 얼마인가요?","options":[{"t":"2400","correct":true},{"t":"240","mis":"M3-2-u1-X06"},{"t":"24","mis":"M3-2-u1-X06"},{"t":"24000","mis":"M3-2-u1-X06"}],"explanation":["4 × 6 = 24예요.","40 × 6 = 240, 곱하는 수가 6에서 60으로 10배가 되면 곱도 10배예요.","40 × 60 = 240의 10배 = 2400이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_basic#5','math',3,2,'u1','L05','g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',2,'ox','auto','30 × 30 = 90이에요.',ARRAY['M3-2-u1-X06']::text[],true,'{"seq":5,"concept":"M3-2-u1-C5","difficulty":2,"kind":"ox","stem":"30 × 30 = 90이에요.","answer":"X","reason_options":[{"t":"30 × 30은 30 × 3의 10배라서","correct":true},{"t":"0을 하나만 붙이면 되어서","mis":"M3-2-u1-X06"}],"mis":"M3-2-u1-X06","explanation":["30 × 3 = 90이에요.","곱하는 수가 3에서 30으로 10배가 되면 곱도 10배 — 900이에요.","90은 10배를 한 번 빠뜨린 답이에요."],"variant_rule":{"alt":[{"stem":"80 × 80 = 640이에요.","answer":"X","reason_options":[{"t":"80 × 80은 80 × 8의 10배라서","correct":true},{"t":"0을 하나만 붙이면 되어서","mis":"M3-2-u1-X06"}],"explanation":["80 × 8 = 640이에요.","곱하는 수가 8에서 80으로 10배가 되면 곱도 10배 — 6400이에요.","640은 10배를 한 번 빠뜨린 답이에요."],"asset":null},{"stem":"80 × 60 = 480이에요.","answer":"X","reason_options":[{"t":"80 × 60은 80 × 6의 10배라서","correct":true},{"t":"0을 하나만 붙이면 되어서","mis":"M3-2-u1-X06"}],"explanation":["80 × 6 = 480이에요.","곱하는 수가 6에서 60으로 10배가 되면 곱도 10배 — 4800이에요.","480은 10배를 한 번 빠뜨린 답이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_basic#6','math',3,2,'u1','L05','g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',2,'mc','auto','한 상자에 도넛이 12개씩 들어 있어요. 이런 상자가 40상자 있어요. 도넛은 모두 몇 개인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X06']::text[],true,'{"seq":6,"concept":"M3-2-u1-C5","difficulty":2,"kind":"mc","stem":"한 상자에 도넛이 12개씩 들어 있어요. 이런 상자가 40상자 있어요. 도넛은 모두 몇 개인가요?","options":[{"t":"480개","correct":true},{"t":"52개","mis":"M3-2-u1-X13"},{"t":"48개","mis":"M3-2-u1-X06"},{"t":"4800개","mis":"M3-2-u1-X06"}],"explanation":["12개씩 40번(묶음) — 곱셈식 12 × 40으로 세워요.","곱하는 수가 4에서 40으로 10배가 되면 곱도 10배예요.","12 × 40 = 480 — 모두 480개예요."],"variant_rule":{"alt":[{"stem":"당근을 한 줄에 79개씩 20줄 놓았어요. 당근은 모두 몇 개인가요?","options":[{"t":"1580개","correct":true},{"t":"99개","mis":"M3-2-u1-X13"},{"t":"158개","mis":"M3-2-u1-X06"},{"t":"15800개","mis":"M3-2-u1-X06"}],"explanation":["79개씩 20번(묶음) — 곱셈식 79 × 20으로 세워요.","곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","79 × 20 = 1580 — 모두 1580개예요."],"asset":null},{"stem":"견과류 과자를 한 판에 84개씩 40판 구웠어요. 과자는 모두 몇 개인가요?","options":[{"t":"3360개","correct":true},{"t":"124개","mis":"M3-2-u1-X13"},{"t":"336개","mis":"M3-2-u1-X06"},{"t":"33600개","mis":"M3-2-u1-X06"}],"explanation":["84개씩 40번(묶음) — 곱셈식 84 × 40으로 세워요.","곱하는 수가 4에서 40으로 10배가 되면 곱도 10배예요.","84 × 40 = 3360 — 모두 3360개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_basic#7','math',3,2,'u1','L05','g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',2,'mc','auto','32 × 30의 곱은 32 × 3의 곱의 몇 배인가요?',ARRAY['M3-2-u1-X06','M3-2-u1-X11']::text[],true,'{"seq":7,"concept":"M3-2-u1-C5","difficulty":2,"kind":"mc","stem":"32 × 30의 곱은 32 × 3의 곱의 몇 배인가요?","options":[{"t":"10배","correct":true},{"t":"100배","mis":"M3-2-u1-X06"},{"t":"2배","mis":"M3-2-u1-X11"},{"t":"같아요","mis":"M3-2-u1-X06"}],"explanation":["곱하는 수 30은 3의 10배예요.","곱하는 수가 10배면 곱도 10배.","32 × 3 = 96, 32 × 30 = 960 — 10배예요."],"variant_rule":{"alt":[{"stem":"12 × 20의 곱은 12 × 2의 곱의 몇 배인가요?","options":[{"t":"10배","correct":true},{"t":"100배","mis":"M3-2-u1-X06"},{"t":"2배","mis":"M3-2-u1-X11"},{"t":"같아요","mis":"M3-2-u1-X06"}],"explanation":["곱하는 수 20은 2의 10배예요.","곱하는 수가 10배면 곱도 10배.","12 × 2 = 24, 12 × 20 = 240 — 10배예요."],"asset":null},{"stem":"94 × 50의 곱은 94 × 5의 곱의 몇 배인가요?","options":[{"t":"10배","correct":true},{"t":"100배","mis":"M3-2-u1-X06"},{"t":"2배","mis":"M3-2-u1-X11"},{"t":"같아요","mis":"M3-2-u1-X06"}],"explanation":["곱하는 수 50은 5의 10배예요.","곱하는 수가 10배면 곱도 10배.","94 × 5 = 470, 94 × 50 = 4700 — 10배예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_basic#8','math',3,2,'u1','L05','g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',2,'match','auto','곱셈식과 곱을 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u1-C5","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"14 × 20","r":"280"},{"l":"44 × 80","r":"3520"},{"l":"72 × 60","r":"4320"}],"mis":"M3-2-u1-X06","explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","14 × 20 = 280, 44 × 80 = 3520, 72 × 60 = 4320.","어림한 값과 가까운지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"34 × 70","r":"2380"},{"l":"24 × 40","r":"960"},{"l":"65 × 70","r":"4550"}],"explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","34 × 70 = 2380, 24 × 40 = 960, 65 × 70 = 4550.","어림한 값과 가까운지 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"53 × 80","r":"4240"},{"l":"36 × 20","r":"720"},{"l":"18 × 90","r":"1620"}],"explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","53 × 80 = 4240, 36 × 20 = 720, 18 × 90 = 1620.","어림한 값과 가까운지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_basic#9','math',3,2,'u1','L05','g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',2,'mc','auto','14 × 20을 구하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M3-2-u1-X15']::text[],true,'{"seq":9,"concept":"M3-2-u1-C5","difficulty":2,"kind":"mc","stem":"14 × 20을 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"14 × 2 = 28에 0을 두 개 붙여요","correct":true},{"t":"14 × 2 = 28의 10배를 해요","mis":"M3-2-u1-X15"},{"t":"14 × 10 = 140의 2배를 해요","mis":"M3-2-u1-X15"},{"t":"20 × 14를 구해요","mis":"M3-2-u1-X15"}],"explanation":["14 × 2 = 28의 10배 = 280이에요.","14 × 10 = 140의 2배도 280이에요. 순서를 바꾼 20 × 14도 같아요.","0을 두 개 붙이면 2800 — 100배가 되어 틀려요."],"variant_rule":{"alt":[{"stem":"61 × 20을 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"61 × 2 = 122에 0을 두 개 붙여요","correct":true},{"t":"61 × 2 = 122의 10배를 해요","mis":"M3-2-u1-X15"},{"t":"61 × 10 = 610의 2배를 해요","mis":"M3-2-u1-X15"},{"t":"20 × 61을 구해요","mis":"M3-2-u1-X15"}],"explanation":["61 × 2 = 122의 10배 = 1220이에요.","61 × 10 = 610의 2배도 1220이에요. 순서를 바꾼 20 × 61도 같아요.","0을 두 개 붙이면 12200 — 100배가 되어 틀려요."],"asset":null},{"stem":"58 × 80을 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"58 × 8 = 464에 0을 두 개 붙여요","correct":true},{"t":"58 × 8 = 464의 10배를 해요","mis":"M3-2-u1-X15"},{"t":"58 × 10 = 580의 8배를 해요","mis":"M3-2-u1-X15"},{"t":"80 × 58을 구해요","mis":"M3-2-u1-X15"}],"explanation":["58 × 8 = 464의 10배 = 4640이에요.","58 × 10 = 580의 8배도 4640이에요. 순서를 바꾼 80 × 58도 같아요.","0을 두 개 붙이면 46400 — 100배가 되어 틀려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_basic#10','math',3,2,'u1','L05','g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',3,'error','auto','73 × 40을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X06','M3-2-u1-X15']::text[],true,'{"seq":10,"concept":"M3-2-u1-C5","difficulty":3,"kind":"error","stem":"73 × 40을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「73 × 40 = 292야」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"서윤 — 「73 × 40 = 2920이야」","mis":"M3-2-u1-X15"},{"t":"도윤 — 「40 × 73 = 2920이야」","mis":"M3-2-u1-X15"}],"explanation":["곱하는 수가 4에서 40으로 10배가 되면 곱도 10배예요.","73 × 40 = 2920이에요.","은우는 292로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배."],"variant_rule":{"alt":[{"stem":"46 × 40을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「46 × 40 = 184야」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"지유 — 「46 × 40 = 1840이야」","mis":"M3-2-u1-X15"},{"t":"시우 — 「어림하면 약 2000이야」","mis":"M3-2-u1-X15"}],"explanation":["곱하는 수가 4에서 40으로 10배가 되면 곱도 10배예요.","46 × 40 = 1840이에요.","하랑은 184로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배."],"asset":null},{"stem":"65 × 50을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「65 × 50 = 325야」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"지유 — 「65 × 50 = 3250이야」","mis":"M3-2-u1-X15"},{"t":"시우 — 「50 × 65 = 3250이야」","mis":"M3-2-u1-X15"}],"explanation":["곱하는 수가 5에서 50으로 10배가 되면 곱도 10배예요.","65 × 50 = 3250이에요.","은우는 325로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_challenge#1','math',3,2,'u1','L05','g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',2,'sa','auto','73 × 40은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C5","difficulty":2,"kind":"sa","stem":"73 × 40은 얼마인가요? 숫자로 쓰세요.","answer":["2920"],"explanation":["곱하는 수 40의 0을 잠시 떼고 73 × 4 = 292예요.","곱하는 수가 4에서 40으로 10배가 되면 곱도 10배예요.","73 × 40 = 292의 10배 = 2920이에요."],"variant_rule":{"alt":[{"stem":"64 × 40은 얼마인가요? 숫자로 쓰세요.","answer":["2560"],"explanation":["곱하는 수 40의 0을 잠시 떼고 64 × 4 = 256이에요.","곱하는 수가 4에서 40으로 10배가 되면 곱도 10배예요.","64 × 40 = 256의 10배 = 2560이에요."],"asset":null},{"stem":"61 × 70은 얼마인가요? 숫자로 쓰세요.","answer":["4270"],"explanation":["곱하는 수 70의 0을 잠시 떼고 61 × 7 = 427이에요.","곱하는 수가 7에서 70으로 10배가 되면 곱도 10배예요.","61 × 70 = 427의 10배 = 4270이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_challenge#2','math',3,2,'u1','L05','g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',2,'sa','auto','□ × 30 = 960 — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u1-C5","difficulty":2,"kind":"sa","stem":"□ × 30 = 960 — □에 알맞은 수를 쓰세요.","answer":["32"],"explanation":["30은 3의 10배예요.","그래서 □ × 3 = 960의 10분의 1인 96이에요.","□ × 3 = 96 → □ = 32 — 32 × 30 = 960이에요."],"variant_rule":{"alt":[{"stem":"□ × 70 = 6580 — □에 알맞은 수를 쓰세요.","answer":["94"],"explanation":["70은 7의 10배예요.","그래서 □ × 7 = 6580의 10분의 1인 658이에요.","□ × 7 = 658 → □ = 94 — 94 × 70 = 6580이에요."],"asset":null},{"stem":"□ × 40 = 2280 — □에 알맞은 수를 쓰세요.","answer":["57"],"explanation":["40은 4의 10배예요.","그래서 □ × 4 = 2280의 10분의 1인 228이에요.","□ × 4 = 228 → □ = 57 — 57 × 40 = 2280이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_challenge#3','math',3,2,'u1','L05','g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',3,'mc','auto','52 × 20, 26 × 40, 24 × 50 가운데 곱이 다른 하나는 어느 것인가요?',ARRAY['M3-2-u1-X11']::text[],true,'{"seq":3,"concept":"M3-2-u1-C5","difficulty":3,"kind":"mc","stem":"52 × 20, 26 × 40, 24 × 50 가운데 곱이 다른 하나는 어느 것인가요?","options":[{"t":"24 × 50","correct":true},{"t":"52 × 20","mis":"M3-2-u1-X11"},{"t":"26 × 40","mis":"M3-2-u1-X11"},{"t":"모두 같아요","mis":"M3-2-u1-X11"}],"explanation":["하나씩 몇의 10배로 구해요.","52 × 20 = 1040, 26 × 40 = 1040, 24 × 50 = 1200.","곱이 다른 것은 24 × 50예요."],"variant_rule":{"alt":[{"stem":"35 × 20, 14 × 50, 27 × 30 가운데 곱이 다른 하나는 어느 것인가요?","options":[{"t":"27 × 30","correct":true},{"t":"35 × 20","mis":"M3-2-u1-X11"},{"t":"14 × 50","mis":"M3-2-u1-X11"},{"t":"모두 같아요","mis":"M3-2-u1-X11"}],"explanation":["하나씩 몇의 10배로 구해요.","35 × 20 = 700, 14 × 50 = 700, 27 × 30 = 810.","곱이 다른 것은 27 × 30예요."],"asset":null},{"stem":"48 × 20, 32 × 30, 26 × 40 가운데 곱이 다른 하나는 어느 것인가요?","options":[{"t":"26 × 40","correct":true},{"t":"48 × 20","mis":"M3-2-u1-X11"},{"t":"32 × 30","mis":"M3-2-u1-X11"},{"t":"모두 같아요","mis":"M3-2-u1-X11"}],"explanation":["하나씩 몇의 10배로 구해요.","48 × 20 = 960, 32 × 30 = 960, 26 × 40 = 1040.","곱이 다른 것은 26 × 40예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_challenge#4','math',3,2,'u1','L05','g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',3,'sa','auto','어떤 수에 30을 곱해야 하는데 잘못하여 30을 더했더니 100이 되었어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u1-C5","difficulty":3,"kind":"sa","stem":"어떤 수에 30을 곱해야 하는데 잘못하여 30을 더했더니 100이 되었어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["2100"],"explanation":["어떤 수 + 30 = 100 → 어떤 수는 100 − 30 = 70이에요.","바르게 계산하면 70 × 30.","70 × 30 = 210의 10배 = 2100이에요."],"variant_rule":{"alt":[{"stem":"어떤 수에 20을 곱해야 하는데 잘못하여 20을 더했더니 66이 되었어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["920"],"explanation":["어떤 수 + 20 = 66 → 어떤 수는 66 − 20 = 46이에요.","바르게 계산하면 46 × 20.","46 × 20 = 92의 10배 = 920이에요."],"asset":null},{"stem":"어떤 수에 40을 곱해야 하는데 잘못하여 40을 더했더니 98이 되었어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["2320"],"explanation":["어떤 수 + 40 = 98 → 어떤 수는 98 − 40 = 58이에요.","바르게 계산하면 58 × 40.","58 × 40 = 232의 10배 = 2320이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_challenge#5','math',3,2,'u1','L05','g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',3,'mc','auto','곱을 견주어 ○ 안에 알맞은 것을 고르세요. 34 × 30 ○ 16 × 60',ARRAY['M3-2-u1-X11','M3-2-u1-X15']::text[],true,'{"seq":5,"concept":"M3-2-u1-C5","difficulty":3,"kind":"mc","stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 34 × 30 ○ 16 × 60","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["34 × 30 = 1020이에요.","16 × 60 = 960이에요.","1020 > 960 — 알맞은 것은 >예요."],"variant_rule":{"alt":[{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 72 × 90 ○ 96 × 70","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["72 × 90 = 6480이에요.","96 × 70 = 6720이에요.","6480 < 6720 — 알맞은 것은 <예요."],"asset":null},{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 99 × 30 ○ 37 × 80","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["99 × 30 = 2970이에요.","37 × 80 = 2960이에요.","2970 > 2960 — 알맞은 것은 >예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_challenge#6','math',3,2,'u1','L05','g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',3,'sa','auto','미니 양배추가 한 상자에 12개씩 40상자 있어요. 미니 양배추는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u1-C5","difficulty":3,"kind":"sa","stem":"미니 양배추가 한 상자에 12개씩 40상자 있어요. 미니 양배추는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["480"],"explanation":["12개씩 40번(묶음) — 곱셈식 12 × 40으로 세워요.","곱하는 수가 4에서 40으로 10배가 되면 곱도 10배예요.","12 × 40 = 480 — 모두 480개예요."],"variant_rule":{"alt":[{"stem":"색종이를 한 명에게 15장씩 90명에게 나누어 주었어요. 색종이는 모두 몇 장인가요? 숫자로 쓰세요.","answer":["1350"],"explanation":["15장씩 90번(묶음) — 곱셈식 15 × 90으로 세워요.","곱하는 수가 9에서 90으로 10배가 되면 곱도 10배예요.","15 × 90 = 1350 — 모두 1350장이에요."],"asset":null},{"stem":"하루에 71분씩 20일 동안 줄넘기를 했어요. 모두 몇 분 했나요? 숫자로 쓰세요.","answer":["1420"],"explanation":["71분씩 20번(묶음) — 곱셈식 71 × 20으로 세워요.","곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","71 × 20 = 1420 — 모두 1420분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_challenge#7','math',3,2,'u1','L05','g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',3,'error','auto','60 × 40을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X06','M3-2-u1-X15']::text[],true,'{"seq":7,"concept":"M3-2-u1-C5","difficulty":3,"kind":"error","stem":"60 × 40을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「60 × 40 = 240이야」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"은우 — 「60 × 40 = 2400이야」","mis":"M3-2-u1-X15"},{"t":"도윤 — 「40 × 60 = 2400이야」","mis":"M3-2-u1-X15"}],"explanation":["60 × 4 = 240, 곱하는 수가 4에서 40으로 10배가 되면 곱도 10배예요.","60 × 40 = 2400이에요.","하린은 240으로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배."],"variant_rule":{"alt":[{"stem":"40 × 80을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「40 × 80 = 320이야」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"태오 — 「40 × 80 = 3200이야」","mis":"M3-2-u1-X15"},{"t":"하린 — 「어림하면 약 3200이야」","mis":"M3-2-u1-X15"}],"explanation":["40 × 8 = 320, 곱하는 수가 8에서 80으로 10배가 되면 곱도 10배예요.","40 × 80 = 3200이에요.","지유는 320으로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배."],"asset":null},{"stem":"20 × 20을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「20 × 20 = 40이야」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"시우 — 「20 × 20 = 400이야」","mis":"M3-2-u1-X15"},{"t":"은우 — 「20 × 20 = 400이야」","mis":"M3-2-u1-X15"}],"explanation":["20 × 2 = 40, 곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","20 × 20 = 400이에요.","도윤은 40으로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_challenge#8','math',3,2,'u1','L05','g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',4,'essay','teacher','미니 양배추가 한 상자에 30개씩 30상자 있어요. 30 × 30이 얼마인지 30 × 3을 이용해 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C5","difficulty":4,"kind":"essay","stem":"미니 양배추가 한 상자에 30개씩 30상자 있어요. 30 × 30이 얼마인지 30 × 3을 이용해 설명해 보세요.","answer_guide":{"answer":"예: 30 × 3 = 90이다. 곱하는 수가 3에서 30으로 10배가 되었으므로 곱도 10배가 되어 30 × 30 = 900이다. 미니 양배추는 900개이다.","scoring_points":["30 × 3 = 90을 구했는가","곱하는 수가 10배이므로 곱도 10배라고 설명했는가","900을 구했는가"]},"explanation":["30 × 3 = 90.","곱하는 수 10배 → 곱 10배.","30 × 30 = 900."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_challenge#9','math',3,2,'u1','L05','g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',4,'essay','teacher','14 × 20을 두 가지 방법으로 계산하고, 두 방법의 답이 같은지 확인해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u1-C5","difficulty":4,"kind":"essay","stem":"14 × 20을 두 가지 방법으로 계산하고, 두 방법의 답이 같은지 확인해 보세요.","answer_guide":{"answer":"예: 방법 1 — 14 × 2 = 28을 구하고 10배 하여 280. 방법 2 — 14 × 10 = 140을 구하고 2배 하여 280. 두 방법 모두 280으로 같다.","scoring_points":["14 × 2의 10배로 구했는가","14 × 10의 2배로 구했는가","두 답이 280으로 같음을 확인했는가"]},"explanation":["14 × 2 = 28 → 10배 280.","14 × 10 = 140 → 2배 280.","두 길 모두 280."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L05_challenge#10','math',3,2,'u1','L05','g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',4,'sa','auto','어떤 수에 30을 곱해야 하는데 잘못하여 30을 더했더니 94가 되었어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u1-C5","difficulty":4,"kind":"sa","stem":"어떤 수에 30을 곱해야 하는데 잘못하여 30을 더했더니 94가 되었어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["1920"],"explanation":["어떤 수 + 30 = 94 → 어떤 수는 94 − 30 = 64예요.","바르게 계산하면 64 × 30.","64 × 30 = 192의 10배 = 1920이에요."],"variant_rule":{"alt":[{"stem":"어떤 수에 20을 곱해야 하는데 잘못하여 20을 더했더니 105가 되었어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["1700"],"explanation":["어떤 수 + 20 = 105 → 어떤 수는 105 − 20 = 85예요.","바르게 계산하면 85 × 20.","85 × 20 = 170의 10배 = 1700이에요."],"asset":null},{"stem":"어떤 수에 50을 곱해야 하는데 잘못하여 50을 더했더니 87이 되었어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["1850"],"explanation":["어떤 수 + 50 = 87 → 어떤 수는 87 − 50 = 37이에요.","바르게 계산하면 37 × 50.","37 × 50 = 185의 10배 = 1850이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_basic#1','math',3,2,'u1','L06','g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',1,'sa','auto','7 × 16은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C6","difficulty":1,"kind":"sa","stem":"7 × 16은 얼마인가요? 숫자로 쓰세요.","answer":["112"],"explanation":["곱하는 수 16을 10과 6으로 갈라요.","7 × 6 = 42, 7 × 10 = 70이에요.","42 + 70 = 112예요."],"variant_rule":{"alt":[{"stem":"8 × 78은 얼마인가요? 숫자로 쓰세요.","answer":["624"],"explanation":["곱하는 수 78을 70과 8로 갈라요.","8 × 8 = 64, 8 × 70 = 560이에요.","64 + 560 = 624예요."],"asset":null},{"stem":"3 × 43은 얼마인가요? 숫자로 쓰세요.","answer":["129"],"explanation":["곱하는 수 43을 40과 3으로 갈라요.","3 × 3 = 9, 3 × 40 = 120이에요.","9 + 120 = 129예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_basic#2','math',3,2,'u1','L06','g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',1,'sa','auto','7 × 16을 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u1-C6","difficulty":1,"kind":"sa","stem":"7 × 16을 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["70"],"explanation":["곱하는 수 16을 6과 10으로 갈라요.","□는 7 × 10 = 70이에요.","42 + 70 = 112 — 7 × 16의 곱이에요."],"asset":{"type":"expr_grid","rows":[["7 × 6","=","42"],["7 × 10","=",null],["42 + □","=","112"]]},"variant_rule":{"alt":[{"stem":"8 × 32를 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["240"],"explanation":["곱하는 수 32를 2와 30으로 갈라요.","□는 8 × 30 = 240이에요.","16 + 240 = 256 — 8 × 32의 곱이에요."],"asset":{"type":"expr_grid","rows":[["8 × 2","=","16"],["8 × 30","=",null],["16 + □","=","256"]]}},{"stem":"5 × 46을 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["200"],"explanation":["곱하는 수 46을 6과 40으로 갈라요.","□는 5 × 40 = 200이에요.","30 + 200 = 230 — 5 × 46의 곱이에요."],"asset":{"type":"expr_grid","rows":[["5 × 6","=","30"],["5 × 40","=",null],["30 + □","=","230"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_basic#3','math',3,2,'u1','L06','g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',1,'mc','auto','3 × 48은 얼마인가요?',ARRAY['M3-2-u1-X07','M3-2-u1-X08']::text[],true,'{"seq":3,"concept":"M3-2-u1-C6","difficulty":1,"kind":"mc","stem":"3 × 48은 얼마인가요?","options":[{"t":"144","correct":true},{"t":"36","mis":"M3-2-u1-X07"},{"t":"24","mis":"M3-2-u1-X08"},{"t":"120","mis":"M3-2-u1-X08"}],"explanation":["곱하는 수 48을 40과 8로 갈라요.","3 × 8 = 24, 3 × 40 = 120이에요.","24 + 120 = 144예요."],"variant_rule":{"alt":[{"stem":"6 × 58은 얼마인가요?","options":[{"t":"348","correct":true},{"t":"78","mis":"M3-2-u1-X07"},{"t":"48","mis":"M3-2-u1-X08"},{"t":"300","mis":"M3-2-u1-X08"}],"explanation":["곱하는 수 58을 50과 8로 갈라요.","6 × 8 = 48, 6 × 50 = 300이에요.","48 + 300 = 348이에요."],"asset":null},{"stem":"5 × 66은 얼마인가요?","options":[{"t":"330","correct":true},{"t":"60","mis":"M3-2-u1-X07"},{"t":"30","mis":"M3-2-u1-X08"},{"t":"300","mis":"M3-2-u1-X08"}],"explanation":["곱하는 수 66을 60과 6으로 갈라요.","5 × 6 = 30, 5 × 60 = 300이에요.","30 + 300 = 330이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_basic#4','math',3,2,'u1','L06','g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',1,'ox','auto','7 × 16의 곱과 16 × 7의 곱은 같아요.',ARRAY['M3-2-u1-X16']::text[],true,'{"seq":4,"concept":"M3-2-u1-C6","difficulty":1,"kind":"ox","stem":"7 × 16의 곱과 16 × 7의 곱은 같아요.","answer":"O","reason_options":[{"t":"곱하는 두 수의 순서를 바꾸어도 곱은 같아서","correct":true},{"t":"곱해지는 수가 커지면 곱도 커져서","mis":"M3-2-u1-X16"}],"mis":"M3-2-u1-X16","explanation":["7 × 16 = 112예요.","16 × 7 = 112예요.","순서를 바꾸어도 곱은 같아요 — 계산하기 쉬운 쪽으로 구해도 돼요."],"variant_rule":{"alt":[{"stem":"6 × 62의 곱과 62 × 6의 곱은 같아요.","answer":"O","reason_options":[{"t":"곱하는 두 수의 순서를 바꾸어도 곱은 같아서","correct":true},{"t":"곱해지는 수가 커지면 곱도 커져서","mis":"M3-2-u1-X16"}],"explanation":["6 × 62 = 372예요.","62 × 6 = 372예요.","순서를 바꾸어도 곱은 같아요 — 계산하기 쉬운 쪽으로 구해도 돼요."],"asset":null},{"stem":"6 × 14의 곱과 14 × 6의 곱은 같아요.","answer":"O","reason_options":[{"t":"곱하는 두 수의 순서를 바꾸어도 곱은 같아서","correct":true},{"t":"곱해지는 수가 커지면 곱도 커져서","mis":"M3-2-u1-X16"}],"explanation":["6 × 14 = 84예요.","14 × 6 = 84예요.","순서를 바꾸어도 곱은 같아요 — 계산하기 쉬운 쪽으로 구해도 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_basic#5','math',3,2,'u1','L06','g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',2,'sa','auto','8 × 42는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C6","difficulty":2,"kind":"sa","stem":"8 × 42는 얼마인가요? 숫자로 쓰세요.","answer":["336"],"explanation":["곱하는 수 42를 40과 2로 갈라요.","8 × 2 = 16, 8 × 40 = 320이에요.","16 + 320 = 336이에요."],"variant_rule":{"alt":[{"stem":"8 × 22는 얼마인가요? 숫자로 쓰세요.","answer":["176"],"explanation":["곱하는 수 22를 20과 2로 갈라요.","8 × 2 = 16, 8 × 20 = 160이에요.","16 + 160 = 176이에요."],"asset":null},{"stem":"3 × 53은 얼마인가요? 숫자로 쓰세요.","answer":["159"],"explanation":["곱하는 수 53을 50과 3으로 갈라요.","3 × 3 = 9, 3 × 50 = 150이에요.","9 + 150 = 159예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_basic#6','math',3,2,'u1','L06','g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',2,'mc','auto','하루에 7분씩 16일 동안 줄넘기를 했어요. 모두 몇 분 했나요?',ARRAY['M3-2-u1-X13','M3-2-u1-X07','M3-2-u1-X08']::text[],true,'{"seq":6,"concept":"M3-2-u1-C6","difficulty":2,"kind":"mc","stem":"하루에 7분씩 16일 동안 줄넘기를 했어요. 모두 몇 분 했나요?","options":[{"t":"112분","correct":true},{"t":"23분","mis":"M3-2-u1-X13"},{"t":"49분","mis":"M3-2-u1-X07"},{"t":"42분","mis":"M3-2-u1-X08"}],"explanation":["7분씩 16번(묶음) — 곱셈식 7 × 16으로 세워요.","7 × 6 = 42, 7 × 10 = 70이에요.","7 × 16 = 112 — 모두 112분이에요."],"variant_rule":{"alt":[{"stem":"체험 프로그램 한 번에 6명씩 들어가요. 프로그램을 52번 열었어요. 모두 몇 명이 체험했나요?","options":[{"t":"312명","correct":true},{"t":"58명","mis":"M3-2-u1-X13"},{"t":"42명","mis":"M3-2-u1-X07"},{"t":"12명","mis":"M3-2-u1-X08"}],"explanation":["6명씩 52번(묶음) — 곱셈식 6 × 52로 세워요.","6 × 2 = 12, 6 × 50 = 300이에요.","6 × 52 = 312 — 모두 312명이에요."],"asset":null},{"stem":"한 상자에 도넛이 6개씩 들어 있어요. 이런 상자가 83상자 있어요. 도넛은 모두 몇 개인가요?","options":[{"t":"498개","correct":true},{"t":"89개","mis":"M3-2-u1-X13"},{"t":"66개","mis":"M3-2-u1-X07"},{"t":"18개","mis":"M3-2-u1-X08"}],"explanation":["6개씩 83번(묶음) — 곱셈식 6 × 83으로 세워요.","6 × 3 = 18, 6 × 80 = 480이에요.","6 × 83 = 498 — 모두 498개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_basic#7','math',3,2,'u1','L06','g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',2,'ox','auto','7 × 16을 계산하는데 7 × 6 = 42에 7 × 1 = 7을 더해 49라고 했어요. 바르게 계산했어요.',ARRAY['M3-2-u1-X07']::text[],true,'{"seq":7,"concept":"M3-2-u1-C6","difficulty":2,"kind":"ox","stem":"7 × 16을 계산하는데 7 × 6 = 42에 7 × 1 = 7을 더해 49라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"십의 자리 1은 10을 나타내 7 × 10을 곱해야 해서","correct":true},{"t":"곱하는 수의 숫자끼리 곱해 더하면 되어서","mis":"M3-2-u1-X07"}],"mis":"M3-2-u1-X07","explanation":["곱하는 수 16의 십의 자리 1은 10을 뜻해요.","7 × 6 = 42, 7 × 10 = 70.","42 + 70 = 112 — 49는 십의 자리 곱을 밀어 쓰지 않은 답이에요."],"variant_rule":{"alt":[{"stem":"8 × 74를 계산하는데 8 × 4 = 32에 8 × 7 = 56을 더해 88이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"십의 자리 7은 70을 나타내 8 × 70을 곱해야 해서","correct":true},{"t":"곱하는 수의 숫자끼리 곱해 더하면 되어서","mis":"M3-2-u1-X07"}],"explanation":["곱하는 수 74의 십의 자리 7은 70을 뜻해요.","8 × 4 = 32, 8 × 70 = 560.","32 + 560 = 592 — 88은 십의 자리 곱을 밀어 쓰지 않은 답이에요."],"asset":null},{"stem":"6 × 49를 계산하는데 6 × 9 = 54에 6 × 4 = 24를 더해 78이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"십의 자리 4는 40을 나타내 6 × 40을 곱해야 해서","correct":true},{"t":"곱하는 수의 숫자끼리 곱해 더하면 되어서","mis":"M3-2-u1-X07"}],"explanation":["곱하는 수 49의 십의 자리 4는 40을 뜻해요.","6 × 9 = 54, 6 × 40 = 240.","54 + 240 = 294 — 78은 십의 자리 곱을 밀어 쓰지 않은 답이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_basic#8','math',3,2,'u1','L06','g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',2,'mc','auto','5 × 64를 갈라 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?',ARRAY['M3-2-u1-X07','M3-2-u1-X08']::text[],true,'{"seq":8,"concept":"M3-2-u1-C6","difficulty":2,"kind":"mc","stem":"5 × 64를 갈라 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?","options":[{"t":"320","correct":true},{"t":"50","mis":"M3-2-u1-X07"},{"t":"20","mis":"M3-2-u1-X08"},{"t":"300","mis":"M3-2-u1-X08"}],"explanation":["갈라 곱한 두 값을 더해요.","20 + 300 = 320이에요.","하나만 쓰면 5 × 64의 일부만 구한 거예요."],"asset":{"type":"expr_grid","rows":[["5 × 4","=","20"],["5 × 60","=","300"],["20 + 300","=",null]]},"variant_rule":{"alt":[{"stem":"5 × 87을 갈라 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?","options":[{"t":"435","correct":true},{"t":"75","mis":"M3-2-u1-X07"},{"t":"35","mis":"M3-2-u1-X08"},{"t":"400","mis":"M3-2-u1-X08"}],"explanation":["갈라 곱한 두 값을 더해요.","35 + 400 = 435예요.","하나만 쓰면 5 × 87의 일부만 구한 거예요."],"asset":{"type":"expr_grid","rows":[["5 × 7","=","35"],["5 × 80","=","400"],["35 + 400","=",null]]}},{"stem":"5 × 72를 갈라 곱했어요. 맨 아래 ?에 알맞은 수는 어느 것인가요?","options":[{"t":"360","correct":true},{"t":"45","mis":"M3-2-u1-X07"},{"t":"10","mis":"M3-2-u1-X08"},{"t":"350","mis":"M3-2-u1-X08"}],"explanation":["갈라 곱한 두 값을 더해요.","10 + 350 = 360이에요.","하나만 쓰면 5 × 72의 일부만 구한 거예요."],"asset":{"type":"expr_grid","rows":[["5 × 2","=","10"],["5 × 70","=","350"],["10 + 350","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_basic#9','math',3,2,'u1','L06','g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',2,'match','auto','곱셈식과 곱을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u1-C6","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"6 × 51","r":"306"},{"l":"9 × 18","r":"162"},{"l":"9 × 33","r":"297"}],"mis":"M3-2-u1-X07","explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","6 × 51 = 306, 9 × 18 = 162, 9 × 33 = 297.","어림한 값과 가까운지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"3 × 53","r":"159"},{"l":"6 × 96","r":"576"},{"l":"9 × 99","r":"891"}],"explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","3 × 53 = 159, 6 × 96 = 576, 9 × 99 = 891.","어림한 값과 가까운지 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"3 × 21","r":"63"},{"l":"4 × 82","r":"328"},{"l":"6 × 49","r":"294"}],"explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","3 × 21 = 63, 4 × 82 = 328, 6 × 49 = 294.","어림한 값과 가까운지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_basic#10','math',3,2,'u1','L06','g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',3,'error','auto','5 × 84를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X07','M3-2-u1-X15']::text[],true,'{"seq":10,"concept":"M3-2-u1-C6","difficulty":3,"kind":"error","stem":"5 × 84를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「5 × 84 = 60이야」","correct":true,"mis_target":"M3-2-u1-X07"},{"t":"도윤 — 「5 × 84 = 420이야」","mis":"M3-2-u1-X15"},{"t":"하랑 — 「어림하면 약 400이야」","mis":"M3-2-u1-X15"}],"explanation":["5 × 4 = 20, 5 × 80 = 400이에요.","5 × 84 = 420이에요.","지유는 60으로 잘못 구했어요 — 십의 자리 곱은 몇십 곱."],"variant_rule":{"alt":[{"stem":"3 × 19를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「3 × 19 = 30이야」","correct":true,"mis_target":"M3-2-u1-X07"},{"t":"태오 — 「3 × 19 = 57이야」","mis":"M3-2-u1-X15"},{"t":"서윤 — 「19 × 3 = 57이야」","mis":"M3-2-u1-X15"}],"explanation":["3 × 9 = 27, 3 × 10 = 30이에요.","3 × 19 = 57이에요.","은우는 30으로 잘못 구했어요 — 십의 자리 곱은 몇십 곱."],"asset":null},{"stem":"7 × 47을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「7 × 47 = 77이야」","correct":true,"mis_target":"M3-2-u1-X07"},{"t":"시우 — 「7 × 47 = 329야」","mis":"M3-2-u1-X15"},{"t":"하랑 — 「어림하면 약 350이야」","mis":"M3-2-u1-X15"}],"explanation":["7 × 7 = 49, 7 × 40 = 280이에요.","7 × 47 = 329예요.","하린은 77로 잘못 구했어요 — 십의 자리 곱은 몇십 곱."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_challenge#1','math',3,2,'u1','L06','g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',2,'sa','auto','7 × 16의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C6","difficulty":2,"kind":"sa","stem":"7 × 16의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["일의 자리 6을 먼저 곱하고, 십의 자리 1을 곱한 값은 한 자리 밀어 써요.","넷째 줄은 7 × 1 = 7 — 한 자리 밀어 써서 70을 나타내요.","?는 십의 자리 숫자 7이에요."],"asset":{"type":"expr_grid","rows":[["","","","","7"],["×","","","1","6"],["","","","4","2"],["","","",null,""],["","","1","1","2"]]},"variant_rule":{"alt":[{"stem":"3 × 13의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["일의 자리 3을 먼저 곱하고, 십의 자리 1을 곱한 값은 한 자리 밀어 써요.","넷째 줄은 3 × 1 = 3 — 한 자리 밀어 써서 30을 나타내요.","?는 십의 자리 숫자 3이에요."],"asset":{"type":"expr_grid","rows":[["","","","","3"],["×","","","1","3"],["","","","","9"],["","","",null,""],["","","","3","9"]]}},{"stem":"4 × 37의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["일의 자리 7을 먼저 곱하고, 십의 자리 3을 곱한 값은 한 자리 밀어 써요.","넷째 줄은 4 × 3 = 12 — 한 자리 밀어 써서 120을 나타내요.","?는 백의 자리 숫자 1이에요."],"asset":{"type":"expr_grid","rows":[["","","","","4"],["×","","","3","7"],["","","","2","8"],["","",null,"2",""],["","","1","4","8"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_challenge#2','math',3,2,'u1','L06','g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',2,'mc','auto','7 × 16과 곱이 같은 것은 어느 것인가요?',ARRAY['M3-2-u1-X16','M3-2-u1-X13','M3-2-u1-X08']::text[],true,'{"seq":2,"concept":"M3-2-u1-C6","difficulty":2,"kind":"mc","stem":"7 × 16과 곱이 같은 것은 어느 것인가요?","options":[{"t":"16 × 7","correct":true},{"t":"61 × 7","mis":"M3-2-u1-X16"},{"t":"7 + 16","mis":"M3-2-u1-X13"},{"t":"7 × 6","mis":"M3-2-u1-X08"}],"explanation":["곱하는 두 수의 순서를 바꾸어도 곱은 같아요.","7 × 16 = 112, 16 × 7 = 112.","숫자 자리를 바꾼 61 × 7 = 427은 달라요."],"variant_rule":{"alt":[{"stem":"5 × 29와 곱이 같은 것은 어느 것인가요?","options":[{"t":"29 × 5","correct":true},{"t":"92 × 5","mis":"M3-2-u1-X16"},{"t":"5 + 29","mis":"M3-2-u1-X13"},{"t":"5 × 9","mis":"M3-2-u1-X08"}],"explanation":["곱하는 두 수의 순서를 바꾸어도 곱은 같아요.","5 × 29 = 145, 29 × 5 = 145.","숫자 자리를 바꾼 92 × 5 = 460은 달라요."],"asset":null},{"stem":"4 × 57과 곱이 같은 것은 어느 것인가요?","options":[{"t":"57 × 4","correct":true},{"t":"75 × 4","mis":"M3-2-u1-X16"},{"t":"4 + 57","mis":"M3-2-u1-X13"},{"t":"4 × 7","mis":"M3-2-u1-X08"}],"explanation":["곱하는 두 수의 순서를 바꾸어도 곱은 같아요.","4 × 57 = 228, 57 × 4 = 228.","숫자 자리를 바꾼 75 × 4 = 300은 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_challenge#3','math',3,2,'u1','L06','g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',3,'mc','auto','곱이 가장 큰 것은 어느 것인가요?',ARRAY['M3-2-u1-X11','M3-2-u1-X15']::text[],true,'{"seq":3,"concept":"M3-2-u1-C6","difficulty":3,"kind":"mc","stem":"곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"3 × 36","correct":true},{"t":"5 × 12","mis":"M3-2-u1-X11"},{"t":"6 × 13","mis":"M3-2-u1-X15"},{"t":"6 × 12","mis":"M3-2-u1-X11"}],"explanation":["하나씩 곱을 구해요.","3 × 36 = 108, 5 × 12 = 60, 6 × 13 = 78, 6 × 12 = 72.","곱이 가장 큰 것은 3 × 36 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"5 × 72","correct":true},{"t":"7 × 23","mis":"M3-2-u1-X15"},{"t":"3 × 12","mis":"M3-2-u1-X11"},{"t":"6 × 36","mis":"M3-2-u1-X11"}],"explanation":["하나씩 곱을 구해요.","5 × 72 = 360, 7 × 23 = 161, 3 × 12 = 36, 6 × 36 = 216.","곱이 가장 큰 것은 5 × 72 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"5 × 29","correct":true},{"t":"6 × 17","mis":"M3-2-u1-X15"},{"t":"3 × 46","mis":"M3-2-u1-X11"},{"t":"4 × 32","mis":"M3-2-u1-X11"}],"explanation":["하나씩 곱을 구해요.","5 × 29 = 145, 6 × 17 = 102, 3 × 46 = 138, 4 × 32 = 128.","곱이 가장 큰 것은 5 × 29 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_challenge#4','math',3,2,'u1','L06','g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',3,'sa','auto','43에 한 자리 수를 곱했더니 200보다 작았어요. 곱할 수 있는 가장 큰 한 자리 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u1-C6","difficulty":3,"kind":"sa","stem":"43에 한 자리 수를 곱했더니 200보다 작았어요. 곱할 수 있는 가장 큰 한 자리 수는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["43 × 4 = 172 — 200보다 작아요.","43 × 5 = 215 — 200보다 커요.","그래서 가장 큰 수는 4예요."],"variant_rule":{"alt":[{"stem":"37에 한 자리 수를 곱했더니 250보다 작았어요. 곱할 수 있는 가장 큰 한 자리 수는 무엇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["37 × 6 = 222 — 250보다 작아요.","37 × 7 = 259 — 250보다 커요.","그래서 가장 큰 수는 6이에요."],"asset":null},{"stem":"64에 한 자리 수를 곱했더니 400보다 작았어요. 곱할 수 있는 가장 큰 한 자리 수는 무엇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["64 × 6 = 384 — 400보다 작아요.","64 × 7 = 448 — 400보다 커요.","그래서 가장 큰 수는 6이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_challenge#5','math',3,2,'u1','L06','g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',3,'sa','auto','색종이를 한 명에게 9장씩 27명에게 나누어 주었어요. 색종이는 모두 몇 장인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C6","difficulty":3,"kind":"sa","stem":"색종이를 한 명에게 9장씩 27명에게 나누어 주었어요. 색종이는 모두 몇 장인가요? 숫자로 쓰세요.","answer":["243"],"explanation":["9장씩 27번(묶음) — 곱셈식 9 × 27로 세워요.","9 × 7 = 63, 9 × 20 = 180이에요.","9 × 27 = 243 — 모두 243장이에요."],"variant_rule":{"alt":[{"stem":"하루에 6분씩 87일 동안 줄넘기를 했어요. 모두 몇 분 했나요? 숫자로 쓰세요.","answer":["522"],"explanation":["6분씩 87번(묶음) — 곱셈식 6 × 87로 세워요.","6 × 7 = 42, 6 × 80 = 480이에요.","6 × 87 = 522 — 모두 522분이에요."],"asset":null},{"stem":"체험 프로그램 한 번에 3명씩 들어가요. 프로그램을 22번 열었어요. 모두 몇 명이 체험했나요? 숫자로 쓰세요.","answer":["66"],"explanation":["3명씩 22번(묶음) — 곱셈식 3 × 22로 세워요.","3 × 2 = 6, 3 × 20 = 60이에요.","3 × 22 = 66 — 모두 66명이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_challenge#6','math',3,2,'u1','L06','g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',3,'mc','auto','곱을 견주어 ○ 안에 알맞은 것을 고르세요. 4 × 98 ○ 8 × 52',ARRAY['M3-2-u1-X11','M3-2-u1-X15']::text[],true,'{"seq":6,"concept":"M3-2-u1-C6","difficulty":3,"kind":"mc","stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 4 × 98 ○ 8 × 52","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["4 × 98 = 392예요.","8 × 52 = 416이에요.","392 < 416 — 알맞은 것은 <예요."],"variant_rule":{"alt":[{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 6 × 31 ○ 6 × 24","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["6 × 31 = 186이에요.","6 × 24 = 144예요.","186 > 144 — 알맞은 것은 >예요."],"asset":null},{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 7 × 94 ○ 7 × 93","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["7 × 94 = 658이에요.","7 × 93 = 651이에요.","658 > 651 — 알맞은 것은 >예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_challenge#7','math',3,2,'u1','L06','g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',3,'error','auto','8 × 34를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X07','M3-2-u1-X15']::text[],true,'{"seq":7,"concept":"M3-2-u1-C6","difficulty":3,"kind":"error","stem":"8 × 34를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「8 × 34 = 56이야」","correct":true,"mis_target":"M3-2-u1-X07"},{"t":"하랑 — 「8 × 34 = 272야」","mis":"M3-2-u1-X15"},{"t":"시우 — 「34 × 8 = 272야」","mis":"M3-2-u1-X15"}],"explanation":["8 × 4 = 32, 8 × 30 = 240이에요.","8 × 34 = 272예요.","은우는 56으로 잘못 구했어요 — 십의 자리 곱은 몇십 곱."],"variant_rule":{"alt":[{"stem":"9 × 67을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「9 × 67 = 117이야」","correct":true,"mis_target":"M3-2-u1-X07"},{"t":"하랑 — 「9 × 67 = 603이야」","mis":"M3-2-u1-X15"},{"t":"시우 — 「어림하면 약 630이야」","mis":"M3-2-u1-X15"}],"explanation":["9 × 7 = 63, 9 × 60 = 540이에요.","9 × 67 = 603이에요.","은우는 117로 잘못 구했어요 — 십의 자리 곱은 몇십 곱."],"asset":null},{"stem":"7 × 69를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「7 × 69 = 105야」","correct":true,"mis_target":"M3-2-u1-X07"},{"t":"하랑 — 「7 × 69 = 483이야」","mis":"M3-2-u1-X15"},{"t":"지유 — 「69 × 7 = 483이야」","mis":"M3-2-u1-X15"}],"explanation":["7 × 9 = 63, 7 × 60 = 420이에요.","7 × 69 = 483이에요.","태오는 105로 잘못 구했어요 — 십의 자리 곱은 몇십 곱."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_challenge#8','math',3,2,'u1','L06','g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',4,'essay','teacher','당근을 한 줄에 7개씩 16줄 놓았어요. 가로 7칸, 세로 16칸인 모눈종이를 두 덩이로 갈라 7 × 16을 구하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C6","difficulty":4,"kind":"essay","stem":"당근을 한 줄에 7개씩 16줄 놓았어요. 가로 7칸, 세로 16칸인 모눈종이를 두 덩이로 갈라 7 × 16을 구하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 세로 16칸을 10칸과 6칸으로 가르면 7 × 10 = 70, 7 × 6 = 42인 두 덩이가 된다. 두 덩이를 더하면 70 + 42 = 112이다. 당근은 112개이다.","scoring_points":["16을 10과 6으로 갈랐는가","70과 42를 구했는가","112를 구했는가"]},"explanation":["16 = 10 + 6.","7 × 10 = 70, 7 × 6 = 42.","70 + 42 = 112."],"asset":{"type":"expr_grid","rows":[["7 × 6","=","42"],["7 × 10","=","70"],["42 + 70","=","112"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_challenge#9','math',3,2,'u1','L06','g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',4,'essay','teacher','시우는 5 × 64를 「5 × 4 = 20, 5 × 6 = 30, 20 + 30 = 50」이라고 계산했어요. 시우의 잘못을 찾고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u1-C6","difficulty":4,"kind":"essay","stem":"시우는 5 × 64를 「5 × 4 = 20, 5 × 6 = 30, 20 + 30 = 50」이라고 계산했어요. 시우의 잘못을 찾고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 64의 6은 60을 나타내므로 5 × 6이 아니라 5 × 60 = 300을 구해야 한다. 5 × 4 = 20, 5 × 60 = 300, 더하면 320이다.","scoring_points":["6이 60을 나타낸다고 찾았는가","5 × 60 = 300을 구했는가","320을 구했는가"]},"explanation":["64 = 60 + 4.","5 × 4 = 20, 5 × 60 = 300.","20 + 300 = 320."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L06_challenge#10','math',3,2,'u1','L06','g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',4,'sa','auto','57에 한 자리 수를 곱했더니 300보다 작았어요. 곱할 수 있는 가장 큰 한 자리 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u1-C6","difficulty":4,"kind":"sa","stem":"57에 한 자리 수를 곱했더니 300보다 작았어요. 곱할 수 있는 가장 큰 한 자리 수는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["57 × 5 = 285 — 300보다 작아요.","57 × 6 = 342 — 300보다 커요.","그래서 가장 큰 수는 5예요."],"variant_rule":{"alt":[{"stem":"82에 한 자리 수를 곱했더니 600보다 작았어요. 곱할 수 있는 가장 큰 한 자리 수는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["82 × 7 = 574 — 600보다 작아요.","82 × 8 = 656 — 600보다 커요.","그래서 가장 큰 수는 7이에요."],"asset":null},{"stem":"69에 한 자리 수를 곱했더니 500보다 작았어요. 곱할 수 있는 가장 큰 한 자리 수는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["69 × 7 = 483 — 500보다 작아요.","69 × 8 = 552 — 500보다 커요.","그래서 가장 큰 수는 7이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_basic#1','math',3,2,'u1','L07','g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',1,'sa','auto','24 × 13은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C7","difficulty":1,"kind":"sa","stem":"24 × 13은 얼마인가요? 숫자로 쓰세요.","answer":["312"],"explanation":["곱하는 수 13을 10과 3으로 갈라요.","24 × 3 = 72, 24 × 10 = 240이에요.","72 + 240 = 312 — 어림한 20 × 10 = 200과 가까워요."],"variant_rule":{"alt":[{"stem":"18 × 44는 얼마인가요? 숫자로 쓰세요.","answer":["792"],"explanation":["곱하는 수 44를 40과 4로 갈라요.","18 × 4 = 72, 18 × 40 = 720이에요.","72 + 720 = 792 — 어림한 20 × 40 = 800과 가까워요."],"asset":null},{"stem":"43 × 21은 얼마인가요? 숫자로 쓰세요.","answer":["903"],"explanation":["곱하는 수 21을 20과 1로 갈라요.","43 × 1 = 43, 43 × 20 = 860이에요.","43 + 860 = 903 — 어림한 40 × 20 = 800과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_basic#2','math',3,2,'u1','L07','g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',1,'sa','auto','24 × 13을 네 덩이로 갈라 곱셈표에 나타냈어요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u1-C7","difficulty":1,"kind":"sa","stem":"24 × 13을 네 덩이로 갈라 곱셈표에 나타냈어요. ?에 알맞은 수를 쓰세요.","answer":["40"],"explanation":["가로 24를 20과 4, 세로 13을 10과 3으로 갈랐어요.","?는 4 × 10 = 40이에요.","네 덩이를 모두 더하면 200 + 60 + 40 + 12 = 312."],"asset":{"type":"expr_grid","rows":[["×","20","4"],["10","200",null],["3","60","12"]]},"variant_rule":{"alt":[{"stem":"12 × 37을 네 덩이로 갈라 곱셈표에 나타냈어요. ?에 알맞은 수를 쓰세요.","answer":["14"],"explanation":["가로 12를 10과 2, 세로 37을 30과 7로 갈랐어요.","?는 2 × 7 = 14예요.","네 덩이를 모두 더하면 300 + 70 + 60 + 14 = 444."],"asset":{"type":"expr_grid","rows":[["×","10","2"],["30","300","60"],["7","70",null]]}},{"stem":"59 × 12를 네 덩이로 갈라 곱셈표에 나타냈어요. ?에 알맞은 수를 쓰세요.","answer":["500"],"explanation":["가로 59를 50과 9, 세로 12를 10과 2로 갈랐어요.","?는 50 × 10 = 500이에요.","네 덩이를 모두 더하면 500 + 100 + 90 + 18 = 708."],"asset":{"type":"expr_grid","rows":[["×","50","9"],["10",null,"90"],["2","100","18"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_basic#3','math',3,2,'u1','L07','g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',1,'mc','auto','12 × 16은 얼마인가요?',ARRAY['M3-2-u1-X09','M3-2-u1-X07','M3-2-u1-X08']::text[],true,'{"seq":3,"concept":"M3-2-u1-C7","difficulty":1,"kind":"mc","stem":"12 × 16은 얼마인가요?","options":[{"t":"192","correct":true},{"t":"112","mis":"M3-2-u1-X09"},{"t":"84","mis":"M3-2-u1-X07"},{"t":"72","mis":"M3-2-u1-X08"}],"explanation":["곱하는 수 16을 10과 6으로 갈라요.","12 × 6 = 72, 12 × 10 = 120이에요.","72 + 120 = 192 — 어림한 10 × 20 = 200과 가까워요."],"variant_rule":{"alt":[{"stem":"53 × 16은 얼마인가요?","options":[{"t":"848","correct":true},{"t":"518","mis":"M3-2-u1-X09"},{"t":"371","mis":"M3-2-u1-X07"},{"t":"318","mis":"M3-2-u1-X08"}],"explanation":["곱하는 수 16을 10과 6으로 갈라요.","53 × 6 = 318, 53 × 10 = 530이에요.","318 + 530 = 848 — 어림한 50 × 20 = 1000과 가까워요."],"asset":null},{"stem":"17 × 23은 얼마인가요?","options":[{"t":"391","correct":true},{"t":"221","mis":"M3-2-u1-X09"},{"t":"85","mis":"M3-2-u1-X07"},{"t":"51","mis":"M3-2-u1-X08"}],"explanation":["곱하는 수 23을 20과 3으로 갈라요.","17 × 3 = 51, 17 × 20 = 340이에요.","51 + 340 = 391 — 어림한 20 × 20 = 400과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_basic#4','math',3,2,'u1','L07','g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C3',1,'mc','auto','29 × 13을 어림하면 약 얼마인가요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],true,'{"seq":4,"concept":"M3-2-u1-C3","difficulty":1,"kind":"mc","stem":"29 × 13을 어림하면 약 얼마인가요?","options":[{"t":"약 300","correct":true},{"t":"약 400","mis":"M3-2-u1-X12"},{"t":"약 40","mis":"M3-2-u1-X12"},{"t":"약 3000","mis":"M3-2-u1-X06"}],"explanation":["29는 가까운 몇십 30으로 어림해요. 13은 10으로 어림해요.","30 × 10 = 300이에요.","그래서 약 300이에요 — 실제 곱 377과 가까워요."],"variant_rule":{"alt":[{"stem":"13 × 58을 어림하면 약 얼마인가요?","options":[{"t":"약 600","correct":true},{"t":"약 70","mis":"M3-2-u1-X12"},{"t":"약 6000","mis":"M3-2-u1-X06"},{"t":"약 10","mis":"M3-2-u1-X12"}],"explanation":["13은 가까운 몇십 10으로 어림해요. 58은 60으로 어림해요.","10 × 60 = 600이에요.","그래서 약 600이에요 — 실제 곱 754와 가까워요."],"asset":null},{"stem":"46 × 21을 어림하면 약 얼마인가요?","options":[{"t":"약 1000","correct":true},{"t":"약 1200","mis":"M3-2-u1-X12"},{"t":"약 70","mis":"M3-2-u1-X12"},{"t":"약 10000","mis":"M3-2-u1-X06"}],"explanation":["46은 가까운 몇십 50으로 어림해요. 21은 20으로 어림해요.","50 × 20 = 1000이에요.","그래서 약 1000이에요 — 실제 곱 966과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_basic#5','math',3,2,'u1','L07','g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',2,'sa','auto','24 × 13을 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C7","difficulty":2,"kind":"sa","stem":"24 × 13을 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["240"],"explanation":["곱하는 수 13을 3과 10으로 갈라요.","□는 24 × 10 = 240이에요.","72 + 240 = 312 — 24 × 13의 곱이에요."],"asset":{"type":"expr_grid","rows":[["24 × 3","=","72"],["24 × 10","=",null],["72 + □","=","312"]]},"variant_rule":{"alt":[{"stem":"31 × 14를 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["310"],"explanation":["곱하는 수 14를 4와 10으로 갈라요.","□는 31 × 10 = 310이에요.","124 + 310 = 434 — 31 × 14의 곱이에요."],"asset":{"type":"expr_grid","rows":[["31 × 4","=","124"],["31 × 10","=",null],["124 + □","=","434"]]}},{"stem":"27 × 14를 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["270"],"explanation":["곱하는 수 14를 4와 10으로 갈라요.","□는 27 × 10 = 270이에요.","108 + 270 = 378 — 27 × 14의 곱이에요."],"asset":{"type":"expr_grid","rows":[["27 × 4","=","108"],["27 × 10","=",null],["108 + □","=","378"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_basic#6','math',3,2,'u1','L07','g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',2,'mc','auto','미니 양배추가 한 상자에 24개씩 13상자 있어요. 미니 양배추는 모두 몇 개인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X09','M3-2-u1-X07']::text[],true,'{"seq":6,"concept":"M3-2-u1-C7","difficulty":2,"kind":"mc","stem":"미니 양배추가 한 상자에 24개씩 13상자 있어요. 미니 양배추는 모두 몇 개인가요?","options":[{"t":"312개","correct":true},{"t":"37개","mis":"M3-2-u1-X13"},{"t":"212개","mis":"M3-2-u1-X09"},{"t":"96개","mis":"M3-2-u1-X07"}],"explanation":["24개씩 13번(묶음) — 곱셈식 24 × 13으로 세워요.","24 × 3 = 72, 24 × 10 = 240이에요.","24 × 13 = 312 — 모두 312개예요."],"variant_rule":{"alt":[{"stem":"색종이를 한 명에게 66장씩 11명에게 나누어 주었어요. 색종이는 모두 몇 장인가요?","options":[{"t":"726장","correct":true},{"t":"77장","mis":"M3-2-u1-X13"},{"t":"606장","mis":"M3-2-u1-X09"},{"t":"132장","mis":"M3-2-u1-X07"}],"explanation":["66장씩 11번(묶음) — 곱셈식 66 × 11로 세워요.","66 × 1 = 66, 66 × 10 = 660이에요.","66 × 11 = 726 — 모두 726장이에요."],"asset":null},{"stem":"하루에 42분씩 16일 동안 줄넘기를 했어요. 모두 몇 분 했나요?","options":[{"t":"672분","correct":true},{"t":"58분","mis":"M3-2-u1-X13"},{"t":"412분","mis":"M3-2-u1-X09"},{"t":"294분","mis":"M3-2-u1-X07"}],"explanation":["42분씩 16번(묶음) — 곱셈식 42 × 16으로 세워요.","42 × 6 = 252, 42 × 10 = 420이에요.","42 × 16 = 672 — 모두 672분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_basic#7','math',3,2,'u1','L07','g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',2,'ox','auto','24 × 13을 계산하는데 십의 자리끼리 20 × 10 = 200, 일의 자리끼리 4 × 3 = 12로 곱해 더해 212라고 했어요. 바르게 계산했어요.',ARRAY['M3-2-u1-X09']::text[],true,'{"seq":7,"concept":"M3-2-u1-C7","difficulty":2,"kind":"ox","stem":"24 × 13을 계산하는데 십의 자리끼리 20 × 10 = 200, 일의 자리끼리 4 × 3 = 12로 곱해 더해 212라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"네 덩이 가운데 두 덩이를 빠뜨려서","correct":true},{"t":"같은 자리끼리 곱하면 되어서","mis":"M3-2-u1-X09"}],"mis":"M3-2-u1-X09","explanation":["24 × 13은 네 덩이예요.","20 × 3, 4 × 10 덩이도 더해야 해요.","24 × 13 = 312예요."],"asset":{"type":"expr_grid","rows":[["×","20","4"],["10","200","40"],["3","60","12"]]},"variant_rule":{"alt":[{"stem":"51 × 14를 계산하는데 십의 자리끼리 50 × 10 = 500, 일의 자리끼리 1 × 4 = 4로 곱해 더해 504라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"네 덩이 가운데 두 덩이를 빠뜨려서","correct":true},{"t":"같은 자리끼리 곱하면 되어서","mis":"M3-2-u1-X09"}],"explanation":["51 × 14는 네 덩이예요.","50 × 4, 1 × 10 덩이도 더해야 해요.","51 × 14 = 714예요."],"asset":{"type":"expr_grid","rows":[["×","50","1"],["10","500","10"],["4","200","4"]]}},{"stem":"31 × 26을 계산하는데 십의 자리끼리 30 × 20 = 600, 일의 자리끼리 1 × 6 = 6으로 곱해 더해 606이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"네 덩이 가운데 두 덩이를 빠뜨려서","correct":true},{"t":"같은 자리끼리 곱하면 되어서","mis":"M3-2-u1-X09"}],"explanation":["31 × 26은 네 덩이예요.","30 × 6, 1 × 20 덩이도 더해야 해요.","31 × 26 = 806이에요."],"asset":{"type":"expr_grid","rows":[["×","30","1"],["20","600","20"],["6","180","6"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_basic#8','math',3,2,'u1','L07','g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',2,'mc','auto','23 × 14를 네 덩이로 갈라 곱했어요. 23 × 14는 얼마인가요?',ARRAY['M3-2-u1-X09','M3-2-u1-X08','M3-2-u1-X11']::text[],true,'{"seq":8,"concept":"M3-2-u1-C7","difficulty":2,"kind":"mc","stem":"23 × 14를 네 덩이로 갈라 곱했어요. 23 × 14는 얼마인가요?","options":[{"t":"322","correct":true},{"t":"212","mis":"M3-2-u1-X09"},{"t":"310","mis":"M3-2-u1-X08"},{"t":"332","mis":"M3-2-u1-X11"}],"explanation":["곱셈표 네 칸이 네 덩이예요.","200 + 80 + 30 + 12 = 322.","두 칸만 더하면 212 — 덩이를 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["×","20","3"],["10","200","30"],["4","80","12"]]},"variant_rule":{"alt":[{"stem":"14 × 16을 네 덩이로 갈라 곱했어요. 14 × 16은 얼마인가요?","options":[{"t":"224","correct":true},{"t":"124","mis":"M3-2-u1-X09"},{"t":"200","mis":"M3-2-u1-X08"},{"t":"234","mis":"M3-2-u1-X11"}],"explanation":["곱셈표 네 칸이 네 덩이예요.","100 + 60 + 40 + 24 = 224.","두 칸만 더하면 124 — 덩이를 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["×","10","4"],["10","100","40"],["6","60","24"]]}},{"stem":"11 × 36을 네 덩이로 갈라 곱했어요. 11 × 36은 얼마인가요?","options":[{"t":"396","correct":true},{"t":"306","mis":"M3-2-u1-X09"},{"t":"390","mis":"M3-2-u1-X08"},{"t":"406","mis":"M3-2-u1-X11"}],"explanation":["곱셈표 네 칸이 네 덩이예요.","300 + 60 + 30 + 6 = 396.","두 칸만 더하면 306 — 덩이를 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["×","10","1"],["30","300","30"],["6","60","6"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_basic#9','math',3,2,'u1','L07','g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',2,'match','auto','곱셈식과 곱을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u1-C7","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"15 × 21","r":"315"},{"l":"77 × 12","r":"924"},{"l":"14 × 64","r":"896"}],"mis":"M3-2-u1-X09","explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","15 × 21 = 315, 77 × 12 = 924, 14 × 64 = 896.","어림한 값과 가까운지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"33 × 19","r":"627"},{"l":"16 × 13","r":"208"},{"l":"18 × 24","r":"432"}],"explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","33 × 19 = 627, 16 × 13 = 208, 18 × 24 = 432.","어림한 값과 가까운지 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"12 × 57","r":"684"},{"l":"12 × 21","r":"252"},{"l":"64 × 13","r":"832"}],"explanation":["자리마다(또는 갈라서) 곱한 뒤 더해요.","12 × 57 = 684, 12 × 21 = 252, 64 × 13 = 832.","어림한 값과 가까운지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_basic#10','math',3,2,'u1','L07','g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',3,'error','auto','23 × 14를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X09','M3-2-u1-X15']::text[],true,'{"seq":10,"concept":"M3-2-u1-C7","difficulty":3,"kind":"error","stem":"23 × 14를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「23 × 14 = 212야」","correct":true,"mis_target":"M3-2-u1-X09"},{"t":"하랑 — 「23 × 14 = 322야」","mis":"M3-2-u1-X15"},{"t":"시우 — 「14 × 23 = 322야」","mis":"M3-2-u1-X15"}],"explanation":["23 × 4 = 92, 23 × 10 = 230이에요.","23 × 14 = 322예요.","지유는 212로 잘못 구했어요 — 네 덩이를 모두 더하기."],"variant_rule":{"alt":[{"stem":"11 × 39를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「11 × 39 = 309야」","correct":true,"mis_target":"M3-2-u1-X09"},{"t":"하린 — 「11 × 39 = 429야」","mis":"M3-2-u1-X15"},{"t":"서윤 — 「어림하면 약 400이야」","mis":"M3-2-u1-X15"}],"explanation":["11 × 9 = 99, 11 × 30 = 330이에요.","11 × 39 = 429예요.","도윤은 309로 잘못 구했어요 — 네 덩이를 모두 더하기."],"asset":null},{"stem":"11 × 27을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「11 × 27 = 207이야」","correct":true,"mis_target":"M3-2-u1-X09"},{"t":"지유 — 「11 × 27 = 297이야」","mis":"M3-2-u1-X15"},{"t":"서윤 — 「27 × 11 = 297이야」","mis":"M3-2-u1-X15"}],"explanation":["11 × 7 = 77, 11 × 20 = 220이에요.","11 × 27 = 297이에요.","하린은 207로 잘못 구했어요 — 네 덩이를 모두 더하기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_challenge#1','math',3,2,'u1','L07','g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',2,'sa','auto','24 × 13의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C7","difficulty":2,"kind":"sa","stem":"24 × 13의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["일의 자리 3을 먼저 곱하고, 십의 자리 1을 곱한 값은 한 자리 밀어 써요.","넷째 줄은 24 × 1 = 24 — 한 자리 밀어 써서 240을 나타내요.","?는 십의 자리 숫자 4예요."],"asset":{"type":"expr_grid","rows":[["","","","2","4"],["×","","","1","3"],["","","","7","2"],["","","2",null,""],["","","3","1","2"]]},"variant_rule":{"alt":[{"stem":"24 × 33의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["일의 자리 3을 먼저 곱하고, 십의 자리 3을 곱한 값은 한 자리 밀어 써요.","두 줄을 더해 72 + 720 = 792예요.","?는 백의 자리 숫자 7이에요."],"asset":{"type":"expr_grid","rows":[["","","","2","4"],["×","","","3","3"],["","","","7","2"],["","","7","2",""],["","",null,"9","2"]]}},{"stem":"27 × 12의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["5"],"explanation":["일의 자리 2를 먼저 곱하고, 십의 자리 1을 곱한 값은 한 자리 밀어 써요.","셋째 줄은 27 × 2 = 54예요.","?는 십의 자리 숫자 5예요."],"asset":{"type":"expr_grid","rows":[["","","","2","7"],["×","","","1","2"],["","","",null,"4"],["","","2","7",""],["","","3","2","4"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_challenge#2','math',3,2,'u1','L07','g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C3',2,'ox','auto','31 × 22를 계산했더니 124가 나왔어요. 어림해 보면 알맞은 답이에요.',ARRAY['M3-2-u1-X12']::text[],true,'{"seq":2,"concept":"M3-2-u1-C3","difficulty":2,"kind":"ox","stem":"31 × 22를 계산했더니 124가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 600과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u1-X12"}],"mis":"M3-2-u1-X12","explanation":["31 × 22를 어림하면 30 × 20 = 600이에요.","124는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 31 × 22 = 682예요."],"variant_rule":{"alt":[{"stem":"33 × 24를 계산했더니 198이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 600과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u1-X12"}],"explanation":["33 × 24를 어림하면 30 × 20 = 600이에요.","198은 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 33 × 24 = 792예요."],"asset":null},{"stem":"19 × 48을 계산했더니 228이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 1000과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u1-X12"}],"explanation":["19 × 48을 어림하면 20 × 50 = 1000이에요.","228은 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 19 × 48 = 912예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_challenge#3','math',3,2,'u1','L07','g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',3,'mc','auto','곱을 견주어 ○ 안에 알맞은 것을 고르세요. 61 × 14 ○ 62 × 13',ARRAY['M3-2-u1-X11','M3-2-u1-X15']::text[],true,'{"seq":3,"concept":"M3-2-u1-C7","difficulty":3,"kind":"mc","stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 61 × 14 ○ 62 × 13","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["61 × 14 = 854예요.","62 × 13 = 806이에요.","854 > 806 — 알맞은 것은 >예요."],"variant_rule":{"alt":[{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 11 × 82 ○ 26 × 31","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["11 × 82 = 902예요.","26 × 31 = 806이에요.","902 > 806 — 알맞은 것은 >예요."],"asset":null},{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 32 × 12 ○ 21 × 17","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["32 × 12 = 384예요.","21 × 17 = 357이에요.","384 > 357 — 알맞은 것은 >예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_challenge#4','math',3,2,'u1','L07','g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',3,'sa','auto','다른 나라 돈 1루피는 우리 돈 36원이에요. 12루피는 우리 돈으로 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u1-C7","difficulty":3,"kind":"sa","stem":"다른 나라 돈 1루피는 우리 돈 36원이에요. 12루피는 우리 돈으로 얼마인가요? 숫자로 쓰세요.","answer":["432"],"explanation":["1루피에 36원씩 12루피 — 36 × 12.","36 × 2 = 72, 36 × 10 = 360이에요.","36 × 12 = 432 — 우리 돈 432원이에요."],"variant_rule":{"alt":[{"stem":"먼 나라 돈 1페소는 우리 돈 47원이에요. 11페소는 우리 돈으로 얼마인가요? 숫자로 쓰세요.","answer":["517"],"explanation":["1페소에 47원씩 11페소 — 47 × 11.","47 × 1 = 47, 47 × 10 = 470이에요.","47 × 11 = 517 — 우리 돈 517원이에요."],"asset":null},{"stem":"어느 나라 돈 1밧은 우리 돈 14원이에요. 19밧은 우리 돈으로 얼마인가요? 숫자로 쓰세요.","answer":["266"],"explanation":["1밧에 14원씩 19밧 — 14 × 19.","14 × 9 = 126, 14 × 10 = 140이에요.","14 × 19 = 266 — 우리 돈 266원이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_challenge#5','math',3,2,'u1','L07','g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',3,'sa','auto','14 × 16은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C7","difficulty":3,"kind":"sa","stem":"14 × 16은 얼마인가요? 숫자로 쓰세요.","answer":["224"],"explanation":["곱하는 수 16을 10과 6으로 갈라요.","14 × 6 = 84, 14 × 10 = 140이에요.","84 + 140 = 224 — 어림한 10 × 20 = 200과 가까워요."],"variant_rule":{"alt":[{"stem":"34 × 28은 얼마인가요? 숫자로 쓰세요.","answer":["952"],"explanation":["곱하는 수 28을 20과 8로 갈라요.","34 × 8 = 272, 34 × 20 = 680이에요.","272 + 680 = 952 — 어림한 30 × 30 = 900과 가까워요."],"asset":null},{"stem":"36 × 11은 얼마인가요? 숫자로 쓰세요.","answer":["396"],"explanation":["곱하는 수 11을 10과 1로 갈라요.","36 × 1 = 36, 36 × 10 = 360이에요.","36 + 360 = 396 — 어림한 40 × 10 = 400과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_challenge#6','math',3,2,'u1','L07','g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',3,'ox','auto','24 × 13을 계산하는데 24 × 3 = 72에 24 × 1 = 24를 더해 96이라고 했어요. 바르게 계산했어요.',ARRAY['M3-2-u1-X07']::text[],true,'{"seq":6,"concept":"M3-2-u1-C7","difficulty":3,"kind":"ox","stem":"24 × 13을 계산하는데 24 × 3 = 72에 24 × 1 = 24를 더해 96이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"십의 자리 1은 10을 나타내 24 × 10을 곱해야 해서","correct":true},{"t":"곱하는 수의 숫자끼리 곱해 더하면 되어서","mis":"M3-2-u1-X07"}],"mis":"M3-2-u1-X07","explanation":["곱하는 수 13의 십의 자리 1은 10을 뜻해요.","24 × 3 = 72, 24 × 10 = 240.","72 + 240 = 312 — 96은 십의 자리 곱을 밀어 쓰지 않은 답이에요."],"variant_rule":{"alt":[{"stem":"28 × 19를 계산하는데 28 × 9 = 252에 28 × 1 = 28을 더해 280이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"십의 자리 1은 10을 나타내 28 × 10을 곱해야 해서","correct":true},{"t":"곱하는 수의 숫자끼리 곱해 더하면 되어서","mis":"M3-2-u1-X07"}],"explanation":["곱하는 수 19의 십의 자리 1은 10을 뜻해요.","28 × 9 = 252, 28 × 10 = 280.","252 + 280 = 532 — 280은 십의 자리 곱을 밀어 쓰지 않은 답이에요."],"asset":null},{"stem":"31 × 24를 계산하는데 31 × 4 = 124에 31 × 2 = 62를 더해 186이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"십의 자리 2는 20을 나타내 31 × 20을 곱해야 해서","correct":true},{"t":"곱하는 수의 숫자끼리 곱해 더하면 되어서","mis":"M3-2-u1-X07"}],"explanation":["곱하는 수 24의 십의 자리 2는 20을 뜻해요.","31 × 4 = 124, 31 × 20 = 620.","124 + 620 = 744 — 186은 십의 자리 곱을 밀어 쓰지 않은 답이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_challenge#7','math',3,2,'u1','L07','g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',3,'error','auto','42 × 23을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X09','M3-2-u1-X15']::text[],true,'{"seq":7,"concept":"M3-2-u1-C7","difficulty":3,"kind":"error","stem":"42 × 23을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「42 × 23 = 806이야」","correct":true,"mis_target":"M3-2-u1-X09"},{"t":"시우 — 「42 × 23 = 966이야」","mis":"M3-2-u1-X15"},{"t":"태오 — 「어림하면 약 800이야」","mis":"M3-2-u1-X15"}],"explanation":["42 × 3 = 126, 42 × 20 = 840이에요.","42 × 23 = 966이에요.","하랑은 806으로 잘못 구했어요 — 네 덩이를 모두 더하기."],"variant_rule":{"alt":[{"stem":"56 × 14를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「56 × 14 = 524야」","correct":true,"mis_target":"M3-2-u1-X09"},{"t":"도윤 — 「56 × 14 = 784야」","mis":"M3-2-u1-X15"},{"t":"하랑 — 「14 × 56 = 784야」","mis":"M3-2-u1-X15"}],"explanation":["56 × 4 = 224, 56 × 10 = 560이에요.","56 × 14 = 784예요.","하린은 524로 잘못 구했어요 — 네 덩이를 모두 더하기."],"asset":null},{"stem":"37 × 22를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「37 × 22 = 614야」","correct":true,"mis_target":"M3-2-u1-X09"},{"t":"지유 — 「37 × 22 = 814야」","mis":"M3-2-u1-X15"},{"t":"은우 — 「어림하면 약 800이야」","mis":"M3-2-u1-X15"}],"explanation":["37 × 2 = 74, 37 × 20 = 740이에요.","37 × 22 = 814예요.","서윤은 614로 잘못 구했어요 — 네 덩이를 모두 더하기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_challenge#8','math',3,2,'u1','L07','g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',4,'essay','teacher','체험 프로그램 한 번에 24명씩 13번 열었어요. 24 × 13을 네 덩이로 가르는 방법과 두 덩이로 가르는 방법으로 각각 계산해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C7","difficulty":4,"kind":"essay","stem":"체험 프로그램 한 번에 24명씩 13번 열었어요. 24 × 13을 네 덩이로 가르는 방법과 두 덩이로 가르는 방법으로 각각 계산해 보세요.","answer_guide":{"answer":"예: 네 덩이 — 20 × 10 = 200, 4 × 10 = 40, 20 × 3 = 60, 4 × 3 = 12, 모두 더하면 312. 두 덩이 — 24 × 10 = 240, 24 × 3 = 72, 더하면 312. 두 방법 모두 312명이다.","scoring_points":["네 덩이 200·40·60·12를 구해 더했는가","두 덩이 240·72를 구해 더했는가","312를 구했는가"]},"explanation":["네 덩이 200 + 40 + 60 + 12 = 312.","두 덩이 240 + 72 = 312.","24 × 13 = 312."],"asset":{"type":"expr_grid","rows":[["×","20","4"],["10","200","40"],["3","60","12"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_challenge#9','math',3,2,'u1','L07','g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',4,'essay','teacher','도윤이는 24 × 13을 「20 × 10 = 200, 4 × 3 = 12, 200 + 12 = 212」라고 계산했어요. 무엇을 빠뜨렸는지 설명하고 바른 답을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u1-C7","difficulty":4,"kind":"essay","stem":"도윤이는 24 × 13을 「20 × 10 = 200, 4 × 3 = 12, 200 + 12 = 212」라고 계산했어요. 무엇을 빠뜨렸는지 설명하고 바른 답을 구해 보세요.","answer_guide":{"answer":"예: 네 덩이 가운데 4 × 10 = 40과 20 × 3 = 60 두 덩이를 빠뜨렸다. 200 + 40 + 60 + 12 = 312가 바른 답이다.","scoring_points":["두 덩이(40, 60)를 빠뜨렸다고 찾았는가","네 덩이를 모두 더했는가","312를 구했는가"]},"explanation":["네 덩이: 200, 40, 60, 12.","도윤이는 40과 60을 빠뜨렸어요.","바른 답 312."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L07_challenge#10','math',3,2,'u1','L07','g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',4,'sa','auto','어느 나라 돈 1밧은 우리 돈 27원이에요. 32밧은 우리 돈으로 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u1-C7","difficulty":4,"kind":"sa","stem":"어느 나라 돈 1밧은 우리 돈 27원이에요. 32밧은 우리 돈으로 얼마인가요? 숫자로 쓰세요.","answer":["864"],"explanation":["1밧에 27원씩 32밧 — 27 × 32.","27 × 2 = 54, 27 × 30 = 810이에요.","27 × 32 = 864 — 우리 돈 864원이에요."],"variant_rule":{"alt":[{"stem":"다른 나라 돈 1루피는 우리 돈 33원이에요. 17루피는 우리 돈으로 얼마인가요? 숫자로 쓰세요.","answer":["561"],"explanation":["1루피에 33원씩 17루피 — 33 × 17.","33 × 7 = 231, 33 × 10 = 330이에요.","33 × 17 = 561 — 우리 돈 561원이에요."],"asset":null},{"stem":"먼 나라 돈 1페소는 우리 돈 19원이에요. 47페소는 우리 돈으로 얼마인가요? 숫자로 쓰세요.","answer":["893"],"explanation":["1페소에 19원씩 47페소 — 19 × 47.","19 × 7 = 133, 19 × 40 = 760이에요.","19 × 47 = 893 — 우리 돈 893원이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L08_basic#1','math',3,2,'u1','L08','g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C8',1,'sa','auto','39 × 26은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C8","difficulty":1,"kind":"sa","stem":"39 × 26은 얼마인가요? 숫자로 쓰세요.","answer":["1014"],"explanation":["곱하는 수 26을 20과 6으로 갈라요.","39 × 6 = 234, 39 × 20 = 780이에요.","234 + 780 = 1014 — 어림한 40 × 30 = 1200과 가까워요."],"variant_rule":{"alt":[{"stem":"39 × 97은 얼마인가요? 숫자로 쓰세요.","answer":["3783"],"explanation":["곱하는 수 97을 90과 7로 갈라요.","39 × 7 = 273, 39 × 90 = 3510이에요.","273 + 3510 = 3783 — 어림한 40 × 100 = 4000과 가까워요."],"asset":null},{"stem":"59 × 63은 얼마인가요? 숫자로 쓰세요.","answer":["3717"],"explanation":["곱하는 수 63을 60과 3으로 갈라요.","59 × 3 = 177, 59 × 60 = 3540이에요.","177 + 3540 = 3717 — 어림한 60 × 60 = 3600과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L08_basic#2','math',3,2,'u1','L08','g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C8',1,'sa','auto','39 × 26을 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u1-C8","difficulty":1,"kind":"sa","stem":"39 × 26을 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["234"],"explanation":["곱하는 수 26을 6과 20으로 갈라요.","□는 39 × 6 = 234예요.","234 + 780 = 1014 — 39 × 26의 곱이에요."],"asset":{"type":"expr_grid","rows":[["39 × 6","=",null],["39 × 20","=","780"],["□ + 780","=","1014"]]},"variant_rule":{"alt":[{"stem":"77 × 53을 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["231"],"explanation":["곱하는 수 53을 3과 50으로 갈라요.","□는 77 × 3 = 231이에요.","231 + 3850 = 4081 — 77 × 53의 곱이에요."],"asset":{"type":"expr_grid","rows":[["77 × 3","=",null],["77 × 50","=","3850"],["□ + 3850","=","4081"]]}},{"stem":"87 × 47을 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["609"],"explanation":["곱하는 수 47을 7과 40으로 갈라요.","□는 87 × 7 = 609예요.","609 + 3480 = 4089 — 87 × 47의 곱이에요."],"asset":{"type":"expr_grid","rows":[["87 × 7","=",null],["87 × 40","=","3480"],["□ + 3480","=","4089"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L08_basic#3','math',3,2,'u1','L08','g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C8',1,'mc','auto','26 × 43은 얼마인가요?',ARRAY['M3-2-u1-X10','M3-2-u1-X07','M3-2-u1-X09']::text[],true,'{"seq":3,"concept":"M3-2-u1-C8","difficulty":1,"kind":"mc","stem":"26 × 43은 얼마인가요?","options":[{"t":"1118","correct":true},{"t":"1128","mis":"M3-2-u1-X10"},{"t":"182","mis":"M3-2-u1-X07"},{"t":"818","mis":"M3-2-u1-X09"}],"explanation":["곱하는 수 43을 40과 3으로 갈라요.","26 × 3 = 78, 26 × 40 = 1040이에요.","78 + 1040 = 1118 — 어림한 30 × 40 = 1200과 가까워요."],"variant_rule":{"alt":[{"stem":"58 × 26은 얼마인가요?","options":[{"t":"1508","correct":true},{"t":"1548","mis":"M3-2-u1-X10"},{"t":"464","mis":"M3-2-u1-X07"},{"t":"1048","mis":"M3-2-u1-X09"}],"explanation":["곱하는 수 26을 20과 6으로 갈라요.","58 × 6 = 348, 58 × 20 = 1160이에요.","348 + 1160 = 1508 — 어림한 60 × 30 = 1800과 가까워요."],"asset":null},{"stem":"94 × 74는 얼마인가요?","options":[{"t":"6956","correct":true},{"t":"6966","mis":"M3-2-u1-X10"},{"t":"1034","mis":"M3-2-u1-X07"},{"t":"6316","mis":"M3-2-u1-X09"}],"explanation":["곱하는 수 74를 70과 4로 갈라요.","94 × 4 = 376, 94 × 70 = 6580이에요.","376 + 6580 = 6956 — 어림한 90 × 70 = 6300과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L08_basic#4','math',3,2,'u1','L08','g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C3',1,'mc','auto','39 × 26을 어림하면 곱은 어느 사이에 있나요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],true,'{"seq":4,"concept":"M3-2-u1-C3","difficulty":1,"kind":"mc","stem":"39 × 26을 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"600보다 크고 1200보다 작아요","correct":true},{"t":"600보다 작아요","mis":"M3-2-u1-X12"},{"t":"1200보다 커요","mis":"M3-2-u1-X12"},{"t":"60보다 크고 120보다 작아요","mis":"M3-2-u1-X06"}],"explanation":["39는 30과 40 사이, 26은 20과 30 사이예요.","30 × 20 = 600, 40 × 30 = 1200이에요.","39 × 26 = 1014 — 그 사이에 들어요."],"variant_rule":{"alt":[{"stem":"82 × 19를 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"800보다 크고 1800보다 작아요","correct":true},{"t":"800보다 작아요","mis":"M3-2-u1-X12"},{"t":"1800보다 커요","mis":"M3-2-u1-X12"},{"t":"80보다 크고 180보다 작아요","mis":"M3-2-u1-X06"}],"explanation":["82는 80과 90 사이, 19는 10과 20 사이예요.","80 × 10 = 800, 90 × 20 = 1800이에요.","82 × 19 = 1558 — 그 사이에 들어요."],"asset":null},{"stem":"42 × 76을 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"2800보다 크고 4000보다 작아요","correct":true},{"t":"2800보다 작아요","mis":"M3-2-u1-X12"},{"t":"4000보다 커요","mis":"M3-2-u1-X12"},{"t":"280보다 크고 400보다 작아요","mis":"M3-2-u1-X06"}],"explanation":["42는 40과 50 사이, 76은 70과 80 사이예요.","40 × 70 = 2800, 50 × 80 = 4000이에요.","42 × 76 = 3192 — 그 사이에 들어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L08_basic#5','math',3,2,'u1','L08','g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C8',2,'sa','auto','39 × 26의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C8","difficulty":2,"kind":"sa","stem":"39 × 26의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["일의 자리 6을 먼저 곱하고, 십의 자리 2를 곱한 값은 한 자리 밀어 써요.","넷째 줄은 39 × 2 = 78 — 한 자리 밀어 써서 780을 나타내요.","?는 십의 자리 숫자 8이에요."],"asset":{"type":"expr_grid","rows":[["","","","3","9"],["×","","","2","6"],["","","2","3","4"],["","","7",null,""],["","1","0","1","4"]]},"variant_rule":{"alt":[{"stem":"94 × 96의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["0"],"explanation":["일의 자리 6을 먼저 곱하고, 십의 자리 9를 곱한 값은 한 자리 밀어 써요.","두 줄을 더해 564 + 8460 = 9024예요.","?는 백의 자리 숫자 0이에요."],"asset":{"type":"expr_grid","rows":[["","","","9","4"],["×","","","9","6"],["","","5","6","4"],["","8","4","6",""],["","9",null,"2","4"]]}},{"stem":"84 × 88의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["일의 자리 8을 먼저 곱하고, 십의 자리 8을 곱한 값은 한 자리 밀어 써요.","셋째 줄은 84 × 8 = 672예요.","?는 십의 자리 숫자 7이에요."],"asset":{"type":"expr_grid","rows":[["","","","8","4"],["×","","","8","8"],["","","6",null,"2"],["","6","7","2",""],["","7","3","9","2"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L08_basic#6','math',3,2,'u1','L08','g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C8',2,'mc','auto','당근을 한 줄에 39개씩 26줄 놓았어요. 당근은 모두 몇 개인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X10','M3-2-u1-X07']::text[],true,'{"seq":6,"concept":"M3-2-u1-C8","difficulty":2,"kind":"mc","stem":"당근을 한 줄에 39개씩 26줄 놓았어요. 당근은 모두 몇 개인가요?","options":[{"t":"1014개","correct":true},{"t":"65개","mis":"M3-2-u1-X13"},{"t":"1064개","mis":"M3-2-u1-X10"},{"t":"312개","mis":"M3-2-u1-X07"}],"explanation":["39개씩 26번(묶음) — 곱셈식 39 × 26으로 세워요.","39 × 6 = 234, 39 × 20 = 780이에요.","39 × 26 = 1014 — 모두 1014개예요."],"variant_rule":{"alt":[{"stem":"견과류 과자를 한 판에 76개씩 72판 구웠어요. 과자는 모두 몇 개인가요?","options":[{"t":"5472개","correct":true},{"t":"148개","mis":"M3-2-u1-X13"},{"t":"5482개","mis":"M3-2-u1-X10"},{"t":"684개","mis":"M3-2-u1-X07"}],"explanation":["76개씩 72번(묶음) — 곱셈식 76 × 72로 세워요.","76 × 2 = 152, 76 × 70 = 5320이에요.","76 × 72 = 5472 — 모두 5472개예요."],"asset":null},{"stem":"미니 양배추가 한 상자에 66개씩 94상자 있어요. 미니 양배추는 모두 몇 개인가요?","options":[{"t":"6204개","correct":true},{"t":"160개","mis":"M3-2-u1-X13"},{"t":"6224개","mis":"M3-2-u1-X10"},{"t":"858개","mis":"M3-2-u1-X07"}],"explanation":["66개씩 94번(묶음) — 곱셈식 66 × 94로 세워요.","66 × 4 = 264, 66 × 90 = 5940이에요.","66 × 94 = 6204 — 모두 6204개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L08_basic#7','math',3,2,'u1','L08','g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C8',2,'ox','auto','39 × 26을 세로셈으로 계산하는데 셋째 줄 39 × 6에서 올림한 5를 넷째 줄 39 × 2에도 더해 1064라고 했어요. 바르게 계산했어요.',ARRAY['M3-2-u1-X10']::text[],true,'{"seq":7,"concept":"M3-2-u1-C8","difficulty":2,"kind":"ox","stem":"39 × 26을 세로셈으로 계산하는데 셋째 줄 39 × 6에서 올림한 5를 넷째 줄 39 × 2에도 더해 1064라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"줄마다 올림은 그 줄 안에서만 더해서","correct":true},{"t":"앞 줄에서 올림한 수는 다음 줄에도 더해야 해서","mis":"M3-2-u1-X10"}],"mis":"M3-2-u1-X10","explanation":["셋째 줄 39 × 6 = 234, 넷째 줄 39 × 2 = 78(한 자리 밀어).","234 + 780 = 1014예요.","1064는 앞 줄의 올림 5를 다시 더한 답이에요."],"asset":{"type":"expr_grid","rows":[["","","","3","9"],["×","","","2","6"],["","","2","3","4"],["","","8","3",""],["",null,null,null,null]]},"variant_rule":{"alt":[{"stem":"52 × 47을 세로셈으로 계산하는데 셋째 줄 52 × 7에서 올림한 1을 넷째 줄 52 × 4에도 더해 2454라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"줄마다 올림은 그 줄 안에서만 더해서","correct":true},{"t":"앞 줄에서 올림한 수는 다음 줄에도 더해야 해서","mis":"M3-2-u1-X10"}],"explanation":["셋째 줄 52 × 7 = 364, 넷째 줄 52 × 4 = 208(한 자리 밀어).","364 + 2080 = 2444예요.","2454는 앞 줄의 올림 1을 다시 더한 답이에요."],"asset":{"type":"expr_grid","rows":[["","","","5","2"],["×","","","4","7"],["","","3","6","4"],["","2","0","9",""],["",null,null,null,null]]}},{"stem":"77 × 57을 세로셈으로 계산하는데 셋째 줄 77 × 7에서 올림한 4를 넷째 줄 77 × 5에도 더해 4429라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"줄마다 올림은 그 줄 안에서만 더해서","correct":true},{"t":"앞 줄에서 올림한 수는 다음 줄에도 더해야 해서","mis":"M3-2-u1-X10"}],"explanation":["셋째 줄 77 × 7 = 539, 넷째 줄 77 × 5 = 385(한 자리 밀어).","539 + 3850 = 4389예요.","4429는 앞 줄의 올림 4를 다시 더한 답이에요."],"asset":{"type":"expr_grid","rows":[["","","","7","7"],["×","","","5","7"],["","","5","3","9"],["","3","8","9",""],["",null,null,null,null]]}}]}}'::jsonb) ON CONFL