INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L08_challenge#2','math',3,2,'u1','L08','g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C3',2,'ox','auto','48 × 36을 계산했더니 432가 나왔어요. 어림해 보면 알맞은 답이에요.',ARRAY['M3-2-u1-X12']::text[],true,'{"seq":2,"concept":"M3-2-u1-C3","difficulty":2,"kind":"ox","stem":"48 × 36을 계산했더니 432가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 2000과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u1-X12"}],"mis":"M3-2-u1-X12","explanation":["48 × 36을 어림하면 50 × 40 = 2000이에요.","432는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 48 × 36 = 1728이에요."],"variant_rule":{"alt":[{"stem":"38 × 44를 계산했더니 304가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 1600과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u1-X12"}],"explanation":["38 × 44를 어림하면 40 × 40 = 1600이에요.","304는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 38 × 44 = 1672예요."],"asset":null},{"stem":"56 × 48을 계산했더니 672가 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 약 3000과 너무 달라서","correct":true},{"t":"계산했으니 어림은 안 해도 되어서","mis":"M3-2-u1-X12"}],"explanation":["56 × 48을 어림하면 60 × 50 = 3000이에요.","672는 어림한 값과 너무 달라 틀린 답이에요.","바른 답은 56 × 48 = 2688이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L08_challenge#3','math',3,2,'u1','L08','g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',3,'sa','auto','지유가 44 × 26을 이렇게 계산해 352라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C8","difficulty":3,"kind":"sa","stem":"지유가 44 × 26을 이렇게 계산해 352라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["1144"],"explanation":["지유 — 넷째 줄을 한 자리 밀어 쓰지 않았어요.","44 × 6 = 264, 44 × 20 = 880.","264 + 880 = 1144예요."],"asset":{"type":"expr_grid","rows":[["","","","4","4"],["×","","","2","6"],["","","2","6","4"],["","","","8","8"],["","","3","5","2"]]},"variant_rule":{"alt":[{"stem":"시우가 84 × 86을 이렇게 계산해 1176이라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["7224"],"explanation":["시우 — 넷째 줄을 한 자리 밀어 쓰지 않았어요.","84 × 6 = 504, 84 × 80 = 6720.","504 + 6720 = 7224예요."],"asset":{"type":"expr_grid","rows":[["","","","8","4"],["×","","","8","6"],["","","5","0","4"],["","","6","7","2"],["","1","1","7","6"]]}},{"stem":"도윤이 76 × 17을 이렇게 계산해 608이라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["1292"],"explanation":["도윤 — 넷째 줄을 한 자리 밀어 쓰지 않았어요.","76 × 7 = 532, 76 × 10 = 760.","532 + 760 = 1292예요."],"asset":{"type":"expr_grid","rows":[["","","","7","6"],["×","","","1","7"],["","","5","3","2"],["","","","7","6"],["","","6","0","8"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L08_challenge#4','math',3,2,'u1','L08','g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',3,'mc','auto','곱을 견주어 ○ 안에 알맞은 것을 고르세요. 37 × 48 ○ 54 × 33',ARRAY['M3-2-u1-X11','M3-2-u1-X15']::text[],true,'{"seq":4,"concept":"M3-2-u1-C8","difficulty":3,"kind":"mc","stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 37 × 48 ○ 54 × 33","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["37 × 48 = 1776이에요.","54 × 33 = 1782예요.","1776 < 1782 — 알맞은 것은 <예요."],"variant_rule":{"alt":[{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 28 × 82 ○ 28 × 76","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["28 × 82 = 2296이에요.","28 × 76 = 2128이에요.","2296 > 2128 — 알맞은 것은 >예요."],"asset":null},{"stem":"곱을 견주어 ○ 안에 알맞은 것을 고르세요. 59 × 89 ○ 77 × 76","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X11"},{"t":"알 수 없다","mis":"M3-2-u1-X15"}],"explanation":["59 × 89 = 5251이에요.","77 × 76 = 5852예요.","5251 < 5852 — 알맞은 것은 <예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L08_challenge#5','math',3,2,'u1','L08','g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',3,'sa','auto','체험 프로그램 한 번에 39명씩 들어가요. 프로그램을 26번 열었어요. 모두 몇 명이 체험했나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C8","difficulty":3,"kind":"sa","stem":"체험 프로그램 한 번에 39명씩 들어가요. 프로그램을 26번 열었어요. 모두 몇 명이 체험했나요? 숫자로 쓰세요.","answer":["1014"],"explanation":["39명씩 26번(묶음) — 곱셈식 39 × 26으로 세워요.","39 × 6 = 234, 39 × 20 = 780이에요.","39 × 26 = 1014 — 모두 1014명이에요."],"variant_rule":{"alt":[{"stem":"한 상자에 도넛이 62개씩 들어 있어요. 이런 상자가 96상자 있어요. 도넛은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5952"],"explanation":["62개씩 96번(묶음) — 곱셈식 62 × 96으로 세워요.","62 × 6 = 372, 62 × 90 = 5580이에요.","62 × 96 = 5952 — 모두 5952개예요."],"asset":null},{"stem":"당근을 한 줄에 78개씩 32줄 놓았어요. 당근은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2496"],"explanation":["78개씩 32번(묶음) — 곱셈식 78 × 32로 세워요.","78 × 2 = 156, 78 × 30 = 2340이에요.","78 × 32 = 2496 — 모두 2496개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L08_challenge#6','math',3,2,'u1','L08','g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',3,'mc','auto','곱이 가장 큰 것은 어느 것인가요?',ARRAY['M3-2-u1-X11','M3-2-u1-X15']::text[],true,'{"seq":6,"concept":"M3-2-u1-C8","difficulty":3,"kind":"mc","stem":"곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"63 × 47","correct":true},{"t":"67 × 27","mis":"M3-2-u1-X11"},{"t":"69 × 18","mis":"M3-2-u1-X11"},{"t":"86 × 17","mis":"M3-2-u1-X15"}],"explanation":["하나씩 곱을 구해요.","63 × 47 = 2961, 67 × 27 = 1809, 69 × 18 = 1242, 86 × 17 = 1462.","곱이 가장 큰 것은 63 × 47 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"77 × 43","correct":true},{"t":"27 × 88","mis":"M3-2-u1-X11"},{"t":"23 × 49","mis":"M3-2-u1-X11"},{"t":"29 × 68","mis":"M3-2-u1-X15"}],"explanation":["하나씩 곱을 구해요.","77 × 43 = 3311, 27 × 88 = 2376, 23 × 49 = 1127, 29 × 68 = 1972.","곱이 가장 큰 것은 77 × 43 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"asset":null},{"stem":"이번에는 다른 수예요. 곱이 가장 큰 것은 어느 것인가요?","options":[{"t":"13 × 88","correct":true},{"t":"43 × 26","mis":"M3-2-u1-X11"},{"t":"59 × 19","mis":"M3-2-u1-X11"},{"t":"78 × 14","mis":"M3-2-u1-X15"}],"explanation":["하나씩 곱을 구해요.","13 × 88 = 1144, 43 × 26 = 1118, 59 × 19 = 1121, 78 × 14 = 1092.","곱이 가장 큰 것은 13 × 88 — 곱해지는 수가 크다고 곱이 가장 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L08_challenge#7','math',3,2,'u1','L08','g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',3,'error','auto','48 × 36을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X10','M3-2-u1-X15']::text[],true,'{"seq":7,"concept":"M3-2-u1-C8","difficulty":3,"kind":"error","stem":"48 × 36을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「48 × 36 = 1768이야」","correct":true,"mis_target":"M3-2-u1-X10"},{"t":"서윤 — 「48 × 36 = 1728이야」","mis":"M3-2-u1-X15"},{"t":"은우 — 「36 × 48 = 1728이야」","mis":"M3-2-u1-X15"}],"explanation":["48 × 6 = 288, 48 × 30 = 1440이에요.","48 × 36 = 1728이에요.","시우는 1768로 잘못 구했어요 — 줄마다 올림은 따로."],"variant_rule":{"alt":[{"stem":"53 × 27을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「53 × 27 = 1451이야」","correct":true,"mis_target":"M3-2-u1-X10"},{"t":"도윤 — 「53 × 27 = 1431이야」","mis":"M3-2-u1-X15"},{"t":"서윤 — 「어림하면 약 1500이야」","mis":"M3-2-u1-X15"}],"explanation":["53 × 7 = 371, 53 × 20 = 1060이에요.","53 × 27 = 1431이에요.","시우는 1451로 잘못 구했어요 — 줄마다 올림은 따로."],"asset":null},{"stem":"52 × 46을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「52 × 46 = 2402야」","correct":true,"mis_target":"M3-2-u1-X10"},{"t":"태오 — 「52 × 46 = 2392야」","mis":"M3-2-u1-X15"},{"t":"지유 — 「46 × 52 = 2392야」","mis":"M3-2-u1-X15"}],"explanation":["52 × 6 = 312, 52 × 40 = 2080이에요.","52 × 46 = 2392예요.","은우는 2402로 잘못 구했어요 — 줄마다 올림은 따로."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L08_challenge#8','math',3,2,'u1','L08','g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',4,'essay','teacher','견과류 과자를 한 판에 39개씩 26판 구웠어요. 39 × 26의 곱이 어느 사이에 있을지 어림하고, 계산한 값이 그 사이에 드는지 확인해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C8","difficulty":4,"kind":"essay","stem":"견과류 과자를 한 판에 39개씩 26판 구웠어요. 39 × 26의 곱이 어느 사이에 있을지 어림하고, 계산한 값이 그 사이에 드는지 확인해 보세요.","answer_guide":{"answer":"예: 39를 40, 26을 20과 30 사이로 보면 40 × 20 = 800, 40 × 30 = 1200이므로 곱은 800과 1200 사이이다. 39 × 6 = 234, 39 × 20 = 780, 더하면 1014이고 800과 1200 사이에 든다.","scoring_points":["800과 1200 사이로 어림했는가","234 + 780 = 1014를 구했는가","어림한 사이에 드는지 확인했는가"]},"explanation":["어림: 800과 1200 사이.","39 × 6 = 234, 39 × 20 = 780.","234 + 780 = 1014 — 사이에 들어요."],"asset":{"type":"expr_grid","rows":[["","","","3","9"],["×","","","2","6"],["","","2","3","4"],["","","7","8",""],["","1","0","1","4"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L08_challenge#9','math',3,2,'u1','L08','g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',4,'essay','teacher','친구가 63 × 45를 세로셈으로 계산하면서 넷째 줄 63 × 4 = 252를 한 자리 밀지 않고 써서 315 + 252 = 567이라고 했어요. 잘못을 설명하고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u1-C8","difficulty":4,"kind":"essay","stem":"친구가 63 × 45를 세로셈으로 계산하면서 넷째 줄 63 × 4 = 252를 한 자리 밀지 않고 써서 315 + 252 = 567이라고 했어요. 잘못을 설명하고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 45의 4는 40을 나타내므로 63 × 4 = 252는 2520을 뜻한다. 한 자리 밀어 써야 한다. 63 × 5 = 315, 63 × 40 = 2520, 더하면 2835이다.","scoring_points":["4가 40을 나타낸다고 설명했는가","2520을 한 자리 밀어 썼는가","2835를 구했는가"]},"explanation":["45 = 40 + 5.","63 × 5 = 315, 63 × 40 = 2520.","315 + 2520 = 2835."],"asset":{"type":"expr_grid","rows":[["","","","6","3"],["×","","","4","5"],["","","3","1","5"],["","","2","5","2"],["","","5","6","7"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L08_challenge#10','math',3,2,'u1','L08','g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',4,'sa','auto','시우가 37 × 48을 이렇게 계산해 1826이라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u1-C8","difficulty":4,"kind":"sa","stem":"시우가 37 × 48을 이렇게 계산해 1826이라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["1776"],"explanation":["시우 — 셋째 줄의 올림을 넷째 줄에 다시 더했어요.","37 × 8 = 296, 37 × 40 = 1480.","296 + 1480 = 1776이에요."],"asset":{"type":"expr_grid","rows":[["","","","3","7"],["×","","","4","8"],["","","2","9","6"],["","1","5","3",""],["","1","8","2","6"]]},"variant_rule":{"alt":[{"stem":"하랑이 32 × 69를 이렇게 계산해 2218이라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["2208"],"explanation":["하랑 — 셋째 줄의 올림을 넷째 줄에 다시 더했어요.","32 × 9 = 288, 32 × 60 = 1920.","288 + 1920 = 2208이에요."],"asset":{"type":"expr_grid","rows":[["","","","3","2"],["×","","","6","9"],["","","2","8","8"],["","1","9","3",""],["","2","2","1","8"]]}},{"stem":"하린이 74 × 36을 이렇게 계산해 2684라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["2664"],"explanation":["하린 — 셋째 줄의 올림을 넷째 줄에 다시 더했어요.","74 × 6 = 444, 74 × 30 = 2220.","444 + 2220 = 2664예요."],"asset":{"type":"expr_grid","rows":[["","","","7","4"],["×","","","3","6"],["","","4","4","4"],["","2","2","4",""],["","2","6","8","4"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_basic#1','math',3,2,'u1','L09','g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',1,'sa','auto','우리에게 물고기가 31마리 필요해요. 걸리버에게는 20배가 필요해요. 걸리버에게 물고기는 몇 마리 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C9","difficulty":1,"kind":"sa","stem":"우리에게 물고기가 31마리 필요해요. 걸리버에게는 20배가 필요해요. 걸리버에게 물고기는 몇 마리 필요한가요? 숫자로 쓰세요.","answer":["620"],"explanation":["「20배」는 31을 20번 더한 것 — 곱셈식 31 × 20으로 세워요.","곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","31 × 20 = 620 — 620마리예요."],"variant_rule":{"alt":[{"stem":"우리에게 사과가 38개 필요해요. 걸리버에게는 20배가 필요해요. 걸리버에게 사과는 몇 개 필요한가요? 숫자로 쓰세요.","answer":["760"],"explanation":["「20배」는 38을 20번 더한 것 — 곱셈식 38 × 20으로 세워요.","곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","38 × 20 = 760 — 760개예요."],"asset":null},{"stem":"우리에게 닭고기가 18조각 필요해요. 걸리버에게는 50배가 필요해요. 걸리버에게 닭고기는 몇 조각 필요한가요? 숫자로 쓰세요.","answer":["900"],"explanation":["「50배」는 18을 50번 더한 것 — 곱셈식 18 × 50으로 세워요.","곱하는 수가 5에서 50으로 10배가 되면 곱도 10배예요.","18 × 50 = 900 — 900조각이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_basic#2','math',3,2,'u1','L09','g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',1,'mc','auto','우리에게 가죽이 138장 필요해요. 걸리버에게는 6배가 필요해요. 걸리버에게 가죽이 몇 장 필요한지 구하는 식은 어느 것인가요?',ARRAY['M3-2-u1-X13']::text[],true,'{"seq":2,"concept":"M3-2-u1-C9","difficulty":1,"kind":"mc","stem":"우리에게 가죽이 138장 필요해요. 걸리버에게는 6배가 필요해요. 걸리버에게 가죽이 몇 장 필요한지 구하는 식은 어느 것인가요?","options":[{"t":"138 × 6","correct":true},{"t":"138 + 6","mis":"M3-2-u1-X13"},{"t":"6 × 6","mis":"M3-2-u1-X13"},{"t":"138 − 6","mis":"M3-2-u1-X13"}],"explanation":["「몇 배」는 같은 수를 여러 번 더한 것이에요.","138장 6배 → 138 × 6.","138 × 6 = 828이에요."],"variant_rule":{"alt":[{"stem":"우리에게 천이 129장 필요해요. 걸리버에게는 6배가 필요해요. 걸리버에게 천이 몇 장 필요한지 구하는 식은 어느 것인가요?","options":[{"t":"129 × 6","correct":true},{"t":"129 + 6","mis":"M3-2-u1-X13"},{"t":"6 × 6","mis":"M3-2-u1-X13"},{"t":"129 − 6","mis":"M3-2-u1-X13"}],"explanation":["「몇 배」는 같은 수를 여러 번 더한 것이에요.","129장 6배 → 129 × 6.","129 × 6 = 774예요."],"asset":null},{"stem":"우리에게 물이 192잔 필요해요. 걸리버에게는 4배가 필요해요. 걸리버에게 물이 몇 잔 필요한지 구하는 식은 어느 것인가요?","options":[{"t":"192 × 4","correct":true},{"t":"192 + 4","mis":"M3-2-u1-X13"},{"t":"4 × 4","mis":"M3-2-u1-X13"},{"t":"192 − 4","mis":"M3-2-u1-X13"}],"explanation":["「몇 배」는 같은 수를 여러 번 더한 것이에요.","192잔 4배 → 192 × 4.","192 × 4 = 768이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_basic#3','math',3,2,'u1','L09','g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',1,'mc','auto','우리에게 사과가 138개 필요해요. 걸리버에게는 6배가 필요해요. 걸리버에게 사과는 몇 개 필요한가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X03']::text[],true,'{"seq":3,"concept":"M3-2-u1-C9","difficulty":1,"kind":"mc","stem":"우리에게 사과가 138개 필요해요. 걸리버에게는 6배가 필요해요. 걸리버에게 사과는 몇 개 필요한가요?","options":[{"t":"828개","correct":true},{"t":"144개","mis":"M3-2-u1-X13"},{"t":"1028개","mis":"M3-2-u1-X03"},{"t":"1828개","mis":"M3-2-u1-X03"}],"explanation":["「6배」는 138을 6번 더한 것 — 곱셈식 138 × 6으로 세워요.","일의 자리 8 × 6 = 48 → 4 올림, 십의 자리 3 × 6 + 4 = 22 → 2 올림.","138 × 6 = 828 — 828개예요."],"variant_rule":{"alt":[{"stem":"우리에게 닭고기가 128조각 필요해요. 걸리버에게는 7배가 필요해요. 걸리버에게 닭고기는 몇 조각 필요한가요?","options":[{"t":"896조각","correct":true},{"t":"135조각","mis":"M3-2-u1-X13"},{"t":"1196조각","mis":"M3-2-u1-X03"},{"t":"1496조각","mis":"M3-2-u1-X03"}],"explanation":["「7배」는 128을 7번 더한 것 — 곱셈식 128 × 7로 세워요.","일의 자리 8 × 7 = 56 → 5 올림, 십의 자리 2 × 7 + 5 = 19 → 1 올림.","128 × 7 = 896 — 896조각이에요."],"asset":null},{"stem":"우리에게 빵이 143개 필요해요. 걸리버에게는 7배가 필요해요. 걸리버에게 빵은 몇 개 필요한가요?","options":[{"t":"1001개","correct":true},{"t":"150개","mis":"M3-2-u1-X13"},{"t":"1121개","mis":"M3-2-u1-X03"},{"t":"2801개","mis":"M3-2-u1-X03"}],"explanation":["「7배」는 143을 7번 더한 것 — 곱셈식 143 × 7로 세워요.","일의 자리 3 × 7 = 21 → 2 올림, 십의 자리 4 × 7 + 2 = 30 → 3 올림, 백의 자리 1 × 7 + 3 = 10 → 천의 자리.","143 × 7 = 1001 — 1001개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_basic#4','math',3,2,'u1','L09','g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',1,'ox','auto','우리에게 사과가 17개 필요해요. 걸리버에게는 27배가 필요해요. 걸리버에게 사과가 몇 개 필요한지는 17 + 27로 구해요.',ARRAY['M3-2-u1-X13']::text[],true,'{"seq":4,"concept":"M3-2-u1-C9","difficulty":1,"kind":"ox","stem":"우리에게 사과가 17개 필요해요. 걸리버에게는 27배가 필요해요. 걸리버에게 사과가 몇 개 필요한지는 17 + 27로 구해요.","answer":"X","reason_options":[{"t":"「27배」는 17을 27번 더한 것이라 곱셈으로 구해서","correct":true},{"t":"「배」가 나오면 두 수를 더하면 되어서","mis":"M3-2-u1-X13"}],"mis":"M3-2-u1-X13","explanation":["「27배」는 17씩 27번이에요.","그래서 17 × 27.","17 × 27 = 459개 — 17 + 27 = 44가 아니에요."],"variant_rule":{"alt":[{"stem":"우리에게 닭고기가 55조각 필요해요. 걸리버에게는 49배가 필요해요. 걸리버에게 닭고기가 몇 조각 필요한지는 55 + 49로 구해요.","answer":"X","reason_options":[{"t":"「49배」는 55를 49번 더한 것이라 곱셈으로 구해서","correct":true},{"t":"「배」가 나오면 두 수를 더하면 되어서","mis":"M3-2-u1-X13"}],"explanation":["「49배」는 55씩 49번이에요.","그래서 55 × 49.","55 × 49 = 2695조각 — 55 + 49 = 104가 아니에요."],"asset":null},{"stem":"우리에게 빵이 23개 필요해요. 걸리버에게는 31배가 필요해요. 걸리버에게 빵이 몇 개 필요한지는 23 + 31로 구해요.","answer":"X","reason_options":[{"t":"「31배」는 23을 31번 더한 것이라 곱셈으로 구해서","correct":true},{"t":"「배」가 나오면 두 수를 더하면 되어서","mis":"M3-2-u1-X13"}],"explanation":["「31배」는 23씩 31번이에요.","그래서 23 × 31.","23 × 31 = 713개 — 23 + 31 = 54가 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_basic#5','math',3,2,'u1','L09','g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',2,'sa','auto','우리에게 단추가 17개 필요해요. 걸리버에게는 27배가 필요해요. 걸리버에게 단추는 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C9","difficulty":2,"kind":"sa","stem":"우리에게 단추가 17개 필요해요. 걸리버에게는 27배가 필요해요. 걸리버에게 단추는 몇 개 필요한가요? 숫자로 쓰세요.","answer":["459"],"explanation":["「27배」는 17을 27번 더한 것 — 곱셈식 17 × 27로 세워요.","17 × 7 = 119, 17 × 20 = 340이에요.","17 × 27 = 459 — 459개예요."],"variant_rule":{"alt":[{"stem":"우리에게 실이 34타래 필요해요. 걸리버에게는 44배가 필요해요. 걸리버에게 실은 몇 타래 필요한가요? 숫자로 쓰세요.","answer":["1496"],"explanation":["「44배」는 34를 44번 더한 것 — 곱셈식 34 × 44로 세워요.","34 × 4 = 136, 34 × 40 = 1360이에요.","34 × 44 = 1496 — 1496타래예요."],"asset":null},{"stem":"우리에게 가죽이 54장 필요해요. 걸리버에게는 28배가 필요해요. 걸리버에게 가죽은 몇 장 필요한가요? 숫자로 쓰세요.","answer":["1512"],"explanation":["「28배」는 54를 28번 더한 것 — 곱셈식 54 × 28로 세워요.","54 × 8 = 432, 54 × 20 = 1080이에요.","54 × 28 = 1512 — 1512장이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_basic#6','math',3,2,'u1','L09','g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',2,'mc','auto','우리에게 물고기가 5마리 필요해요. 걸리버에게는 49배가 필요해요. 걸리버에게 물고기는 몇 마리 필요한가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X07','M3-2-u1-X08']::text[],true,'{"seq":6,"concept":"M3-2-u1-C9","difficulty":2,"kind":"mc","stem":"우리에게 물고기가 5마리 필요해요. 걸리버에게는 49배가 필요해요. 걸리버에게 물고기는 몇 마리 필요한가요?","options":[{"t":"245마리","correct":true},{"t":"54마리","mis":"M3-2-u1-X13"},{"t":"65마리","mis":"M3-2-u1-X07"},{"t":"45마리","mis":"M3-2-u1-X08"}],"explanation":["「49배」는 5를 49번 더한 것 — 곱셈식 5 × 49로 세워요.","5 × 9 = 45, 5 × 40 = 200이에요.","5 × 49 = 245 — 245마리예요."],"variant_rule":{"alt":[{"stem":"우리에게 사과가 4개 필요해요. 걸리버에게는 47배가 필요해요. 걸리버에게 사과는 몇 개 필요한가요?","options":[{"t":"188개","correct":true},{"t":"51개","mis":"M3-2-u1-X13"},{"t":"44개","mis":"M3-2-u1-X07"},{"t":"28개","mis":"M3-2-u1-X08"}],"explanation":["「47배」는 4를 47번 더한 것 — 곱셈식 4 × 47로 세워요.","4 × 7 = 28, 4 × 40 = 160이에요.","4 × 47 = 188 — 188개예요."],"asset":null},{"stem":"우리에게 닭고기가 8조각 필요해요. 걸리버에게는 58배가 필요해요. 걸리버에게 닭고기는 몇 조각 필요한가요?","options":[{"t":"464조각","correct":true},{"t":"66조각","mis":"M3-2-u1-X13"},{"t":"104조각","mis":"M3-2-u1-X07"},{"t":"64조각","mis":"M3-2-u1-X08"}],"explanation":["「58배」는 8을 58번 더한 것 — 곱셈식 8 × 58로 세워요.","8 × 8 = 64, 8 × 50 = 400이에요.","8 × 58 = 464 — 464조각이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_basic#7','math',3,2,'u1','L09','g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C3',2,'mc','auto','우리에게 물이 51잔 필요해요. 걸리버에게는 19배가 필요해요. 걸리버에게 필요한 물을 어림하면 약 몇 잔인가요?',ARRAY['M3-2-u1-X06','M3-2-u1-X13']::text[],true,'{"seq":7,"concept":"M3-2-u1-C3","difficulty":2,"kind":"mc","stem":"우리에게 물이 51잔 필요해요. 걸리버에게는 19배가 필요해요. 걸리버에게 필요한 물을 어림하면 약 몇 잔인가요?","options":[{"t":"약 1000잔","correct":true},{"t":"약 100잔","mis":"M3-2-u1-X06"},{"t":"약 10000잔","mis":"M3-2-u1-X06"},{"t":"약 70잔","mis":"M3-2-u1-X13"}],"explanation":["51을 50, 19를 20으로 어림해요.","50 × 20 = 1000이에요.","실제로는 51 × 19 = 969잔 — 어림한 값과 가까워요."],"variant_rule":{"alt":[{"stem":"우리에게 물고기가 33마리 필요해요. 걸리버에게는 21배가 필요해요. 걸리버에게 필요한 물고기를 어림하면 약 몇 마리인가요?","options":[{"t":"약 600마리","correct":true},{"t":"약 60마리","mis":"M3-2-u1-X06"},{"t":"약 6000마리","mis":"M3-2-u1-X06"},{"t":"약 50마리","mis":"M3-2-u1-X13"}],"explanation":["33을 30, 21을 20으로 어림해요.","30 × 20 = 600이에요.","실제로는 33 × 21 = 693마리 — 어림한 값과 가까워요."],"asset":null},{"stem":"우리에게 사과가 26개 필요해요. 걸리버에게는 19배가 필요해요. 걸리버에게 필요한 사과를 어림하면 약 몇 개인가요?","options":[{"t":"약 600개","correct":true},{"t":"약 60개","mis":"M3-2-u1-X06"},{"t":"약 6000개","mis":"M3-2-u1-X06"},{"t":"약 50개","mis":"M3-2-u1-X13"}],"explanation":["26을 30, 19를 20으로 어림해요.","30 × 20 = 600이에요.","실제로는 26 × 19 = 494개 — 어림한 값과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_basic#8','math',3,2,'u1','L09','g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',2,'sa','auto','우리에게 사과가 109개 필요해요. 걸리버에게는 8배가 필요해요. 걸리버에게 사과는 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u1-C9","difficulty":2,"kind":"sa","stem":"우리에게 사과가 109개 필요해요. 걸리버에게는 8배가 필요해요. 걸리버에게 사과는 몇 개 필요한가요? 숫자로 쓰세요.","answer":["872"],"explanation":["「8배」는 109를 8번 더한 것 — 곱셈식 109 × 8로 세워요.","일의 자리 9 × 8 = 72 → 7 올림.","109 × 8 = 872 — 872개예요."],"variant_rule":{"alt":[{"stem":"우리에게 닭고기가 236조각 필요해요. 걸리버에게는 3배가 필요해요. 걸리버에게 닭고기는 몇 조각 필요한가요? 숫자로 쓰세요.","answer":["708"],"explanation":["「3배」는 236을 3번 더한 것 — 곱셈식 236 × 3으로 세워요.","일의 자리 6 × 3 = 18 → 1 올림, 십의 자리 3 × 3 + 1 = 10 → 1 올림.","236 × 3 = 708 — 708조각이에요."],"asset":null},{"stem":"우리에게 빵이 169개 필요해요. 걸리버에게는 4배가 필요해요. 걸리버에게 빵은 몇 개 필요한가요? 숫자로 쓰세요.","answer":["676"],"explanation":["「4배」는 169를 4번 더한 것 — 곱셈식 169 × 4로 세워요.","일의 자리 9 × 4 = 36 → 3 올림, 십의 자리 6 × 4 + 3 = 27 → 2 올림.","169 × 4 = 676 — 676개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_basic#9','math',3,2,'u1','L09','g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',2,'match','auto','걸리버에게 필요한 양을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u1-C9","difficulty":2,"kind":"match","stem":"걸리버에게 필요한 양을 알맞게 이으세요.","pairs":[{"l":"가죽 17장의 48배","r":"816장"},{"l":"천 34장의 16배","r":"544장"},{"l":"물 49잔의 23배","r":"1127잔"}],"mis":"M3-2-u1-X13","explanation":["「몇 배」는 곱셈이에요.","17 × 48 = 816, 34 × 16 = 544, 49 × 23 = 1127.","어림한 값과 가까운지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 걸리버에게 필요한 양을 알맞게 이으세요.","pairs":[{"l":"천 23장의 38배","r":"874장"},{"l":"물 49잔의 28배","r":"1372잔"},{"l":"물고기 33마리의 39배","r":"1287마리"}],"explanation":["「몇 배」는 곱셈이에요.","23 × 38 = 874, 49 × 28 = 1372, 33 × 39 = 1287.","어림한 값과 가까운지 확인해요."],"asset":null},{"stem":"이번에는 다른 수예요. 걸리버에게 필요한 양을 알맞게 이으세요.","pairs":[{"l":"물 47잔의 44배","r":"2068잔"},{"l":"물고기 36마리의 42배","r":"1512마리"},{"l":"사과 35개의 49배","r":"1715개"}],"explanation":["「몇 배」는 곱셈이에요.","47 × 44 = 2068, 36 × 42 = 1512, 35 × 49 = 1715.","어림한 값과 가까운지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_basic#10','math',3,2,'u1','L09','g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',3,'mc','auto','우리에게 가죽이 31장 필요하고 걸리버에게는 그 20배가 필요해요. 천은 우리에게 138장 필요하고 걸리버에게는 그 6배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?',ARRAY['M3-2-u1-X08','M3-2-u1-X13']::text[],true,'{"seq":10,"concept":"M3-2-u1-C9","difficulty":3,"kind":"mc","stem":"우리에게 가죽이 31장 필요하고 걸리버에게는 그 20배가 필요해요. 천은 우리에게 138장 필요하고 걸리버에게는 그 6배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"1448장","correct":true},{"t":"620장","mis":"M3-2-u1-X08"},{"t":"828장","mis":"M3-2-u1-X08"},{"t":"169장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 31 × 20 = 620장.","천: 138 × 6 = 828장.","620 + 828 = 1448 — 모두 1448장이에요."],"variant_rule":{"alt":[{"stem":"우리에게 가죽이 24장 필요하고 걸리버에게는 그 30배가 필요해요. 천은 우리에게 125장 필요하고 걸리버에게는 그 4배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"1220장","correct":true},{"t":"720장","mis":"M3-2-u1-X08"},{"t":"500장","mis":"M3-2-u1-X08"},{"t":"149장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 24 × 30 = 720장.","천: 125 × 4 = 500장.","720 + 500 = 1220 — 모두 1220장이에요."],"asset":null},{"stem":"우리에게 가죽이 42장 필요하고 걸리버에게는 그 20배가 필요해요. 천은 우리에게 116장 필요하고 걸리버에게는 그 7배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"1652장","correct":true},{"t":"840장","mis":"M3-2-u1-X08"},{"t":"812장","mis":"M3-2-u1-X08"},{"t":"158장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 42 × 20 = 840장.","천: 116 × 7 = 812장.","840 + 812 = 1652 — 모두 1652장이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_challenge#1','math',3,2,'u1','L09','g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',2,'sa','auto','우리에게 천이 8장 필요해요. 걸리버에게는 35배가 필요해요. 걸리버에게 천은 몇 장 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C9","difficulty":2,"kind":"sa","stem":"우리에게 천이 8장 필요해요. 걸리버에게는 35배가 필요해요. 걸리버에게 천은 몇 장 필요한가요? 숫자로 쓰세요.","answer":["280"],"explanation":["「35배」는 8을 35번 더한 것 — 곱셈식 8 × 35로 세워요.","8 × 5 = 40, 8 × 30 = 240이에요.","8 × 35 = 280 — 280장이에요."],"variant_rule":{"alt":[{"stem":"우리에게 물이 4잔 필요해요. 걸리버에게는 57배가 필요해요. 걸리버에게 물은 몇 잔 필요한가요? 숫자로 쓰세요.","answer":["228"],"explanation":["「57배」는 4를 57번 더한 것 — 곱셈식 4 × 57로 세워요.","4 × 7 = 28, 4 × 50 = 200이에요.","4 × 57 = 228 — 228잔이에요."],"asset":null},{"stem":"우리에게 물고기가 7마리 필요해요. 걸리버에게는 47배가 필요해요. 걸리버에게 물고기는 몇 마리 필요한가요? 숫자로 쓰세요.","answer":["329"],"explanation":["「47배」는 7을 47번 더한 것 — 곱셈식 7 × 47로 세워요.","7 × 7 = 49, 7 × 40 = 280이에요.","7 × 47 = 329 — 329마리예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_challenge#2','math',3,2,'u1','L09','g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',2,'error','auto','우리에게 천이 51장 필요해요. 걸리버에게는 19배가 필요해요. 걸리버에게 천이 몇 장 필요한지 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X09','M3-2-u1-X15']::text[],true,'{"seq":2,"concept":"M3-2-u1-C9","difficulty":2,"kind":"error","stem":"우리에게 천이 51장 필요해요. 걸리버에게는 19배가 필요해요. 걸리버에게 천이 몇 장 필요한지 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「509장」","correct":true,"mis_target":"M3-2-u1-X09"},{"t":"하랑 — 「51 × 19 = 969장」","mis":"M3-2-u1-X15"},{"t":"하린 — 「어림하면 약 1000장」","mis":"M3-2-u1-X15"}],"explanation":["「19배」는 51 × 19.","51 × 9 = 459, 51 × 10 = 510이에요.","51 × 19 = 969장 — 시우가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"우리에게 물이 27잔 필요해요. 걸리버에게는 34배가 필요해요. 걸리버에게 물이 몇 잔 필요한지 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「61잔」","correct":true,"mis_target":"M3-2-u1-X13"},{"t":"은우 — 「27 × 34 = 918잔」","mis":"M3-2-u1-X15"},{"t":"하랑 — 「어림하면 약 900잔」","mis":"M3-2-u1-X15"}],"explanation":["「34배」는 27 × 34.","27 × 4 = 108, 27 × 30 = 810이에요.","27 × 34 = 918잔 — 시우가 잘못 말했어요."],"asset":null},{"stem":"우리에게 물고기가 58마리 필요해요. 걸리버에게는 23배가 필요해요. 걸리버에게 물고기가 몇 마리 필요한지 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「1354마리」","correct":true,"mis_target":"M3-2-u1-X10"},{"t":"서윤 — 「58 × 23 = 1334마리」","mis":"M3-2-u1-X15"},{"t":"시우 — 「어림하면 약 1200마리」","mis":"M3-2-u1-X15"}],"explanation":["「23배」는 58 × 23.","58 × 3 = 174, 58 × 20 = 1160이에요.","58 × 23 = 1334마리 — 하린이 잘못 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_challenge#3','math',3,2,'u1','L09','g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',3,'sa','auto','우리에게 가죽이 23장 필요하고 걸리버에게는 그 30배가 필요해요. 천은 우리에게 146장 필요하고 걸리버에게는 그 5배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C9","difficulty":3,"kind":"sa","stem":"우리에게 가죽이 23장 필요하고 걸리버에게는 그 30배가 필요해요. 천은 우리에게 146장 필요하고 걸리버에게는 그 5배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요? 숫자로 쓰세요.","answer":["1420"],"explanation":["가죽: 23 × 30 = 690장.","천: 146 × 5 = 730장.","690 + 730 = 1420 — 모두 1420장이에요."],"variant_rule":{"alt":[{"stem":"우리에게 가죽이 36장 필요하고 걸리버에게는 그 20배가 필요해요. 천은 우리에게 214장 필요하고 걸리버에게는 그 4배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요? 숫자로 쓰세요.","answer":["1576"],"explanation":["가죽: 36 × 20 = 720장.","천: 214 × 4 = 856장.","720 + 856 = 1576 — 모두 1576장이에요."],"asset":null},{"stem":"우리에게 가죽이 15장 필요하고 걸리버에게는 그 40배가 필요해요. 천은 우리에게 132장 필요하고 걸리버에게는 그 6배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요? 숫자로 쓰세요.","answer":["1392"],"explanation":["가죽: 15 × 40 = 600장.","천: 132 × 6 = 792장.","600 + 792 = 1392 — 모두 1392장이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_challenge#4','math',3,2,'u1','L09','g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',3,'sa','auto','걸리버는 물을 우리의 17잔의 27배, 우유를 우리의 12잔의 35배 마셔요. 걸리버가 마시는 물과 우유는 몇 잔 차이가 나나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u1-C9","difficulty":3,"kind":"sa","stem":"걸리버는 물을 우리의 17잔의 27배, 우유를 우리의 12잔의 35배 마셔요. 걸리버가 마시는 물과 우유는 몇 잔 차이가 나나요? 숫자로 쓰세요.","answer":["39"],"explanation":["물: 17 × 27 = 459잔.","우유: 12 × 35 = 420잔.","459 − 420 = 39 — 물이 39잔 더 많아요."],"variant_rule":{"alt":[{"stem":"걸리버는 물을 우리의 23잔의 18배, 우유를 우리의 14잔의 26배 마셔요. 걸리버가 마시는 물과 우유는 몇 잔 차이가 나나요? 숫자로 쓰세요.","answer":["50"],"explanation":["물: 23 × 18 = 414잔.","우유: 14 × 26 = 364잔.","414 − 364 = 50 — 물이 50잔 더 많아요."],"asset":null},{"stem":"걸리버는 물을 우리의 19잔의 24배, 우유를 우리의 16잔의 31배 마셔요. 걸리버가 마시는 물과 우유는 몇 잔 차이가 나나요? 숫자로 쓰세요.","answer":["40"],"explanation":["물: 19 × 24 = 456잔.","우유: 16 × 31 = 496잔.","496 − 456 = 40 — 우유가 40잔 더 많아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_challenge#5','math',3,2,'u1','L09','g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',3,'mc','auto','우리에게 물이 17잔 필요해요. 걸리버에게는 48배가 필요해요. 걸리버에게 물은 몇 잔 필요한가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X09','M3-2-u1-X07']::text[],true,'{"seq":5,"concept":"M3-2-u1-C9","difficulty":3,"kind":"mc","stem":"우리에게 물이 17잔 필요해요. 걸리버에게는 48배가 필요해요. 걸리버에게 물은 몇 잔 필요한가요?","options":[{"t":"816잔","correct":true},{"t":"65잔","mis":"M3-2-u1-X13"},{"t":"456잔","mis":"M3-2-u1-X09"},{"t":"204잔","mis":"M3-2-u1-X07"}],"explanation":["「48배」는 17을 48번 더한 것 — 곱셈식 17 × 48로 세워요.","17 × 8 = 136, 17 × 40 = 680이에요.","17 × 48 = 816 — 816잔이에요."],"variant_rule":{"alt":[{"stem":"우리에게 물고기가 42마리 필요해요. 걸리버에게는 47배가 필요해요. 걸리버에게 물고기는 몇 마리 필요한가요?","options":[{"t":"1974마리","correct":true},{"t":"89마리","mis":"M3-2-u1-X13"},{"t":"1984마리","mis":"M3-2-u1-X10"},{"t":"462마리","mis":"M3-2-u1-X07"}],"explanation":["「47배」는 42를 47번 더한 것 — 곱셈식 42 × 47로 세워요.","42 × 7 = 294, 42 × 40 = 1680이에요.","42 × 47 = 1974 — 1974마리예요."],"asset":null},{"stem":"우리에게 사과가 59개 필요해요. 걸리버에게는 37배가 필요해요. 걸리버에게 사과는 몇 개 필요한가요?","options":[{"t":"2183개","correct":true},{"t":"96개","mis":"M3-2-u1-X13"},{"t":"2243개","mis":"M3-2-u1-X10"},{"t":"590개","mis":"M3-2-u1-X07"}],"explanation":["「37배」는 59를 37번 더한 것 — 곱셈식 59 × 37로 세워요.","59 × 7 = 413, 59 × 30 = 1770이에요.","59 × 37 = 2183 — 2183개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_challenge#6','math',3,2,'u1','L09','g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',3,'mc','auto','걸리버 옷에 단추는 우리의 16개의 23배, 구슬은 우리의 12개의 29배가 필요해요. 어느 것이 더 많이 필요한가요?',ARRAY['M3-2-u1-X15','M3-2-u1-X11']::text[],true,'{"seq":6,"concept":"M3-2-u1-C9","difficulty":3,"kind":"mc","stem":"걸리버 옷에 단추는 우리의 16개의 23배, 구슬은 우리의 12개의 29배가 필요해요. 어느 것이 더 많이 필요한가요?","options":[{"t":"단추","correct":true},{"t":"구슬","mis":"M3-2-u1-X15"},{"t":"둘이 같아요","mis":"M3-2-u1-X11"},{"t":"알 수 없어요","mis":"M3-2-u1-X15"}],"explanation":["단추: 16 × 23 = 368개.","구슬: 12 × 29 = 348개.","단추가 더 많이 필요해요."],"variant_rule":{"alt":[{"stem":"걸리버 옷에 단추는 우리의 27개의 14배, 구슬은 우리의 19개의 21배가 필요해요. 어느 것이 더 많이 필요한가요?","options":[{"t":"구슬","correct":true},{"t":"단추","mis":"M3-2-u1-X15"},{"t":"둘이 같아요","mis":"M3-2-u1-X11"},{"t":"알 수 없어요","mis":"M3-2-u1-X15"}],"explanation":["단추: 27 × 14 = 378개.","구슬: 19 × 21 = 399개.","구슬이 더 많이 필요해요."],"asset":null},{"stem":"걸리버 옷에 단추는 우리의 34개의 18배, 구슬은 우리의 26개의 22배가 필요해요. 어느 것이 더 많이 필요한가요?","options":[{"t":"단추","correct":true},{"t":"구슬","mis":"M3-2-u1-X15"},{"t":"둘이 같아요","mis":"M3-2-u1-X11"},{"t":"알 수 없어요","mis":"M3-2-u1-X15"}],"explanation":["단추: 34 × 18 = 612개.","구슬: 26 × 22 = 572개.","단추가 더 많이 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_challenge#7','math',3,2,'u1','L09','g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',3,'sa','auto','마을에 천이 1000장 있어요. 걸리버의 이불에는 우리 이불 천 31장의 20배가 필요해요. 이불을 만들고 남는 천은 몇 장인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u1-C9","difficulty":3,"kind":"sa","stem":"마을에 천이 1000장 있어요. 걸리버의 이불에는 우리 이불 천 31장의 20배가 필요해요. 이불을 만들고 남는 천은 몇 장인가요? 숫자로 쓰세요.","answer":["380"],"explanation":["필요한 천: 31 × 20 = 620장.","남는 천: 1000 − 620.","1000 − 620 = 380 — 380장이 남아요."],"variant_rule":{"alt":[{"stem":"마을에 천이 2000장 있어요. 걸리버의 이불에는 우리 이불 천 48장의 35배가 필요해요. 이불을 만들고 남는 천은 몇 장인가요? 숫자로 쓰세요.","answer":["320"],"explanation":["필요한 천: 48 × 35 = 1680장.","남는 천: 2000 − 1680.","2000 − 1680 = 320 — 320장이 남아요."],"asset":null},{"stem":"마을에 천이 1500장 있어요. 걸리버의 이불에는 우리 이불 천 26장의 43배가 필요해요. 이불을 만들고 남는 천은 몇 장인가요? 숫자로 쓰세요.","answer":["382"],"explanation":["필요한 천: 26 × 43 = 1118장.","남는 천: 1500 − 1118.","1500 − 1118 = 382 — 382장이 남아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_challenge#8','math',3,2,'u1','L09','g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',4,'essay','teacher','「12개가 필요한데 걸리버에게는 25배가 필요하다」로 걸리버 문제를 하나 만들고, 식과 답을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C9","difficulty":4,"kind":"essay","stem":"「12개가 필요한데 걸리버에게는 25배가 필요하다」로 걸리버 문제를 하나 만들고, 식과 답을 써 보세요.","answer_guide":{"answer":"예: 「우리에게 빵이 12개 필요해요. 걸리버에게는 25배가 필요해요. 걸리버에게 빵은 몇 개 필요할까요?」 — 12 × 25 = 300(12 × 5 = 60, 12 × 20 = 240), 빵 300개.","scoring_points":["12의 25배인 문제를 만들었는가","12 × 25로 식을 세웠는가","300을 구했는가"]},"explanation":["「25배」 → 12 × 25.","12 × 5 = 60, 12 × 20 = 240.","60 + 240 = 300."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_challenge#9','math',3,2,'u1','L09','g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',4,'essay','teacher','걸리버에게 가죽은 우리가 쓰는 31장의 20배, 천은 우리가 쓰는 138장의 6배가 필요해요. 필요한 가죽과 천의 수를 각각 구하고, 어느 것이 몇 장 더 필요한지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u1-C9","difficulty":4,"kind":"essay","stem":"걸리버에게 가죽은 우리가 쓰는 31장의 20배, 천은 우리가 쓰는 138장의 6배가 필요해요. 필요한 가죽과 천의 수를 각각 구하고, 어느 것이 몇 장 더 필요한지 써 보세요.","answer_guide":{"answer":"예: 가죽 31 × 20 = 620장(31 × 2 = 62의 10배), 천 138 × 6 = 828장(600 + 180 + 48). 천이 828 − 620 = 208장 더 필요하다.","scoring_points":["가죽 620장을 구했는가","천 828장을 구했는가","천이 208장 더 필요하다고 답했는가"]},"explanation":["가죽 31 × 20 = 620.","천 138 × 6 = 828.","828 − 620 = 208."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_L09_challenge#10','math',3,2,'u1','L09','g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',4,'mc','auto','우리에게 가죽이 47장 필요하고 걸리버에게는 그 30배가 필요해요. 천은 우리에게 168장 필요하고 걸리버에게는 그 6배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?',ARRAY['M3-2-u1-X08','M3-2-u1-X13']::text[],true,'{"seq":10,"concept":"M3-2-u1-C9","difficulty":4,"kind":"mc","stem":"우리에게 가죽이 47장 필요하고 걸리버에게는 그 30배가 필요해요. 천은 우리에게 168장 필요하고 걸리버에게는 그 6배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"2418장","correct":true},{"t":"1410장","mis":"M3-2-u1-X08"},{"t":"1008장","mis":"M3-2-u1-X08"},{"t":"215장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 47 × 30 = 1410장.","천: 168 × 6 = 1008장.","1410 + 1008 = 2418 — 모두 2418장이에요."],"variant_rule":{"alt":[{"stem":"우리에게 가죽이 38장 필요하고 걸리버에게는 그 40배가 필요해요. 천은 우리에게 245장 필요하고 걸리버에게는 그 4배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"2500장","correct":true},{"t":"1520장","mis":"M3-2-u1-X08"},{"t":"980장","mis":"M3-2-u1-X08"},{"t":"283장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 38 × 40 = 1520장.","천: 245 × 4 = 980장.","1520 + 980 = 2500 — 모두 2500장이에요."],"asset":null},{"stem":"우리에게 가죽이 29장 필요하고 걸리버에게는 그 50배가 필요해요. 천은 우리에게 174장 필요하고 걸리버에게는 그 5배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"2320장","correct":true},{"t":"1450장","mis":"M3-2-u1-X08"},{"t":"870장","mis":"M3-2-u1-X08"},{"t":"203장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 29 × 50 = 1450장.","천: 174 × 5 = 870장.","1450 + 870 = 2320 — 모두 2320장이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#1','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C1',1,'sa','auto','220 × 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C1","difficulty":1,"kind":"sa","stem":"220 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["880"],"explanation":["220을 200, 20, 0으로 갈라 곱해요: 200 × 4 = 800, 20 × 4 = 80, 0 × 4 = 0.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","800 + 80 + 0 = 880 — 어림한 200 × 4 = 800과 가까워요."],"variant_rule":{"alt":[{"stem":"203 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["406"],"explanation":["203을 200, 0, 3으로 갈라 곱해요: 200 × 2 = 400, 0 × 2 = 0, 3 × 2 = 6.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","400 + 0 + 6 = 406 — 어림한 200 × 2 = 400과 가까워요."],"asset":null},{"stem":"312 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["936"],"explanation":["312를 300, 10, 2로 갈라 곱해요: 300 × 3 = 900, 10 × 3 = 30, 2 × 3 = 6.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요.","900 + 30 + 6 = 936 — 어림한 300 × 3 = 900과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#2','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C1',1,'sa','auto','111 × 3을 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u1-C1","difficulty":1,"kind":"sa","stem":"111 × 3을 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["111을 100, 10, 1로 갈라요.","□는 1 × 3 = 3이에요.","300 + 30 + 3 = 333 — 111 × 3의 곱이에요."],"asset":{"type":"expr_grid","rows":[["100 × 3","=","300"],["10 × 3","=","30"],["1 × 3","=",null],["300 + 30 + □","=","333"]]},"variant_rule":{"alt":[{"stem":"423 × 2를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["800"],"explanation":["423을 400, 20, 3으로 갈라요.","□는 400 × 2 = 800이에요.","800 + 40 + 6 = 846 — 423 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["400 × 2","=",null],["20 × 2","=","40"],["3 × 2","=","6"],["□ + 40 + 6","=","846"]]}},{"stem":"222 × 4를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["80"],"explanation":["222를 200, 20, 2로 갈라요.","□는 20 × 4 = 80이에요.","800 + 80 + 8 = 888 — 222 × 4의 곱이에요."],"asset":{"type":"expr_grid","rows":[["200 × 4","=","800"],["20 × 4","=",null],["2 × 4","=","8"],["800 + □ + 8","=","888"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#3','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C2',1,'sa','auto','116 × 5는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C2","difficulty":1,"kind":"sa","stem":"116 × 5는 얼마인가요? 숫자로 쓰세요.","answer":["580"],"explanation":["116을 100, 10, 6으로 갈라 곱해요: 100 × 5 = 500, 10 × 5 = 50, 6 × 5 = 30.","일의 자리 6 × 5 = 30 → 3 올림.","500 + 50 + 30 = 580 — 어림한 100 × 5 = 500과 가까워요."],"variant_rule":{"alt":[{"stem":"124 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["372"],"explanation":["124를 100, 20, 4로 갈라 곱해요: 100 × 3 = 300, 20 × 3 = 60, 4 × 3 = 12.","일의 자리 4 × 3 = 12 → 1 올림.","300 + 60 + 12 = 372 — 어림한 100 × 3 = 300과 가까워요."],"asset":null},{"stem":"118 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["354"],"explanation":["118을 100, 10, 8로 갈라 곱해요: 100 × 3 = 300, 10 × 3 = 30, 8 × 3 = 24.","일의 자리 8 × 3 = 24 → 2 올림.","300 + 30 + 24 = 354 — 어림한 100 × 3 = 300과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#4','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C4',1,'sa','auto','145 × 7은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u1-C4","difficulty":1,"kind":"sa","stem":"145 × 7은 얼마인가요? 숫자로 쓰세요.","answer":["1015"],"explanation":["145를 100, 40, 5로 갈라 곱해요: 100 × 7 = 700, 40 × 7 = 280, 5 × 7 = 35.","일의 자리 5 × 7 = 35 → 3 올림, 십의 자리 4 × 7 + 3 = 31 → 3 올림, 백의 자리 1 × 7 + 3 = 10 → 천의 자리.","700 + 280 + 35 = 1015 — 어림한 100 × 7 = 700과 가까워요."],"variant_rule":{"alt":[{"stem":"873 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["2619"],"explanation":["873을 800, 70, 3으로 갈라 곱해요: 800 × 3 = 2400, 70 × 3 = 210, 3 × 3 = 9.","십의 자리 7 × 3 = 21 → 2 올림, 백의 자리 8 × 3 + 2 = 26 → 천의 자리.","2400 + 210 + 9 = 2619 — 어림한 900 × 3 = 2700과 가까워요."],"asset":null},{"stem":"970 × 8은 얼마인가요? 숫자로 쓰세요.","answer":["7760"],"explanation":["970을 900, 70, 0으로 갈라 곱해요: 900 × 8 = 7200, 70 × 8 = 560, 0 × 8 = 0.","십의 자리 7 × 8 = 56 → 5 올림, 백의 자리 9 × 8 + 5 = 77 → 천의 자리.","7200 + 560 + 0 = 7760 — 어림한 1000 × 8 = 8000과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#5','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C5',1,'sa','auto','70 × 60은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C5","difficulty":1,"kind":"sa","stem":"70 × 60은 얼마인가요? 숫자로 쓰세요.","answer":["4200"],"explanation":["7 × 6 = 42예요.","70 × 6 = 420, 곱하는 수가 6에서 60으로 10배가 되면 곱도 10배예요.","70 × 60 = 420의 10배 = 4200이에요."],"variant_rule":{"alt":[{"stem":"30 × 40은 얼마인가요? 숫자로 쓰세요.","answer":["1200"],"explanation":["3 × 4 = 12예요.","30 × 4 = 120, 곱하는 수가 4에서 40으로 10배가 되면 곱도 10배예요.","30 × 40 = 120의 10배 = 1200이에요."],"asset":null},{"stem":"90 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["2700"],"explanation":["9 × 3 = 27이에요.","90 × 3 = 270, 곱하는 수가 3에서 30으로 10배가 되면 곱도 10배예요.","90 × 30 = 270의 10배 = 2700이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#6','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C6',1,'sa','auto','7 × 36은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u1-C6","difficulty":1,"kind":"sa","stem":"7 × 36은 얼마인가요? 숫자로 쓰세요.","answer":["252"],"explanation":["곱하는 수 36을 30과 6으로 갈라요.","7 × 6 = 42, 7 × 30 = 210이에요.","42 + 210 = 252예요."],"variant_rule":{"alt":[{"stem":"4 × 16은 얼마인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["곱하는 수 16을 10과 6으로 갈라요.","4 × 6 = 24, 4 × 10 = 40이에요.","24 + 40 = 64예요."],"asset":null},{"stem":"7 × 53은 얼마인가요? 숫자로 쓰세요.","answer":["371"],"explanation":["곱하는 수 53을 50과 3으로 갈라요.","7 × 3 = 21, 7 × 50 = 350이에요.","21 + 350 = 371이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#7','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C7',1,'sa','auto','19 × 26은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u1-C7","difficulty":1,"kind":"sa","stem":"19 × 26은 얼마인가요? 숫자로 쓰세요.","answer":["494"],"explanation":["곱하는 수 26을 20과 6으로 갈라요.","19 × 6 = 114, 19 × 20 = 380이에요.","114 + 380 = 494 — 어림한 20 × 30 = 600과 가까워요."],"variant_rule":{"alt":[{"stem":"22 × 32는 얼마인가요? 숫자로 쓰세요.","answer":["704"],"explanation":["곱하는 수 32를 30과 2로 갈라요.","22 × 2 = 44, 22 × 30 = 660이에요.","44 + 660 = 704 — 어림한 20 × 30 = 600과 가까워요."],"asset":null},{"stem":"33 × 14는 얼마인가요? 숫자로 쓰세요.","answer":["462"],"explanation":["곱하는 수 14를 10과 4로 갈라요.","33 × 4 = 132, 33 × 10 = 330이에요.","132 + 330 = 462 — 어림한 30 × 10 = 300과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#8','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C3',1,'mc','auto','217 × 4를 어림하면 약 얼마인가요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],true,'{"seq":8,"concept":"M3-2-u1-C3","difficulty":1,"kind":"mc","stem":"217 × 4를 어림하면 약 얼마인가요?","options":[{"t":"약 800","correct":true},{"t":"약 400","mis":"M3-2-u1-X12"},{"t":"약 204","mis":"M3-2-u1-X12"},{"t":"약 8000","mis":"M3-2-u1-X06"}],"explanation":["217은 가까운 몇백 200으로 어림해요.","200 × 4 = 800이에요.","그래서 약 800이에요 — 실제 곱 868과 가까워요."],"variant_rule":{"alt":[{"stem":"149 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 200","correct":true},{"t":"약 102","mis":"M3-2-u1-X12"},{"t":"약 2000","mis":"M3-2-u1-X06"},{"t":"약 100","mis":"M3-2-u1-X12"}],"explanation":["149는 가까운 몇백 100으로 어림해요.","100 × 2 = 200이에요.","그래서 약 200이에요 — 실제 곱 298과 가까워요."],"asset":null},{"stem":"215 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 400","correct":true},{"t":"약 200","mis":"M3-2-u1-X12"},{"t":"약 202","mis":"M3-2-u1-X12"},{"t":"약 4000","mis":"M3-2-u1-X06"}],"explanation":["215는 가까운 몇백 200으로 어림해요.","200 × 2 = 400이에요.","그래서 약 400이에요 — 실제 곱 430과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#9','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C2',2,'sa','auto','152 × 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u1-C2","difficulty":2,"kind":"sa","stem":"152 × 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["0"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 5 × 4 = 20 → 0을 써요.","152 × 4 = 608 — 십의 자리 숫자는 0이에요."],"asset":{"type":"expr_grid","rows":[["올림","","2","",""],["","","1","5","2"],["×","","","","4"],["","","6",null,"8"]]},"variant_rule":{"alt":[{"stem":"131 × 6의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 3 × 6 = 18 → 8을 써요.","131 × 6 = 786 — 십의 자리 숫자는 8이에요."],"asset":{"type":"expr_grid","rows":[["올림","","1","",""],["","","1","3","1"],["×","","","","6"],["","","7",null,"6"]]}},{"stem":"151 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["세로셈은 일의 자리부터 곱해요.","백의 자리: 1 × 2 + 올림 1 = 3 → 3을 써요.","151 × 2 = 302 — 백의 자리 숫자는 3이에요."],"asset":{"type":"expr_grid","rows":[["올림","","1","",""],["","","1","5","1"],["×","","","","2"],["","",null,"0","2"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#10','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C4',2,'sa','auto','587 × 5의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u1-C4","difficulty":2,"kind":"sa","stem":"587 × 5의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["백의 자리 곱 5 × 5 + 올림 4 = 29예요.","10을 넘은 2가 천의 자리로 가요.","587 × 5 = 2935 — 천의 자리 숫자는 2예요."],"variant_rule":{"alt":[{"stem":"288 × 6의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["백의 자리 곱 2 × 6 + 올림 5 = 17이에요.","10을 넘은 1이 천의 자리로 가요.","288 × 6 = 1728 — 천의 자리 숫자는 1이에요."],"asset":null},{"stem":"711 × 6의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["백의 자리 곱 7 × 6 = 42예요.","10을 넘은 4가 천의 자리로 가요.","711 × 6 = 4266 — 천의 자리 숫자는 4예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#11','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C5',2,'sa','auto','74 × 8 = 592예요. 그러면 74 × 80은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-2-u1-C5","difficulty":2,"kind":"sa","stem":"74 × 8 = 592예요. 그러면 74 × 80은 얼마인가요? 숫자로 쓰세요.","answer":["5920"],"explanation":["곱하는 수 80은 8의 10배예요.","곱하는 수가 10배가 되면 곱도 10배가 돼요.","592의 10배 — 74 × 80 = 5920이에요."],"variant_rule":{"alt":[{"stem":"87 × 6 = 522예요. 그러면 87 × 60은 얼마인가요? 숫자로 쓰세요.","answer":["5220"],"explanation":["곱하는 수 60은 6의 10배예요.","곱하는 수가 10배가 되면 곱도 10배가 돼요.","522의 10배 — 87 × 60 = 5220이에요."],"asset":null},{"stem":"75 × 8 = 600이에요. 그러면 75 × 80은 얼마인가요? 숫자로 쓰세요.","answer":["6000"],"explanation":["곱하는 수 80은 8의 10배예요.","곱하는 수가 10배가 되면 곱도 10배가 돼요.","600의 10배 — 75 × 80 = 6000이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#12','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C6',2,'ox','auto','4 × 83의 곱과 83 × 4의 곱은 같아요.',ARRAY['M3-2-u1-X16']::text[],true,'{"seq":12,"concept":"M3-2-u1-C6","difficulty":2,"kind":"ox","stem":"4 × 83의 곱과 83 × 4의 곱은 같아요.","answer":"O","reason_options":[{"t":"곱하는 두 수의 순서를 바꾸어도 곱은 같아서","correct":true},{"t":"곱해지는 수가 커지면 곱도 커져서","mis":"M3-2-u1-X16"}],"mis":"M3-2-u1-X16","explanation":["4 × 83 = 332예요.","83 × 4 = 332예요.","순서를 바꾸어도 곱은 같아요 — 계산하기 쉬운 쪽으로 구해도 돼요."],"variant_rule":{"alt":[{"stem":"8 × 96의 곱과 96 × 8의 곱은 같아요.","answer":"O","reason_options":[{"t":"곱하는 두 수의 순서를 바꾸어도 곱은 같아서","correct":true},{"t":"곱해지는 수가 커지면 곱도 커져서","mis":"M3-2-u1-X16"}],"explanation":["8 × 96 = 768이에요.","96 × 8 = 768이에요.","순서를 바꾸어도 곱은 같아요 — 계산하기 쉬운 쪽으로 구해도 돼요."],"asset":null},{"stem":"9 × 16의 곱과 16 × 9의 곱은 같아요.","answer":"O","reason_options":[{"t":"곱하는 두 수의 순서를 바꾸어도 곱은 같아서","correct":true},{"t":"곱해지는 수가 커지면 곱도 커져서","mis":"M3-2-u1-X16"}],"explanation":["9 × 16 = 144예요.","16 × 9 = 144예요.","순서를 바꾸어도 곱은 같아요 — 계산하기 쉬운 쪽으로 구해도 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#13','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C7',2,'sa','auto','69 × 14를 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M3-2-u1-C7","difficulty":2,"kind":"sa","stem":"69 × 14를 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["690"],"explanation":["곱하는 수 14를 4와 10으로 갈라요.","□는 69 × 10 = 690이에요.","276 + 690 = 966 — 69 × 14의 곱이에요."],"asset":{"type":"expr_grid","rows":[["69 × 4","=","276"],["69 × 10","=",null],["276 + □","=","966"]]},"variant_rule":{"alt":[{"stem":"29 × 12를 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["58"],"explanation":["곱하는 수 12를 2와 10으로 갈라요.","□는 29 × 2 = 58이에요.","58 + 290 = 348 — 29 × 12의 곱이에요."],"asset":{"type":"expr_grid","rows":[["29 × 2","=",null],["29 × 10","=","290"],["□ + 290","=","348"]]}},{"stem":"34 × 19를 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["340"],"explanation":["곱하는 수 19를 9와 10으로 갈라요.","□는 34 × 10 = 340이에요.","306 + 340 = 646 — 34 × 19의 곱이에요."],"asset":{"type":"expr_grid","rows":[["34 × 9","=","306"],["34 × 10","=",null],["306 + □","=","646"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#14','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C8',2,'sa','auto','37 × 77은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-2-u1-C8","difficulty":2,"kind":"sa","stem":"37 × 77은 얼마인가요? 숫자로 쓰세요.","answer":["2849"],"explanation":["곱하는 수 77을 70과 7로 갈라요.","37 × 7 = 259, 37 × 70 = 2590이에요.","259 + 2590 = 2849 — 어림한 40 × 80 = 3200과 가까워요."],"variant_rule":{"alt":[{"stem":"54 × 87은 얼마인가요? 숫자로 쓰세요.","answer":["4698"],"explanation":["곱하는 수 87을 80과 7로 갈라요.","54 × 7 = 378, 54 × 80 = 4320이에요.","378 + 4320 = 4698 — 어림한 50 × 90 = 4500과 가까워요."],"asset":null},{"stem":"74 × 59는 얼마인가요? 숫자로 쓰세요.","answer":["4366"],"explanation":["곱하는 수 59를 50과 9로 갈라요.","74 × 9 = 666, 74 × 50 = 3700이에요.","666 + 3700 = 4366 — 어림한 70 × 60 = 4200과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#15','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C3',2,'mc','auto','29 × 68을 어림하면 곱은 어느 사이에 있나요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],true,'{"seq":15,"concept":"M3-2-u1-C3","difficulty":2,"kind":"mc","stem":"29 × 68을 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"1200보다 크고 2100보다 작아요","correct":true},{"t":"1200보다 작아요","mis":"M3-2-u1-X12"},{"t":"2100보다 커요","mis":"M3-2-u1-X12"},{"t":"120보다 크고 210보다 작아요","mis":"M3-2-u1-X06"}],"explanation":["29는 20과 30 사이, 68은 60과 70 사이예요.","20 × 60 = 1200, 30 × 70 = 2100이에요.","29 × 68 = 1972 — 그 사이에 들어요."],"variant_rule":{"alt":[{"stem":"36 × 94를 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"2700보다 크고 4000보다 작아요","correct":true},{"t":"2700보다 작아요","mis":"M3-2-u1-X12"},{"t":"4000보다 커요","mis":"M3-2-u1-X12"},{"t":"270보다 크고 400보다 작아요","mis":"M3-2-u1-X06"}],"explanation":["36은 30과 40 사이, 94는 90과 100 사이예요.","30 × 90 = 2700, 40 × 100 = 4000이에요.","36 × 94 = 3384 — 그 사이에 들어요."],"asset":null},{"stem":"99 × 94를 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"8100보다 크고 10000보다 작아요","correct":true},{"t":"8100보다 작아요","mis":"M3-2-u1-X12"},{"t":"10000보다 커요","mis":"M3-2-u1-X12"},{"t":"810보다 크고 1000보다 작아요","mis":"M3-2-u1-X06"}],"explanation":["99는 90과 100 사이, 94는 90과 100 사이예요.","90 × 90 = 8100, 100 × 100 = 10000이에요.","99 × 94 = 9306 — 그 사이에 들어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#16','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C9',2,'sa','auto','우리에게 가죽이 31장 필요해요. 걸리버에게는 20배가 필요해요. 걸리버에게 가죽은 몇 장 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-2-u1-C9","difficulty":2,"kind":"sa","stem":"우리에게 가죽이 31장 필요해요. 걸리버에게는 20배가 필요해요. 걸리버에게 가죽은 몇 장 필요한가요? 숫자로 쓰세요.","answer":["620"],"explanation":["「20배」는 31을 20번 더한 것 — 곱셈식 31 × 20으로 세워요.","곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","31 × 20 = 620 — 620장이에요."],"variant_rule":{"alt":[{"stem":"우리에게 천이 53장 필요해요. 걸리버에게는 40배가 필요해요. 걸리버에게 천은 몇 장 필요한가요? 숫자로 쓰세요.","answer":["2120"],"explanation":["「40배」는 53을 40번 더한 것 — 곱셈식 53 × 40으로 세워요.","곱하는 수가 4에서 40으로 10배가 되면 곱도 10배예요.","53 × 40 = 2120 — 2120장이에요."],"asset":null},{"stem":"우리에게 물이 48잔 필요해요. 걸리버에게는 20배가 필요해요. 걸리버에게 물은 몇 잔 필요한가요? 숫자로 쓰세요.","answer":["960"],"explanation":["「20배」는 48을 20번 더한 것 — 곱셈식 48 × 20으로 세워요.","곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","48 × 20 = 960 — 960잔이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#17','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C1',3,'error','auto','110 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X05','M3-2-u1-X15']::text[],true,'{"seq":17,"concept":"M3-2-u1-C1","difficulty":3,"kind":"error","stem":"110 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「110 × 7 = 777이야」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"서윤 — 「110 × 7 = 770이야」","mis":"M3-2-u1-X15"},{"t":"하랑 — 「어림하면 약 700이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","110 × 7 = 770이에요.","은우는 777로 잘못 구했어요 — 0에 곱하면 0."],"variant_rule":{"alt":[{"stem":"204 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「204 × 2 = 428이야」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"시우 — 「204 × 2 = 408이야」","mis":"M3-2-u1-X15"},{"t":"은우 — 「2 × 204 = 408이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","204 × 2 = 408이에요.","서윤은 428로 잘못 구했어요 — 0에 곱하면 0."],"asset":null},{"stem":"430 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「430 × 2 = 862야」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"도윤 — 「430 × 2 = 860이야」","mis":"M3-2-u1-X15"},{"t":"하린 — 「어림하면 약 800이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","430 × 2 = 860이에요.","서윤은 862로 잘못 구했어요 — 0에 곱하면 0."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#18','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C2',3,'ox','auto','223 × 4를 계산하는데 일의 자리에서 십의 자리로 올림한 1을 더하지 않고 882라고 했어요. 바르게 계산했어요.',ARRAY['M3-2-u1-X02']::text[],true,'{"seq":18,"concept":"M3-2-u1-C2","difficulty":3,"kind":"ox","stem":"223 × 4를 계산하는데 일의 자리에서 십의 자리로 올림한 1을 더하지 않고 882라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수는 윗자리를 곱한 다음 꼭 더해야 해서","correct":true},{"t":"올림한 수는 작게 적어 두기만 하면 되어서","mis":"M3-2-u1-X02"}],"mis":"M3-2-u1-X02","explanation":["일의 자리 3 × 4 = 12 → 1 올림.","223 × 4 = 892예요.","882는 올림한 1을 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["올림","","","1",""],["","","2","2","3"],["×","","","","4"],["","",null,null,null]]},"variant_rule":{"alt":[{"stem":"336 × 2를 계산하는데 일의 자리에서 십의 자리로 올림한 1을 더하지 않고 662라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수는 윗자리를 곱한 다음 꼭 더해야 해서","correct":true},{"t":"올림한 수는 작게 적어 두기만 하면 되어서","mis":"M3-2-u1-X02"}],"explanation":["일의 자리 6 × 2 = 12 → 1 올림.","336 × 2 = 672예요.","662는 올림한 1을 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["올림","","","1",""],["","","3","3","6"],["×","","","","2"],["","",null,null,null]]}},{"stem":"108 × 3을 계산하는데 일의 자리에서 십의 자리로 올림한 2를 더하지 않고 304라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수는 윗자리를 곱한 다음 꼭 더해야 해서","correct":true},{"t":"올림한 수는 작게 적어 두기만 하면 되어서","mis":"M3-2-u1-X02"}],"explanation":["일의 자리 8 × 3 = 24 → 2 올림.","108 × 3 = 324예요.","304는 올림한 2를 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["올림","","","2",""],["","","1","0","8"],["×","","","","3"],["","",null,null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#19','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C4',3,'error','auto','864 × 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X03','M3-2-u1-X15']::text[],true,'{"seq":19,"concept":"M3-2-u1-C4","difficulty":3,"kind":"error","stem":"864 × 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「864 × 5 = 4400이야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"도윤 — 「864 × 5 = 4320이야」","mis":"M3-2-u1-X15"},{"t":"서윤 — 「5 × 864 = 4320이야」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 4 × 5 = 20 → 2 올림, 십의 자리 6 × 5 + 2 = 32 → 3 올림, 백의 자리 8 × 5 + 3 = 43 → 천의 자리.","864 × 5 = 4320이에요.","은우는 4400으로 잘못 구했어요 — 곱한 다음에 더하기."],"variant_rule":{"alt":[{"stem":"477 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「477 × 7 = 3579야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"서윤 — 「477 × 7 = 3339야」","mis":"M3-2-u1-X15"},{"t":"지유 — 「어림하면 약 3500이야」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 7 × 7 = 49 → 4 올림, 십의 자리 7 × 7 + 4 = 53 → 5 올림, 백의 자리 4 × 7 + 5 = 33 → 천의 자리.","477 × 7 = 3339예요.","은우는 3579로 잘못 구했어요 — 곱한 다음에 더하기."],"asset":null},{"stem":"558 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「558 × 8 = 4884야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"지유 — 「558 × 8 = 4464야」","mis":"M3-2-u1-X15"},{"t":"은우 — 「8 × 558 = 4464야」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 8 × 8 = 64 → 6 올림, 십의 자리 5 × 8 + 6 = 46 → 4 올림, 백의 자리 5 × 8 + 4 = 44 → 천의 자리.","558 × 8 = 4464예요.","도윤은 4884로 잘못 구했어요 — 곱한 다음에 더하기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#20','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C5',3,'error','auto','87 × 70을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X06','M3-2-u1-X15']::text[],true,'{"seq":20,"concept":"M3-2-u1-C5","difficulty":3,"kind":"error","stem":"87 × 70을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「87 × 70 = 609야」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"시우 — 「87 × 70 = 6090이야」","mis":"M3-2-u1-X15"},{"t":"하랑 — 「어림하면 약 6300이야」","mis":"M3-2-u1-X15"}],"explanation":["곱하는 수가 7에서 70으로 10배가 되면 곱도 10배예요.","87 × 70 = 6090이에요.","지유는 609로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배."],"variant_rule":{"alt":[{"stem":"11 × 40을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「11 × 40 = 44야」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"하린 — 「11 × 40 = 440이야」","mis":"M3-2-u1-X15"},{"t":"하랑 — 「40 × 11 = 440이야」","mis":"M3-2-u1-X15"}],"explanation":["곱하는 수가 4에서 40으로 10배가 되면 곱도 10배예요.","11 × 40 = 440이에요.","시우는 44로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배."],"asset":null},{"stem":"27 × 30을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「27 × 30 = 81이야」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"시우 — 「27 × 30 = 810이야」","mis":"M3-2-u1-X15"},{"t":"은우 — 「어림하면 약 900이야」","mis":"M3-2-u1-X15"}],"explanation":["곱하는 수가 3에서 30으로 10배가 되면 곱도 10배예요.","27 × 30 = 810이에요.","도윤은 81로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#21','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C8',3,'ox','auto','58 × 99를 세로셈으로 계산하는데 셋째 줄 58 × 9에서 올림한 7을 넷째 줄 58 × 9에도 더해 5812라고 했어요. 바르게 계산했어요.',ARRAY['M3-2-u1-X10']::text[],true,'{"seq":21,"concept":"M3-2-u1-C8","difficulty":3,"kind":"ox","stem":"58 × 99를 세로셈으로 계산하는데 셋째 줄 58 × 9에서 올림한 7을 넷째 줄 58 × 9에도 더해 5812라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"줄마다 올림은 그 줄 안에서만 더해서","correct":true},{"t":"앞 줄에서 올림한 수는 다음 줄에도 더해야 해서","mis":"M3-2-u1-X10"}],"mis":"M3-2-u1-X10","explanation":["셋째 줄 58 × 9 = 522, 넷째 줄 58 × 9 = 522(한 자리 밀어).","522 + 5220 = 5742예요.","5812는 앞 줄의 올림 7을 다시 더한 답이에요."],"asset":{"type":"expr_grid","rows":[["","","","5","8"],["×","","","9","9"],["","","5","2","2"],["","5","2","9",""],["",null,null,null,null]]},"variant_rule":{"alt":[{"stem":"67 × 37을 세로셈으로 계산하는데 셋째 줄 67 × 7에서 올림한 4를 넷째 줄 67 × 3에도 더해 2519라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"줄마다 올림은 그 줄 안에서만 더해서","correct":true},{"t":"앞 줄에서 올림한 수는 다음 줄에도 더해야 해서","mis":"M3-2-u1-X10"}],"explanation":["셋째 줄 67 × 7 = 469, 넷째 줄 67 × 3 = 201(한 자리 밀어).","469 + 2010 = 2479예요.","2519는 앞 줄의 올림 4를 다시 더한 답이에요."],"asset":{"type":"expr_grid","rows":[["","","","6","7"],["×","","","3","7"],["","","4","6","9"],["","2","0","5",""],["",null,null,null,null]]}},{"stem":"84 × 36을 세로셈으로 계산하는데 셋째 줄 84 × 6에서 올림한 2를 넷째 줄 84 × 3에도 더해 3044라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"줄마다 올림은 그 줄 안에서만 더해서","correct":true},{"t":"앞 줄에서 올림한 수는 다음 줄에도 더해야 해서","mis":"M3-2-u1-X10"}],"explanation":["셋째 줄 84 × 6 = 504, 넷째 줄 84 × 3 = 252(한 자리 밀어).","504 + 2520 = 3024예요.","3044는 앞 줄의 올림 2를 다시 더한 답이에요."],"asset":{"type":"expr_grid","rows":[["","","","8","4"],["×","","","3","6"],["","","5","0","4"],["","2","5","4",""],["",null,null,null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#22','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C9',3,'mc','auto','우리에게 가죽이 31장 필요하고 걸리버에게는 그 20배가 필요해요. 천은 우리에게 138장 필요하고 걸리버에게는 그 6배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?',ARRAY['M3-2-u1-X08','M3-2-u1-X13']::text[],true,'{"seq":22,"concept":"M3-2-u1-C9","difficulty":3,"kind":"mc","stem":"우리에게 가죽이 31장 필요하고 걸리버에게는 그 20배가 필요해요. 천은 우리에게 138장 필요하고 걸리버에게는 그 6배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"1448장","correct":true},{"t":"620장","mis":"M3-2-u1-X08"},{"t":"828장","mis":"M3-2-u1-X08"},{"t":"169장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 31 × 20 = 620장.","천: 138 × 6 = 828장.","620 + 828 = 1448 — 모두 1448장이에요."],"variant_rule":{"alt":[{"stem":"우리에게 가죽이 24장 필요하고 걸리버에게는 그 30배가 필요해요. 천은 우리에게 125장 필요하고 걸리버에게는 그 4배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"1220장","correct":true},{"t":"720장","mis":"M3-2-u1-X08"},{"t":"500장","mis":"M3-2-u1-X08"},{"t":"149장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 24 × 30 = 720장.","천: 125 × 4 = 500장.","720 + 500 = 1220 — 모두 1220장이에요."],"asset":null},{"stem":"우리에게 가죽이 42장 필요하고 걸리버에게는 그 20배가 필요해요. 천은 우리에게 116장 필요하고 걸리버에게는 그 7배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"1652장","correct":true},{"t":"840장","mis":"M3-2-u1-X08"},{"t":"812장","mis":"M3-2-u1-X08"},{"t":"158장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 42 × 20 = 840장.","천: 116 × 7 = 812장.","840 + 812 = 1652 — 모두 1652장이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#23','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C4',4,'sa','auto','수 카드 6, 4, 2, 3을 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-2-u1-C4","difficulty":4,"kind":"sa","stem":"수 카드 6, 4, 2, 3을 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.","answer":["2592"],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 6을 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 432를 만들어요.","432 × 6 = 2592 — 큰 수를 백의 자리에 놓은 643 × 2 = 1286보다 커요."],"variant_rule":{"alt":[{"stem":"수 카드 5, 7, 4, 3을 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.","answer":["3801"],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 7을 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 543을 만들어요.","543 × 7 = 3801 — 큰 수를 백의 자리에 놓은 754 × 3 = 2262보다 커요."],"asset":null},{"stem":"수 카드 8, 2, 4, 6을 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.","answer":["5136"],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 8을 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 642를 만들어요.","642 × 8 = 5136 — 큰 수를 백의 자리에 놓은 864 × 2 = 1728보다 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#24','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C8',4,'sa','auto','은우가 66 × 77을 이렇게 계산해 5122라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-2-u1-C8","difficulty":4,"kind":"sa","stem":"은우가 66 × 77을 이렇게 계산해 5122라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["5082"],"explanation":["은우 — 셋째 줄의 올림을 넷째 줄에 다시 더했어요.","66 × 7 = 462, 66 × 70 = 4620.","462 + 4620 = 5082예요."],"asset":{"type":"expr_grid","rows":[["","","","6","6"],["×","","","7","7"],["","","4","6","2"],["","4","6","6",""],["","5","1","2","2"]]},"variant_rule":{"alt":[{"stem":"도윤이 17 × 76을 이렇게 계산해 221이라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["1292"],"explanation":["도윤 — 넷째 줄을 한 자리 밀어 쓰지 않았어요.","17 × 6 = 102, 17 × 70 = 1190.","102 + 1190 = 1292예요."],"asset":{"type":"expr_grid","rows":[["","","","1","7"],["×","","","7","6"],["","","1","0","2"],["","","1","1","9"],["","","2","2","1"]]}},{"stem":"도윤이 44 × 89를 이렇게 계산해 3946이라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["3916"],"explanation":["도윤 — 셋째 줄의 올림을 넷째 줄에 다시 더했어요.","44 × 9 = 396, 44 × 80 = 3520.","396 + 3520 = 3916이에요."],"asset":{"type":"expr_grid","rows":[["","","","4","4"],["×","","","8","9"],["","","3","9","6"],["","3","5","5",""],["","3","9","4","6"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_a#25','math',3,2,'u1','','g3_2_math_u1_review_a','unit_review','M3-2-u1-C4',4,'essay','teacher','한 개에 972원인 인형을 5개 사려고 해요. 필요한 돈을 어림한 뒤 계산하고, 어림한 값과 견주어 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u1-C4","difficulty":4,"kind":"essay","stem":"한 개에 972원인 인형을 5개 사려고 해요. 필요한 돈을 어림한 뒤 계산하고, 어림한 값과 견주어 보세요.","answer_guide":{"answer":"예: 972를 1000쯤으로 보면 1000 × 5 = 5000이다. 900 × 5 = 4500, 70 × 5 = 350, 2 × 5 = 10, 더하면 4860원이다. 5000에 가깝다.","scoring_points":["1000 × 5 = 5000으로 어림했는가","4860을 구했는가","어림과 견주었는가"]},"explanation":["어림 약 5000.","4500 + 350 + 10 = 4860.","972 × 5 = 4860원."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#1','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C1',1,'sa','auto','344 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C1","difficulty":1,"kind":"sa","stem":"344 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["688"],"explanation":["344를 300, 40, 4로 갈라 곱해요: 300 × 2 = 600, 40 × 2 = 80, 4 × 2 = 8.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요.","600 + 80 + 8 = 688 — 어림한 300 × 2 = 600과 가까워요."],"variant_rule":{"alt":[{"stem":"203 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["406"],"explanation":["203을 200, 0, 3으로 갈라 곱해요: 200 × 2 = 400, 0 × 2 = 0, 3 × 2 = 6.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","400 + 0 + 6 = 406 — 어림한 200 × 2 = 400과 가까워요."],"asset":null},{"stem":"142 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["284"],"explanation":["142를 100, 40, 2로 갈라 곱해요: 100 × 2 = 200, 40 × 2 = 80, 2 × 2 = 4.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요.","200 + 80 + 4 = 284 — 어림한 100 × 2 = 200과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#2','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C1',1,'sa','auto','120 × 4를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u1-C1","difficulty":1,"kind":"sa","stem":"120 × 4를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["80"],"explanation":["120을 100, 20, 0으로 갈라요.","□는 20 × 4 = 80이에요.","400 + 80 + 0 = 480 — 120 × 4의 곱이에요."],"asset":{"type":"expr_grid","rows":[["100 × 4","=","400"],["20 × 4","=",null],["0 × 4","=","0"],["400 + □ + 0","=","480"]]},"variant_rule":{"alt":[{"stem":"420 × 2를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["800"],"explanation":["420을 400, 20, 0으로 갈라요.","□는 400 × 2 = 800이에요.","800 + 40 + 0 = 840 — 420 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["400 × 2","=",null],["20 × 2","=","40"],["0 × 2","=","0"],["□ + 40 + 0","=","840"]]}},{"stem":"242 × 2를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["400"],"explanation":["242를 200, 40, 2로 갈라요.","□는 200 × 2 = 400이에요.","400 + 80 + 4 = 484 — 242 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["200 × 2","=",null],["40 × 2","=","80"],["2 × 2","=","4"],["□ + 80 + 4","=","484"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#3','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C2',1,'sa','auto','319 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C2","difficulty":1,"kind":"sa","stem":"319 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["957"],"explanation":["319를 300, 10, 9로 갈라 곱해요: 300 × 3 = 900, 10 × 3 = 30, 9 × 3 = 27.","일의 자리 9 × 3 = 27 → 2 올림.","900 + 30 + 27 = 957 — 어림한 300 × 3 = 900과 가까워요."],"variant_rule":{"alt":[{"stem":"104 × 5는 얼마인가요? 숫자로 쓰세요.","answer":["520"],"explanation":["104를 100, 0, 4로 갈라 곱해요: 100 × 5 = 500, 0 × 5 = 0, 4 × 5 = 20.","일의 자리 4 × 5 = 20 → 2 올림.","500 + 0 + 20 = 520 — 어림한 100 × 5 = 500과 가까워요."],"asset":null},{"stem":"439 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["878"],"explanation":["439를 400, 30, 9로 갈라 곱해요: 400 × 2 = 800, 30 × 2 = 60, 9 × 2 = 18.","일의 자리 9 × 2 = 18 → 1 올림.","800 + 60 + 18 = 878 — 어림한 400 × 2 = 800과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#4','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C4',1,'sa','auto','811 × 8은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u1-C4","difficulty":1,"kind":"sa","stem":"811 × 8은 얼마인가요? 숫자로 쓰세요.","answer":["6488"],"explanation":["811을 800, 10, 1로 갈라 곱해요: 800 × 8 = 6400, 10 × 8 = 80, 1 × 8 = 8.","백의 자리 8 × 8 = 64 → 천의 자리.","6400 + 80 + 8 = 6488 — 어림한 800 × 8 = 6400과 가까워요."],"variant_rule":{"alt":[{"stem":"545 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["1090"],"explanation":["545를 500, 40, 5로 갈라 곱해요: 500 × 2 = 1000, 40 × 2 = 80, 5 × 2 = 10.","일의 자리 5 × 2 = 10 → 1 올림, 백의 자리 5 × 2 = 10 → 천의 자리.","1000 + 80 + 10 = 1090 — 어림한 500 × 2 = 1000과 가까워요."],"asset":null},{"stem":"818 × 9는 얼마인가요? 숫자로 쓰세요.","answer":["7362"],"explanation":["818을 800, 10, 8로 갈라 곱해요: 800 × 9 = 7200, 10 × 9 = 90, 8 × 9 = 72.","일의 자리 8 × 9 = 72 → 7 올림, 십의 자리 1 × 9 + 7 = 16 → 1 올림, 백의 자리 8 × 9 + 1 = 73 → 천의 자리.","7200 + 90 + 72 = 7362 — 어림한 800 × 9 = 7200과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#5','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C5',1,'sa','auto','70 × 80은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C5","difficulty":1,"kind":"sa","stem":"70 × 80은 얼마인가요? 숫자로 쓰세요.","answer":["5600"],"explanation":["7 × 8 = 56이에요.","70 × 8 = 560, 곱하는 수가 8에서 80으로 10배가 되면 곱도 10배예요.","70 × 80 = 560의 10배 = 5600이에요."],"variant_rule":{"alt":[{"stem":"40 × 80은 얼마인가요? 숫자로 쓰세요.","answer":["3200"],"explanation":["4 × 8 = 32예요.","40 × 8 = 320, 곱하는 수가 8에서 80으로 10배가 되면 곱도 10배예요.","40 × 80 = 320의 10배 = 3200이에요."],"asset":null},{"stem":"80 × 20은 얼마인가요? 숫자로 쓰세요.","answer":["1600"],"explanation":["8 × 2 = 16이에요.","80 × 2 = 160, 곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","80 × 20 = 160의 10배 = 1600이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#6','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C6',1,'sa','auto','6 × 18은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u1-C6","difficulty":1,"kind":"sa","stem":"6 × 18은 얼마인가요? 숫자로 쓰세요.","answer":["108"],"explanation":["곱하는 수 18을 10과 8로 갈라요.","6 × 8 = 48, 6 × 10 = 60이에요.","48 + 60 = 108이에요."],"variant_rule":{"alt":[{"stem":"6 × 39는 얼마인가요? 숫자로 쓰세요.","answer":["234"],"explanation":["곱하는 수 39를 30과 9로 갈라요.","6 × 9 = 54, 6 × 30 = 180이에요.","54 + 180 = 234예요."],"asset":null},{"stem":"6 × 53은 얼마인가요? 숫자로 쓰세요.","answer":["318"],"explanation":["곱하는 수 53을 50과 3으로 갈라요.","6 × 3 = 18, 6 × 50 = 300이에요.","18 + 300 = 318이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#7','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C7',1,'sa','auto','62 × 11은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u1-C7","difficulty":1,"kind":"sa","stem":"62 × 11은 얼마인가요? 숫자로 쓰세요.","answer":["682"],"explanation":["곱하는 수 11을 10과 1로 갈라요.","62 × 1 = 62, 62 × 10 = 620이에요.","62 + 620 = 682 — 어림한 60 × 10 = 600과 가까워요."],"variant_rule":{"alt":[{"stem":"11 × 21은 얼마인가요? 숫자로 쓰세요.","answer":["231"],"explanation":["곱하는 수 21을 20과 1로 갈라요.","11 × 1 = 11, 11 × 20 = 220이에요.","11 + 220 = 231 — 어림한 10 × 20 = 200과 가까워요."],"asset":null},{"stem":"26 × 19는 얼마인가요? 숫자로 쓰세요.","answer":["494"],"explanation":["곱하는 수 19를 10과 9로 갈라요.","26 × 9 = 234, 26 × 10 = 260이에요.","234 + 260 = 494 — 어림한 30 × 20 = 600과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#8','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C3',1,'mc','auto','206 × 3을 어림하면 약 얼마인가요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],true,'{"seq":8,"concept":"M3-2-u1-C3","difficulty":1,"kind":"mc","stem":"206 × 3을 어림하면 약 얼마인가요?","options":[{"t":"약 600","correct":true},{"t":"약 300","mis":"M3-2-u1-X12"},{"t":"약 203","mis":"M3-2-u1-X12"},{"t":"약 6000","mis":"M3-2-u1-X06"}],"explanation":["206은 가까운 몇백 200으로 어림해요.","200 × 3 = 600이에요.","그래서 약 600이에요 — 실제 곱 618과 가까워요."],"variant_rule":{"alt":[{"stem":"118 × 5를 어림하면 약 얼마인가요?","options":[{"t":"약 500","correct":true},{"t":"약 105","mis":"M3-2-u1-X12"},{"t":"약 5000","mis":"M3-2-u1-X06"},{"t":"약 100","mis":"M3-2-u1-X12"}],"explanation":["118은 가까운 몇백 100으로 어림해요.","100 × 5 = 500이에요.","그래서 약 500이에요 — 실제 곱 590과 가까워요."],"asset":null},{"stem":"317 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 600","correct":true},{"t":"약 400","mis":"M3-2-u1-X12"},{"t":"약 302","mis":"M3-2-u1-X12"},{"t":"약 6000","mis":"M3-2-u1-X06"}],"explanation":["317은 가까운 몇백 300으로 어림해요.","300 × 2 = 600이에요.","그래서 약 600이에요 — 실제 곱 634와 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#9','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C2',2,'sa','auto','292 × 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u1-C2","difficulty":2,"kind":"sa","stem":"292 × 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 9 × 3 = 27 → 7을 써요.","292 × 3 = 876 — 십의 자리 숫자는 7이에요."],"asset":{"type":"expr_grid","rows":[["올림","","2","",""],["","","2","9","2"],["×","","","","3"],["","","8",null,"6"]]},"variant_rule":{"alt":[{"stem":"240 × 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["세로셈은 일의 자리부터 곱해요.","백의 자리: 2 × 3 + 올림 1 = 7 → 7을 써요.","240 × 3 = 720 — 백의 자리 숫자는 7이에요."],"asset":{"type":"expr_grid","rows":[["올림","","1","",""],["","","2","4","0"],["×","","","","3"],["","",null,"2","0"]]}},{"stem":"192 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 2 × 2 = 4 → 4를 써요.","192 × 2 = 384 — 일의 자리 숫자는 4예요."],"asset":{"type":"expr_grid","rows":[["올림","","1","",""],["","","1","9","2"],["×","","","","2"],["","","3","8",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#10','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C4',2,'sa','auto','766 × 3의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u1-C4","difficulty":2,"kind":"sa","stem":"766 × 3의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["백의 자리 곱 7 × 3 + 올림 1 = 22예요.","10을 넘은 2가 천의 자리로 가요.","766 × 3 = 2298 — 천의 자리 숫자는 2예요."],"variant_rule":{"alt":[{"stem":"399 × 3의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["백의 자리 곱 3 × 3 + 올림 2 = 11이에요.","10을 넘은 1이 천의 자리로 가요.","399 × 3 = 1197 — 천의 자리 숫자는 1이에요."],"asset":null},{"stem":"617 × 9의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["백의 자리 곱 6 × 9 + 올림 1 = 55예요.","10을 넘은 5가 천의 자리로 가요.","617 × 9 = 5553 — 천의 자리 숫자는 5예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#11','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C5',2,'sa','auto','43 × 6 = 258이에요. 그러면 43 × 60은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-2-u1-C5","difficulty":2,"kind":"sa","stem":"43 × 6 = 258이에요. 그러면 43 × 60은 얼마인가요? 숫자로 쓰세요.","answer":["2580"],"explanation":["곱하는 수 60은 6의 10배예요.","곱하는 수가 10배가 되면 곱도 10배가 돼요.","258의 10배 — 43 × 60 = 2580이에요."],"variant_rule":{"alt":[{"stem":"54 × 4 = 216이에요. 그러면 54 × 40은 얼마인가요? 숫자로 쓰세요.","answer":["2160"],"explanation":["곱하는 수 40은 4의 10배예요.","곱하는 수가 10배가 되면 곱도 10배가 돼요.","216의 10배 — 54 × 40 = 2160이에요."],"asset":null},{"stem":"76 × 5 = 380이에요. 그러면 76 × 50은 얼마인가요? 숫자로 쓰세요.","answer":["3800"],"explanation":["곱하는 수 50은 5의 10배예요.","곱하는 수가 10배가 되면 곱도 10배가 돼요.","380의 10배 — 76 × 50 = 3800이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#12','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C6',2,'ox','auto','4 × 34의 곱과 34 × 4의 곱은 같아요.',ARRAY['M3-2-u1-X16']::text[],true,'{"seq":12,"concept":"M3-2-u1-C6","difficulty":2,"kind":"ox","stem":"4 × 34의 곱과 34 × 4의 곱은 같아요.","answer":"O","reason_options":[{"t":"곱하는 두 수의 순서를 바꾸어도 곱은 같아서","correct":true},{"t":"곱해지는 수가 커지면 곱도 커져서","mis":"M3-2-u1-X16"}],"mis":"M3-2-u1-X16","explanation":["4 × 34 = 136이에요.","34 × 4 = 136이에요.","순서를 바꾸어도 곱은 같아요 — 계산하기 쉬운 쪽으로 구해도 돼요."],"variant_rule":{"alt":[{"stem":"5 × 47의 곱과 47 × 5의 곱은 같아요.","answer":"O","reason_options":[{"t":"곱하는 두 수의 순서를 바꾸어도 곱은 같아서","correct":true},{"t":"곱해지는 수가 커지면 곱도 커져서","mis":"M3-2-u1-X16"}],"explanation":["5 × 47 = 235예요.","47 × 5 = 235예요.","순서를 바꾸어도 곱은 같아요 — 계산하기 쉬운 쪽으로 구해도 돼요."],"asset":null},{"stem":"5 × 23의 곱과 23 × 5의 곱은 같아요.","answer":"O","reason_options":[{"t":"곱하는 두 수의 순서를 바꾸어도 곱은 같아서","correct":true},{"t":"곱해지는 수가 커지면 곱도 커져서","mis":"M3-2-u1-X16"}],"explanation":["5 × 23 = 115예요.","23 × 5 = 115예요.","순서를 바꾸어도 곱은 같아요 — 계산하기 쉬운 쪽으로 구해도 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#13','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C7',2,'sa','auto','12 × 41을 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M3-2-u1-C7","difficulty":2,"kind":"sa","stem":"12 × 41을 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["12"],"explanation":["곱하는 수 41을 1과 40으로 갈라요.","□는 12 × 1 = 12예요.","12 + 480 = 492 — 12 × 41의 곱이에요."],"asset":{"type":"expr_grid","rows":[["12 × 1","=",null],["12 × 40","=","480"],["□ + 480","=","492"]]},"variant_rule":{"alt":[{"stem":"12 × 32를 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["360"],"explanation":["곱하는 수 32를 2와 30으로 갈라요.","□는 12 × 30 = 360이에요.","24 + 360 = 384 — 12 × 32의 곱이에요."],"asset":{"type":"expr_grid","rows":[["12 × 2","=","24"],["12 × 30","=",null],["24 + □","=","384"]]}},{"stem":"19 × 39를 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["171"],"explanation":["곱하는 수 39를 9와 30으로 갈라요.","□는 19 × 9 = 171이에요.","171 + 570 = 741 — 19 × 39의 곱이에요."],"asset":{"type":"expr_grid","rows":[["19 × 9","=",null],["19 × 30","=","570"],["□ + 570","=","741"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#14','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C8',2,'sa','auto','74 × 46은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-2-u1-C8","difficulty":2,"kind":"sa","stem":"74 × 46은 얼마인가요? 숫자로 쓰세요.","answer":["3404"],"explanation":["곱하는 수 46을 40과 6으로 갈라요.","74 × 6 = 444, 74 × 40 = 2960이에요.","444 + 2960 = 3404 — 어림한 70 × 50 = 3500과 가까워요."],"variant_rule":{"alt":[{"stem":"24 × 59는 얼마인가요? 숫자로 쓰세요.","answer":["1416"],"explanation":["곱하는 수 59를 50과 9로 갈라요.","24 × 9 = 216, 24 × 50 = 1200이에요.","216 + 1200 = 1416 — 어림한 20 × 60 = 1200과 가까워요."],"asset":null},{"stem":"92 × 79는 얼마인가요? 숫자로 쓰세요.","answer":["7268"],"explanation":["곱하는 수 79를 70과 9로 갈라요.","92 × 9 = 828, 92 × 70 = 6440이에요.","828 + 6440 = 7268 — 어림한 90 × 80 = 7200과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#15','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C3',2,'mc','auto','98 × 57을 어림하면 곱은 어느 사이에 있나요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],true,'{"seq":15,"concept":"M3-2-u1-C3","difficulty":2,"kind":"mc","stem":"98 × 57을 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"4500보다 크고 6000보다 작아요","correct":true},{"t":"4500보다 작아요","mis":"M3-2-u1-X12"},{"t":"6000보다 커요","mis":"M3-2-u1-X12"},{"t":"450보다 크고 600보다 작아요","mis":"M3-2-u1-X06"}],"explanation":["98은 90과 100 사이, 57은 50과 60 사이예요.","90 × 50 = 4500, 100 × 60 = 6000이에요.","98 × 57 = 5586 — 그 사이에 들어요."],"variant_rule":{"alt":[{"stem":"67 × 43을 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"2400보다 크고 3500보다 작아요","correct":true},{"t":"2400보다 작아요","mis":"M3-2-u1-X12"},{"t":"3500보다 커요","mis":"M3-2-u1-X12"},{"t":"240보다 크고 350보다 작아요","mis":"M3-2-u1-X06"}],"explanation":["67은 60과 70 사이, 43은 40과 50 사이예요.","60 × 40 = 2400, 70 × 50 = 3500이에요.","67 × 43 = 2881 — 그 사이에 들어요."],"asset":null},{"stem":"36 × 32를 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"900보다 크고 1600보다 작아요","correct":true},{"t":"900보다 작아요","mis":"M3-2-u1-X12"},{"t":"1600보다 커요","mis":"M3-2-u1-X12"},{"t":"90보다 크고 160보다 작아요","mis":"M3-2-u1-X06"}],"explanation":["36은 30과 40 사이, 32는 30과 40 사이예요.","30 × 30 = 900, 40 × 40 = 1600이에요.","36 × 32 = 1152 — 그 사이에 들어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#16','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C9',2,'sa','auto','우리에게 닭고기가 138조각 필요해요. 걸리버에게는 6배가 필요해요. 걸리버에게 닭고기는 몇 조각 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-2-u1-C9","difficulty":2,"kind":"sa","stem":"우리에게 닭고기가 138조각 필요해요. 걸리버에게는 6배가 필요해요. 걸리버에게 닭고기는 몇 조각 필요한가요? 숫자로 쓰세요.","answer":["828"],"explanation":["「6배」는 138을 6번 더한 것 — 곱셈식 138 × 6으로 세워요.","일의 자리 8 × 6 = 48 → 4 올림, 십의 자리 3 × 6 + 4 = 22 → 2 올림.","138 × 6 = 828 — 828조각이에요."],"variant_rule":{"alt":[{"stem":"우리에게 빵이 137개 필요해요. 걸리버에게는 7배가 필요해요. 걸리버에게 빵은 몇 개 필요한가요? 숫자로 쓰세요.","answer":["959"],"explanation":["「7배」는 137을 7번 더한 것 — 곱셈식 137 × 7로 세워요.","일의 자리 7 × 7 = 49 → 4 올림, 십의 자리 3 × 7 + 4 = 25 → 2 올림.","137 × 7 = 959 — 959개예요."],"asset":null},{"stem":"우리에게 단추가 166개 필요해요. 걸리버에게는 6배가 필요해요. 걸리버에게 단추는 몇 개 필요한가요? 숫자로 쓰세요.","answer":["996"],"explanation":["「6배」는 166을 6번 더한 것 — 곱셈식 166 × 6으로 세워요.","일의 자리 6 × 6 = 36 → 3 올림, 십의 자리 6 × 6 + 3 = 39 → 3 올림.","166 × 6 = 996 — 996개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#17','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C1',3,'error','auto','440 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X05','M3-2-u1-X15']::text[],true,'{"seq":17,"concept":"M3-2-u1-C1","difficulty":3,"kind":"error","stem":"440 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「440 × 2 = 882야」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"서윤 — 「440 × 2 = 880이야」","mis":"M3-2-u1-X15"},{"t":"하린 — 「2 × 440 = 880이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","440 × 2 = 880이에요.","도윤은 882로 잘못 구했어요 — 0에 곱하면 0."],"variant_rule":{"alt":[{"stem":"203 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「203 × 3 = 639야」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"태오 — 「203 × 3 = 609야」","mis":"M3-2-u1-X15"},{"t":"하린 — 「어림하면 약 600이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","203 × 3 = 609예요.","지유는 639로 잘못 구했어요 — 0에 곱하면 0."],"asset":null},{"stem":"330 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「330 × 2 = 662야」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"시우 — 「330 × 2 = 660이야」","mis":"M3-2-u1-X15"},{"t":"하랑 — 「2 × 330 = 660이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","330 × 2 = 660이에요.","은우는 662로 잘못 구했어요 — 0에 곱하면 0."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
