INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#19','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C4',3,'error','auto','279 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X03','M3-2-u1-X15']::text[],true,'{"seq":19,"concept":"M3-2-u1-C4","difficulty":3,"kind":"error","stem":"279 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「279 × 7 = 2313이야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"지유 — 「279 × 7 = 1953이야」","mis":"M3-2-u1-X15"},{"t":"태오 — 「어림하면 약 2100이야」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 9 × 7 = 63 → 6 올림, 십의 자리 7 × 7 + 6 = 55 → 5 올림, 백의 자리 2 × 7 + 5 = 19 → 천의 자리.","279 × 7 = 1953이에요.","은우는 2313으로 잘못 구했어요 — 곱한 다음에 더하기."],"variant_rule":{"alt":[{"stem":"278 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「278 × 7 = 2246이야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"지유 — 「278 × 7 = 1946이야」","mis":"M3-2-u1-X15"},{"t":"은우 — 「7 × 278 = 1946이야」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 8 × 7 = 56 → 5 올림, 십의 자리 7 × 7 + 5 = 54 → 5 올림, 백의 자리 2 × 7 + 5 = 19 → 천의 자리.","278 × 7 = 1946이에요.","도윤은 2246으로 잘못 구했어요 — 곱한 다음에 더하기."],"asset":null},{"stem":"773 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「773 × 4 = 3122야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"태오 — 「773 × 4 = 3092야」","mis":"M3-2-u1-X15"},{"t":"지유 — 「어림하면 약 3200이야」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 3 × 4 = 12 → 1 올림, 십의 자리 7 × 4 + 1 = 29 → 2 올림, 백의 자리 7 × 4 + 2 = 30 → 천의 자리.","773 × 4 = 3092예요.","하랑은 3122로 잘못 구했어요 — 곱한 다음에 더하기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=tru