INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#21','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C8',3,'ox','auto','89 × 53을 세로셈으로 계산하는데 셋째 줄 89 × 3에서 올림한 2를 넷째 줄 89 × 5에도 더해 4737이라고 했어요. 바르게 계산했어요.',ARRAY['M3-2-u1-X10']::text[],true,'{"seq":21,"concept":"M3-2-u1-C8","difficulty":3,"kind":"ox","stem":"89 × 53을 세로셈으로 계산하는데 셋째 줄 89 × 3에서 올림한 2를 넷째 줄 89 × 5에도 더해 4737이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"줄마다 올림은 그 줄 안에서만 더해서","correct":true},{"t":"앞 줄에서 올림한 수는 다음 줄에도 더해야 해서","mis":"M3-2-u1-X10"}],"mis":"M3-2-u1-X10","explanation":["셋째 줄 89 × 3 = 267, 넷째 줄 89 × 5 = 445(한 자리 밀어).","267 + 4450 = 4717이에요.","4737은 앞 줄의 올림 2를 다시 더한 답이에요."],"asset":{"type":"expr_grid","rows":[["","","","8","9"],["×","","","5","3"],["","","2","6","7"],["","4","4","7",""],["",null,null,null,null]]},"variant_rule":{"alt":[{"stem":"83 × 79를 세로셈으로 계산하는데 셋째 줄 83 × 9에서 올림한 2를 넷째 줄 83 × 7에도 더해 6577이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"줄마다 올림은 그 줄 안에서만 더해서","correct":true},{"t":"앞 줄에서 올림한 수는 다음 줄에도 더해야 해서","mis":"M3-2-u1-X10"}],"explanation":["셋째 줄 83 × 9 = 747, 넷째 줄 83 × 7 = 581(한 자리 밀어).","747 + 5810 = 6557이에요.","6577은 앞 줄의 올림 2를 다시 더한 답이에요."],"asset":{"type":"expr_grid","rows":[["","","","8","3"],["×","","","7","9"],["","","7","4","7"],["","5","8","3",""],["",null,null,null,null]]}},{"stem":"78 × 57을 세로셈으로 계산하는데 셋째 줄 78 × 7에서 올림한 5를 넷째 줄 78 × 5에도 더해 4496이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"줄마다 올림은 그 줄 안에서만 더해서","correct":true},{"t":"앞 줄에서 올림한 수는 다음 줄에도 더해야 해서","mis":"M3-2-u1-X10"}],"explanation":["셋째 줄 78 × 7 = 546, 넷째 줄 78 × 5 = 390(한 자리 밀어).","546 + 3900 = 4446이에요.","4496은 앞 줄의 올림 5를 다시 더한 답이에요."],"asset":{"type":"expr_grid","rows":[["","","","7","8"],["×","","","5","7"],["","","5","4","6"],["","3","9","5",""],["",null,null,null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#22','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C9',3,'mc','auto','우리에게 가죽이 26장 필요하고 걸리버에게는 그 40배가 필요해요. 천은 우리에게 147장 필요하고 걸리버에게는 그 5배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?',ARRAY['M3-2-u1-X08','M3-2-u1-X13']::text[],true,'{"seq":22,"concept":"M3-2-u1-C9","difficulty":3,"kind":"mc","stem":"우리에게 가죽이 26장 필요하고 걸리버에게는 그 40배가 필요해요. 천은 우리에게 147장 필요하고 걸리버에게는 그 5배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"1775장","correct":true},{"t":"1040장","mis":"M3-2-u1-X08"},{"t":"735장","mis":"M3-2-u1-X08"},{"t":"173장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 26 × 40 = 1040장.","천: 147 × 5 = 735장.","1040 + 735 = 1775 — 모두 1775장이에요."],"variant_rule":{"alt":[{"stem":"우리에게 가죽이 33장 필요하고 걸리버에게는 그 20배가 필요해요. 천은 우리에게 152장 필요하고 걸리버에게는 그 6배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"1572장","correct":true},{"t":"660장","mis":"M3-2-u1-X08"},{"t":"912장","mis":"M3-2-u1-X08"},{"t":"185장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 33 × 20 = 660장.","천: 152 × 6 = 912장.","660 + 912 = 1572 — 모두 1572장이에요."],"asset":null},{"stem":"우리에게 가죽이 18장 필요하고 걸리버에게는 그 50배가 필요해요. 천은 우리에게 213장 필요하고 걸리버에게는 그 4배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"1752장","correct":true},{"t":"900장","mis":"M3-2-u1-X08"},{"t":"852장","mis":"M3-2-u1-X08"},{"t":"231장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 18 × 50 = 900장.","천: 213 × 4 = 852장.","900 + 852 = 1752 — 모두 1752장이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#23','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C4',4,'sa','auto','수 카드 7, 3, 5, 2를 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-2-u1-C4","difficulty":4,"kind":"sa","stem":"수 카드 7, 3, 5, 2를 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.","answer":["3724"],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 7을 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 532를 만들어요.","532 × 7 = 3724 — 큰 수를 백의 자리에 놓은 753 × 2 = 1506보다 커요."],"variant_rule":{"alt":[{"stem":"수 카드 4, 9, 2, 6을 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.","answer":["5778"],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 9를 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 642를 만들어요.","642 × 9 = 5778 — 큰 수를 백의 자리에 놓은 964 × 2 = 1928보다 커요."],"asset":null},{"stem":"수 카드 3, 8, 2, 5를 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.","answer":["4256"],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 8을 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 532를 만들어요.","532 × 8 = 4256 — 큰 수를 백의 자리에 놓은 853 × 2 = 1706보다 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#24','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C8',4,'sa','auto','하랑이 19 × 92를 이렇게 계산해 1758이라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-2-u1-C8","difficulty":4,"kind":"sa","stem":"하랑이 19 × 92를 이렇게 계산해 1758이라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["1748"],"explanation":["하랑 — 셋째 줄의 올림을 넷째 줄에 다시 더했어요.","19 × 2 = 38, 19 × 90 = 1710.","38 + 1710 = 1748이에요."],"asset":{"type":"expr_grid","rows":[["","","","1","9"],["×","","","9","2"],["","","","3","8"],["","1","7","2",""],["","1","7","5","8"]]},"variant_rule":{"alt":[{"stem":"도윤이 84 × 17을 이렇게 계산해 672라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["1428"],"explanation":["도윤 — 넷째 줄을 한 자리 밀어 쓰지 않았어요.","84 × 7 = 588, 84 × 10 = 840.","588 + 840 = 1428이에요."],"asset":{"type":"expr_grid","rows":[["","","","8","4"],["×","","","1","7"],["","","5","8","8"],["","","","8","4"],["","","6","7","2"]]}},{"stem":"서윤이 28 × 52를 이렇게 계산해 1466이라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["1456"],"explanation":["서윤 — 셋째 줄의 올림을 넷째 줄에 다시 더했어요.","28 × 2 = 56, 28 × 50 = 1400.","56 + 1400 = 1456이에요."],"asset":{"type":"expr_grid","rows":[["","","","2","8"],["×","","","5","2"],["","","","5","6"],["","1","4","1",""],["","1","4","6","6"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_b#25','math',3,2,'u1','','g3_2_math_u1_review_b','unit_review','M3-2-u1-C8',4,'essay','teacher','48 × 36을 세로셈으로 계산하는 방법을 쓰고, 둘째 곱을 한 자리 밀어 쓰는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u1-C8","difficulty":4,"kind":"essay","stem":"48 × 36을 세로셈으로 계산하는 방법을 쓰고, 둘째 곱을 한 자리 밀어 쓰는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 48 × 6 = 288을 쓰고, 48 × 3 = 144를 한 자리 밀어 쓴다. 36의 3은 30을 나타내므로 144는 1440을 뜻하기 때문이다. 288 + 1440 = 1728이다.","scoring_points":["288과 1440을 구했는가","3이 30을 나타내 한 자리 민다고 설명했는가","1728을 구했는가"]},"explanation":["48 × 6 = 288.","48 × 30 = 1440 — 한 자리 밀어 써요.","288 + 1440 = 1728."],"asset":{"type":"expr_grid","rows":[["","","","4","8"],["×","","","3","6"],["","","2","8","8"],["","1","4","4",""],["","1","7","2","8"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#1','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C1',1,'sa','auto','243 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C1","difficulty":1,"kind":"sa","stem":"243 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["486"],"explanation":["243을 200, 40, 3으로 갈라 곱해요: 200 × 2 = 400, 40 × 2 = 80, 3 × 2 = 6.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요.","400 + 80 + 6 = 486 — 어림한 200 × 2 = 400과 가까워요."],"variant_rule":{"alt":[{"stem":"432 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["864"],"explanation":["432를 400, 30, 2로 갈라 곱해요: 400 × 2 = 800, 30 × 2 = 60, 2 × 2 = 4.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요.","800 + 60 + 4 = 864 — 어림한 400 × 2 = 800과 가까워요."],"asset":null},{"stem":"234 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["468"],"explanation":["234를 200, 30, 4로 갈라 곱해요: 200 × 2 = 400, 30 × 2 = 60, 4 × 2 = 8.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요.","400 + 60 + 8 = 468 — 어림한 200 × 2 = 400과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#2','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C1',1,'sa','auto','221 × 4를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u1-C1","difficulty":1,"kind":"sa","stem":"221 × 4를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["800"],"explanation":["221을 200, 20, 1로 갈라요.","□는 200 × 4 = 800이에요.","800 + 80 + 4 = 884 — 221 × 4의 곱이에요."],"asset":{"type":"expr_grid","rows":[["200 × 4","=",null],["20 × 4","=","80"],["1 × 4","=","4"],["□ + 80 + 4","=","884"]]},"variant_rule":{"alt":[{"stem":"333 × 2를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["60"],"explanation":["333을 300, 30, 3으로 갈라요.","□는 30 × 2 = 60이에요.","600 + 60 + 6 = 666 — 333 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["300 × 2","=","600"],["30 × 2","=",null],["3 × 2","=","6"],["600 + □ + 6","=","666"]]}},{"stem":"331 × 3을 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["331을 300, 30, 1로 갈라요.","□는 1 × 3 = 3이에요.","900 + 90 + 3 = 993 — 331 × 3의 곱이에요."],"asset":{"type":"expr_grid","rows":[["300 × 3","=","900"],["30 × 3","=","90"],["1 × 3","=",null],["900 + 90 + □","=","993"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#3','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C2',1,'sa','auto','107 × 5는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C2","difficulty":1,"kind":"sa","stem":"107 × 5는 얼마인가요? 숫자로 쓰세요.","answer":["535"],"explanation":["107을 100, 0, 7로 갈라 곱해요: 100 × 5 = 500, 0 × 5 = 0, 7 × 5 = 35.","일의 자리 7 × 5 = 35 → 3 올림.","500 + 0 + 35 = 535 — 어림한 100 × 5 = 500과 가까워요."],"variant_rule":{"alt":[{"stem":"214 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["856"],"explanation":["214를 200, 10, 4로 갈라 곱해요: 200 × 4 = 800, 10 × 4 = 40, 4 × 4 = 16.","일의 자리 4 × 4 = 16 → 1 올림.","800 + 40 + 16 = 856 — 어림한 200 × 4 = 800과 가까워요."],"asset":null},{"stem":"116 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["464"],"explanation":["116을 100, 10, 6으로 갈라 곱해요: 100 × 4 = 400, 10 × 4 = 40, 6 × 4 = 24.","일의 자리 6 × 4 = 24 → 2 올림.","400 + 40 + 24 = 464 — 어림한 100 × 4 = 400과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#4','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C4',1,'sa','auto','658 × 7은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u1-C4","difficulty":1,"kind":"sa","stem":"658 × 7은 얼마인가요? 숫자로 쓰세요.","answer":["4606"],"explanation":["658을 600, 50, 8로 갈라 곱해요: 600 × 7 = 4200, 50 × 7 = 350, 8 × 7 = 56.","일의 자리 8 × 7 = 56 → 5 올림, 십의 자리 5 × 7 + 5 = 40 → 4 올림, 백의 자리 6 × 7 + 4 = 46 → 천의 자리.","4200 + 350 + 56 = 4606 — 어림한 700 × 7 = 4900과 가까워요."],"variant_rule":{"alt":[{"stem":"294 × 7은 얼마인가요? 숫자로 쓰세요.","answer":["2058"],"explanation":["294를 200, 90, 4로 갈라 곱해요: 200 × 7 = 1400, 90 × 7 = 630, 4 × 7 = 28.","일의 자리 4 × 7 = 28 → 2 올림, 십의 자리 9 × 7 + 2 = 65 → 6 올림, 백의 자리 2 × 7 + 6 = 20 → 천의 자리.","1400 + 630 + 28 = 2058 — 어림한 300 × 7 = 2100과 가까워요."],"asset":null},{"stem":"586 × 6은 얼마인가요? 숫자로 쓰세요.","answer":["3516"],"explanation":["586을 500, 80, 6으로 갈라 곱해요: 500 × 6 = 3000, 80 × 6 = 480, 6 × 6 = 36.","일의 자리 6 × 6 = 36 → 3 올림, 십의 자리 8 × 6 + 3 = 51 → 5 올림, 백의 자리 5 × 6 + 5 = 35 → 천의 자리.","3000 + 480 + 36 = 3516 — 어림한 600 × 6 = 3600과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#5','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C5',1,'sa','auto','60 × 80은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C5","difficulty":1,"kind":"sa","stem":"60 × 80은 얼마인가요? 숫자로 쓰세요.","answer":["4800"],"explanation":["6 × 8 = 48이에요.","60 × 8 = 480, 곱하는 수가 8에서 80으로 10배가 되면 곱도 10배예요.","60 × 80 = 480의 10배 = 4800이에요."],"variant_rule":{"alt":[{"stem":"90 × 50은 얼마인가요? 숫자로 쓰세요.","answer":["4500"],"explanation":["9 × 5 = 45예요.","90 × 5 = 450, 곱하는 수가 5에서 50으로 10배가 되면 곱도 10배예요.","90 × 50 = 450의 10배 = 4500이에요."],"asset":null},{"stem":"70 × 80은 얼마인가요? 숫자로 쓰세요.","answer":["5600"],"explanation":["7 × 8 = 56이에요.","70 × 8 = 560, 곱하는 수가 8에서 80으로 10배가 되면 곱도 10배예요.","70 × 80 = 560의 10배 = 5600이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#6','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C6',1,'sa','auto','7 × 72는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u1-C6","difficulty":1,"kind":"sa","stem":"7 × 72는 얼마인가요? 숫자로 쓰세요.","answer":["504"],"explanation":["곱하는 수 72를 70과 2로 갈라요.","7 × 2 = 14, 7 × 70 = 490이에요.","14 + 490 = 504예요."],"variant_rule":{"alt":[{"stem":"3 × 58은 얼마인가요? 숫자로 쓰세요.","answer":["174"],"explanation":["곱하는 수 58을 50과 8로 갈라요.","3 × 8 = 24, 3 × 50 = 150이에요.","24 + 150 = 174예요."],"asset":null},{"stem":"8 × 68은 얼마인가요? 숫자로 쓰세요.","answer":["544"],"explanation":["곱하는 수 68을 60과 8로 갈라요.","8 × 8 = 64, 8 × 60 = 480이에요.","64 + 480 = 544예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#7','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C7',1,'sa','auto','11 × 18은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u1-C7","difficulty":1,"kind":"sa","stem":"11 × 18은 얼마인가요? 숫자로 쓰세요.","answer":["198"],"explanation":["곱하는 수 18을 10과 8로 갈라요.","11 × 8 = 88, 11 × 10 = 110이에요.","88 + 110 = 198 — 어림한 10 × 20 = 200과 가까워요."],"variant_rule":{"alt":[{"stem":"71 × 13은 얼마인가요? 숫자로 쓰세요.","answer":["923"],"explanation":["곱하는 수 13을 10과 3으로 갈라요.","71 × 3 = 213, 71 × 10 = 710이에요.","213 + 710 = 923 — 어림한 70 × 10 = 700과 가까워요."],"asset":null},{"stem":"69 × 13은 얼마인가요? 숫자로 쓰세요.","answer":["897"],"explanation":["곱하는 수 13을 10과 3으로 갈라요.","69 × 3 = 207, 69 × 10 = 690이에요.","207 + 690 = 897 — 어림한 70 × 10 = 700과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#8','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C3',1,'mc','auto','307 × 3을 어림하면 약 얼마인가요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],true,'{"seq":8,"concept":"M3-2-u1-C3","difficulty":1,"kind":"mc","stem":"307 × 3을 어림하면 약 얼마인가요?","options":[{"t":"약 900","correct":true},{"t":"약 600","mis":"M3-2-u1-X12"},{"t":"약 303","mis":"M3-2-u1-X12"},{"t":"약 9000","mis":"M3-2-u1-X06"}],"explanation":["307은 가까운 몇백 300으로 어림해요.","300 × 3 = 900이에요.","그래서 약 900이에요 — 실제 곱 921과 가까워요."],"variant_rule":{"alt":[{"stem":"206 × 4를 어림하면 약 얼마인가요?","options":[{"t":"약 800","correct":true},{"t":"약 400","mis":"M3-2-u1-X12"},{"t":"약 204","mis":"M3-2-u1-X12"},{"t":"약 8000","mis":"M3-2-u1-X06"}],"explanation":["206은 가까운 몇백 200으로 어림해요.","200 × 4 = 800이에요.","그래서 약 800이에요 — 실제 곱 824와 가까워요."],"asset":null},{"stem":"207 × 2를 어림하면 약 얼마인가요?","options":[{"t":"약 400","correct":true},{"t":"약 200","mis":"M3-2-u1-X12"},{"t":"약 202","mis":"M3-2-u1-X12"},{"t":"약 4000","mis":"M3-2-u1-X06"}],"explanation":["207은 가까운 몇백 200으로 어림해요.","200 × 2 = 400이에요.","그래서 약 400이에요 — 실제 곱 414와 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#9','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C2',2,'sa','auto','143 × 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u1-C2","difficulty":2,"kind":"sa","stem":"143 × 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["세로셈은 일의 자리부터 곱해요.","백의 자리: 1 × 3 + 올림 1 = 4 → 4를 써요.","143 × 3 = 429 — 백의 자리 숫자는 4예요."],"asset":{"type":"expr_grid","rows":[["올림","","1","",""],["","","1","4","3"],["×","","","","3"],["","",null,"2","9"]]},"variant_rule":{"alt":[{"stem":"151 × 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 1 × 3 = 3 → 3을 써요.","151 × 3 = 453 — 일의 자리 숫자는 3이에요."],"asset":{"type":"expr_grid","rows":[["올림","","1","",""],["","","1","5","1"],["×","","","","3"],["","","4","5",null]]}},{"stem":"191 × 4의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 1 × 4 = 4 → 4를 써요.","191 × 4 = 764 — 일의 자리 숫자는 4예요."],"asset":{"type":"expr_grid","rows":[["올림","","3","",""],["","","1","9","1"],["×","","","","4"],["","","7","6",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#10','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C4',2,'sa','auto','537 × 7의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u1-C4","difficulty":2,"kind":"sa","stem":"537 × 7의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["백의 자리 곱 5 × 7 + 올림 2 = 37이에요.","10을 넘은 3이 천의 자리로 가요.","537 × 7 = 3759 — 천의 자리 숫자는 3이에요."],"variant_rule":{"alt":[{"stem":"538 × 4의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["백의 자리 곱 5 × 4 + 올림 1 = 21이에요.","10을 넘은 2가 천의 자리로 가요.","538 × 4 = 2152 — 천의 자리 숫자는 2예요."],"asset":null},{"stem":"928 × 9의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["백의 자리 곱 9 × 9 + 올림 2 = 83이에요.","10을 넘은 8이 천의 자리로 가요.","928 × 9 = 8352 — 천의 자리 숫자는 8이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#11','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C5',2,'sa','auto','26 × 9 = 234예요. 그러면 26 × 90은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-2-u1-C5","difficulty":2,"kind":"sa","stem":"26 × 9 = 234예요. 그러면 26 × 90은 얼마인가요? 숫자로 쓰세요.","answer":["2340"],"explanation":["곱하는 수 90은 9의 10배예요.","곱하는 수가 10배가 되면 곱도 10배가 돼요.","234의 10배 — 26 × 90 = 2340이에요."],"variant_rule":{"alt":[{"stem":"73 × 9 = 657이에요. 그러면 73 × 90은 얼마인가요? 숫자로 쓰세요.","answer":["6570"],"explanation":["곱하는 수 90은 9의 10배예요.","곱하는 수가 10배가 되면 곱도 10배가 돼요.","657의 10배 — 73 × 90 = 6570이에요."],"asset":null},{"stem":"69 × 3 = 207이에요. 그러면 69 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["2070"],"explanation":["곱하는 수 30은 3의 10배예요.","곱하는 수가 10배가 되면 곱도 10배가 돼요.","207의 10배 — 69 × 30 = 2070이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#12','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C6',2,'ox','auto','3 × 26의 곱과 26 × 3의 곱은 같아요.',ARRAY['M3-2-u1-X16']::text[],true,'{"seq":12,"concept":"M3-2-u1-C6","difficulty":2,"kind":"ox","stem":"3 × 26의 곱과 26 × 3의 곱은 같아요.","answer":"O","reason_options":[{"t":"곱하는 두 수의 순서를 바꾸어도 곱은 같아서","correct":true},{"t":"곱해지는 수가 커지면 곱도 커져서","mis":"M3-2-u1-X16"}],"mis":"M3-2-u1-X16","explanation":["3 × 26 = 78이에요.","26 × 3 = 78이에요.","순서를 바꾸어도 곱은 같아요 — 계산하기 쉬운 쪽으로 구해도 돼요."],"variant_rule":{"alt":[{"stem":"8 × 52의 곱과 52 × 8의 곱은 같아요.","answer":"O","reason_options":[{"t":"곱하는 두 수의 순서를 바꾸어도 곱은 같아서","correct":true},{"t":"곱해지는 수가 커지면 곱도 커져서","mis":"M3-2-u1-X16"}],"explanation":["8 × 52 = 416이에요.","52 × 8 = 416이에요.","순서를 바꾸어도 곱은 같아요 — 계산하기 쉬운 쪽으로 구해도 돼요."],"asset":null},{"stem":"8 × 23의 곱과 23 × 8의 곱은 같아요.","answer":"O","reason_options":[{"t":"곱하는 두 수의 순서를 바꾸어도 곱은 같아서","correct":true},{"t":"곱해지는 수가 커지면 곱도 커져서","mis":"M3-2-u1-X16"}],"explanation":["8 × 23 = 184예요.","23 × 8 = 184예요.","순서를 바꾸어도 곱은 같아요 — 계산하기 쉬운 쪽으로 구해도 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#13','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C7',2,'sa','auto','22 × 18을 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M3-2-u1-C7","difficulty":2,"kind":"sa","stem":"22 × 18을 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["220"],"explanation":["곱하는 수 18을 8과 10으로 갈라요.","□는 22 × 10 = 220이에요.","176 + 220 = 396 — 22 × 18의 곱이에요."],"asset":{"type":"expr_grid","rows":[["22 × 8","=","176"],["22 × 10","=",null],["176 + □","=","396"]]},"variant_rule":{"alt":[{"stem":"11 × 74를 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["44"],"explanation":["곱하는 수 74를 4와 70으로 갈라요.","□는 11 × 4 = 44예요.","44 + 770 = 814 — 11 × 74의 곱이에요."],"asset":{"type":"expr_grid","rows":[["11 × 4","=",null],["11 × 70","=","770"],["□ + 770","=","814"]]}},{"stem":"34 × 19를 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["340"],"explanation":["곱하는 수 19를 9와 10으로 갈라요.","□는 34 × 10 = 340이에요.","306 + 340 = 646 — 34 × 19의 곱이에요."],"asset":{"type":"expr_grid","rows":[["34 × 9","=","306"],["34 × 10","=",null],["306 + □","=","646"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#14','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C8',2,'sa','auto','67 × 63은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-2-u1-C8","difficulty":2,"kind":"sa","stem":"67 × 63은 얼마인가요? 숫자로 쓰세요.","answer":["4221"],"explanation":["곱하는 수 63을 60과 3으로 갈라요.","67 × 3 = 201, 67 × 60 = 4020이에요.","201 + 4020 = 4221 — 어림한 70 × 60 = 4200과 가까워요."],"variant_rule":{"alt":[{"stem":"76 × 86은 얼마인가요? 숫자로 쓰세요.","answer":["6536"],"explanation":["곱하는 수 86을 80과 6으로 갈라요.","76 × 6 = 456, 76 × 80 = 6080이에요.","456 + 6080 = 6536 — 어림한 80 × 90 = 7200과 가까워요."],"asset":null},{"stem":"88 × 16은 얼마인가요? 숫자로 쓰세요.","answer":["1408"],"explanation":["곱하는 수 16을 10과 6으로 갈라요.","88 × 6 = 528, 88 × 10 = 880이에요.","528 + 880 = 1408 — 어림한 90 × 20 = 1800과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#15','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C3',2,'mc','auto','88 × 73을 어림하면 곱은 어느 사이에 있나요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],true,'{"seq":15,"concept":"M3-2-u1-C3","difficulty":2,"kind":"mc","stem":"88 × 73을 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"5600보다 크고 7200보다 작아요","correct":true},{"t":"5600보다 작아요","mis":"M3-2-u1-X12"},{"t":"7200보다 커요","mis":"M3-2-u1-X12"},{"t":"560보다 크고 720보다 작아요","mis":"M3-2-u1-X06"}],"explanation":["88은 80과 90 사이, 73은 70과 80 사이예요.","80 × 70 = 5600, 90 × 80 = 7200이에요.","88 × 73 = 6424 — 그 사이에 들어요."],"variant_rule":{"alt":[{"stem":"97 × 54를 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"4500보다 크고 6000보다 작아요","correct":true},{"t":"4500보다 작아요","mis":"M3-2-u1-X12"},{"t":"6000보다 커요","mis":"M3-2-u1-X12"},{"t":"450보다 크고 600보다 작아요","mis":"M3-2-u1-X06"}],"explanation":["97은 90과 100 사이, 54는 50과 60 사이예요.","90 × 50 = 4500, 100 × 60 = 6000이에요.","97 × 54 = 5238 — 그 사이에 들어요."],"asset":null},{"stem":"29 × 76을 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"1400보다 크고 2400보다 작아요","correct":true},{"t":"1400보다 작아요","mis":"M3-2-u1-X12"},{"t":"2400보다 커요","mis":"M3-2-u1-X12"},{"t":"140보다 크고 240보다 작아요","mis":"M3-2-u1-X06"}],"explanation":["29는 20과 30 사이, 76은 70과 80 사이예요.","20 × 70 = 1400, 30 × 80 = 2400이에요.","29 × 76 = 2204 — 그 사이에 들어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#16','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C9',2,'sa','auto','우리에게 천이 17장 필요해요. 걸리버에게는 27배가 필요해요. 걸리버에게 천은 몇 장 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-2-u1-C9","difficulty":2,"kind":"sa","stem":"우리에게 천이 17장 필요해요. 걸리버에게는 27배가 필요해요. 걸리버에게 천은 몇 장 필요한가요? 숫자로 쓰세요.","answer":["459"],"explanation":["「27배」는 17을 27번 더한 것 — 곱셈식 17 × 27로 세워요.","17 × 7 = 119, 17 × 20 = 340이에요.","17 × 27 = 459 — 459장이에요."],"variant_rule":{"alt":[{"stem":"우리에게 물이 48잔 필요해요. 걸리버에게는 24배가 필요해요. 걸리버에게 물은 몇 잔 필요한가요? 숫자로 쓰세요.","answer":["1152"],"explanation":["「24배」는 48을 24번 더한 것 — 곱셈식 48 × 24로 세워요.","48 × 4 = 192, 48 × 20 = 960이에요.","48 × 24 = 1152 — 1152잔이에요."],"asset":null},{"stem":"우리에게 물고기가 41마리 필요해요. 걸리버에게는 16배가 필요해요. 걸리버에게 물고기는 몇 마리 필요한가요? 숫자로 쓰세요.","answer":["656"],"explanation":["「16배」는 41을 16번 더한 것 — 곱셈식 41 × 16으로 세워요.","41 × 6 = 246, 41 × 10 = 410이에요.","41 × 16 = 656 — 656마리예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#17','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C1',3,'error','auto','310 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X05','M3-2-u1-X15']::text[],true,'{"seq":17,"concept":"M3-2-u1-C1","difficulty":3,"kind":"error","stem":"310 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「310 × 2 = 622야」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"하린 — 「310 × 2 = 620이야」","mis":"M3-2-u1-X15"},{"t":"태오 — 「2 × 310 = 620이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","310 × 2 = 620이에요.","도윤은 622로 잘못 구했어요 — 0에 곱하면 0."],"variant_rule":{"alt":[{"stem":"330 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「330 × 2 = 662야」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"도윤 — 「330 × 2 = 660이야」","mis":"M3-2-u1-X15"},{"t":"태오 — 「어림하면 약 600이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","330 × 2 = 660이에요.","하린은 662로 잘못 구했어요 — 0에 곱하면 0."],"asset":null},{"stem":"240 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「240 × 2 = 482야」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"도윤 — 「240 × 2 = 480이야」","mis":"M3-2-u1-X15"},{"t":"하린 — 「2 × 240 = 480이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","240 × 2 = 480이에요.","서윤은 482로 잘못 구했어요 — 0에 곱하면 0."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#18','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C2',3,'ox','auto','109 × 2를 계산하는데 일의 자리에서 십의 자리로 올림한 1을 더하지 않고 208이라고 했어요. 바르게 계산했어요.',ARRAY['M3-2-u1-X02']::text[],true,'{"seq":18,"concept":"M3-2-u1-C2","difficulty":3,"kind":"ox","stem":"109 × 2를 계산하는데 일의 자리에서 십의 자리로 올림한 1을 더하지 않고 208이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수는 윗자리를 곱한 다음 꼭 더해야 해서","correct":true},{"t":"올림한 수는 작게 적어 두기만 하면 되어서","mis":"M3-2-u1-X02"}],"mis":"M3-2-u1-X02","explanation":["일의 자리 9 × 2 = 18 → 1 올림.","109 × 2 = 218이에요.","208은 올림한 1을 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["올림","","","1",""],["","","1","0","9"],["×","","","","2"],["","",null,null,null]]},"variant_rule":{"alt":[{"stem":"112 × 6을 계산하는데 일의 자리에서 십의 자리로 올림한 1을 더하지 않고 662라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수는 윗자리를 곱한 다음 꼭 더해야 해서","correct":true},{"t":"올림한 수는 작게 적어 두기만 하면 되어서","mis":"M3-2-u1-X02"}],"explanation":["일의 자리 2 × 6 = 12 → 1 올림.","112 × 6 = 672예요.","662는 올림한 1을 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["올림","","","1",""],["","","1","1","2"],["×","","","","6"],["","",null,null,null]]}},{"stem":"226 × 2를 계산하는데 일의 자리에서 십의 자리로 올림한 1을 더하지 않고 442라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수는 윗자리를 곱한 다음 꼭 더해야 해서","correct":true},{"t":"올림한 수는 작게 적어 두기만 하면 되어서","mis":"M3-2-u1-X02"}],"explanation":["일의 자리 6 × 2 = 12 → 1 올림.","226 × 2 = 452예요.","442는 올림한 1을 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["올림","","","1",""],["","","2","2","6"],["×","","","","2"],["","",null,null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#19','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C4',3,'error','auto','859 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X03','M3-2-u1-X15']::text[],true,'{"seq":19,"concept":"M3-2-u1-C4","difficulty":3,"kind":"error","stem":"859 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「859 × 4 = 3526이야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"하린 — 「859 × 4 = 3436이야」","mis":"M3-2-u1-X15"},{"t":"태오 — 「4 × 859 = 3436이야」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 9 × 4 = 36 → 3 올림, 십의 자리 5 × 4 + 3 = 23 → 2 올림, 백의 자리 8 × 4 + 2 = 34 → 천의 자리.","859 × 4 = 3436이에요.","하랑은 3526으로 잘못 구했어요 — 곱한 다음에 더하기."],"variant_rule":{"alt":[{"stem":"128 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「128 × 7 = 1196이야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"시우 — 「128 × 7 = 896이야」","mis":"M3-2-u1-X15"},{"t":"은우 — 「어림하면 약 700이야」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 8 × 7 = 56 → 5 올림, 십의 자리 2 × 7 + 5 = 19 → 1 올림.","128 × 7 = 896이에요.","태오는 1196으로 잘못 구했어요 — 곱한 다음에 더하기."],"asset":null},{"stem":"776 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「776 × 8 = 6488이야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"도윤 — 「776 × 8 = 6208이야」","mis":"M3-2-u1-X15"},{"t":"하린 — 「8 × 776 = 6208이야」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 6 × 8 = 48 → 4 올림, 십의 자리 7 × 8 + 4 = 60 → 6 올림, 백의 자리 7 × 8 + 6 = 62 → 천의 자리.","776 × 8 = 6208이에요.","태오는 6488로 잘못 구했어요 — 곱한 다음에 더하기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#20','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C5',3,'error','auto','29 × 20을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X06','M3-2-u1-X15']::text[],true,'{"seq":20,"concept":"M3-2-u1-C5","difficulty":3,"kind":"error","stem":"29 × 20을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「29 × 20 = 58이야」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"하린 — 「29 × 20 = 580이야」","mis":"M3-2-u1-X15"},{"t":"도윤 — 「어림하면 약 600이야」","mis":"M3-2-u1-X15"}],"explanation":["곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","29 × 20 = 580이에요.","은우는 58로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배."],"variant_rule":{"alt":[{"stem":"45 × 70을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「45 × 70 = 315야」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"지유 — 「45 × 70 = 3150이야」","mis":"M3-2-u1-X15"},{"t":"도윤 — 「70 × 45 = 3150이야」","mis":"M3-2-u1-X15"}],"explanation":["곱하는 수가 7에서 70으로 10배가 되면 곱도 10배예요.","45 × 70 = 3150이에요.","서윤은 315로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배."],"asset":null},{"stem":"54 × 70을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「54 × 70 = 378이야」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"태오 — 「54 × 70 = 3780이야」","mis":"M3-2-u1-X15"},{"t":"도윤 — 「어림하면 약 3500이야」","mis":"M3-2-u1-X15"}],"explanation":["곱하는 수가 7에서 70으로 10배가 되면 곱도 10배예요.","54 × 70 = 3780이에요.","은우는 378로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#21','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C8',3,'ox','auto','57 × 88을 세로셈으로 계산하는데 셋째 줄 57 × 8에서 올림한 5를 넷째 줄 57 × 8에도 더해 5066이라고 했어요. 바르게 계산했어요.',ARRAY['M3-2-u1-X10']::text[],true,'{"seq":21,"concept":"M3-2-u1-C8","difficulty":3,"kind":"ox","stem":"57 × 88을 세로셈으로 계산하는데 셋째 줄 57 × 8에서 올림한 5를 넷째 줄 57 × 8에도 더해 5066이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"줄마다 올림은 그 줄 안에서만 더해서","correct":true},{"t":"앞 줄에서 올림한 수는 다음 줄에도 더해야 해서","mis":"M3-2-u1-X10"}],"mis":"M3-2-u1-X10","explanation":["셋째 줄 57 × 8 = 456, 넷째 줄 57 × 8 = 456(한 자리 밀어).","456 + 4560 = 5016이에요.","5066은 앞 줄의 올림 5를 다시 더한 답이에요."],"asset":{"type":"expr_grid","rows":[["","","","5","7"],["×","","","8","8"],["","","4","5","6"],["","4","6","1",""],["",null,null,null,null]]},"variant_rule":{"alt":[{"stem":"56 × 29를 세로셈으로 계산하는데 셋째 줄 56 × 9에서 올림한 5를 넷째 줄 56 × 2에도 더해 1674라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"줄마다 올림은 그 줄 안에서만 더해서","correct":true},{"t":"앞 줄에서 올림한 수는 다음 줄에도 더해야 해서","mis":"M3-2-u1-X10"}],"explanation":["셋째 줄 56 × 9 = 504, 넷째 줄 56 × 2 = 112(한 자리 밀어).","504 + 1120 = 1624예요.","1674는 앞 줄의 올림 5를 다시 더한 답이에요."],"asset":{"type":"expr_grid","rows":[["","","","5","6"],["×","","","2","9"],["","","5","0","4"],["","1","1","7",""],["",null,null,null,null]]}},{"stem":"94 × 43을 세로셈으로 계산하는데 셋째 줄 94 × 3에서 올림한 1을 넷째 줄 94 × 4에도 더해 4052라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"줄마다 올림은 그 줄 안에서만 더해서","correct":true},{"t":"앞 줄에서 올림한 수는 다음 줄에도 더해야 해서","mis":"M3-2-u1-X10"}],"explanation":["셋째 줄 94 × 3 = 282, 넷째 줄 94 × 4 = 376(한 자리 밀어).","282 + 3760 = 4042예요.","4052는 앞 줄의 올림 1을 다시 더한 답이에요."],"asset":{"type":"expr_grid","rows":[["","","","9","4"],["×","","","4","3"],["","","2","8","2"],["","3","7","7",""],["",null,null,null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#22','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C9',3,'mc','auto','우리에게 가죽이 44장 필요하고 걸리버에게는 그 20배가 필요해요. 천은 우리에게 126장 필요하고 걸리버에게는 그 7배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?',ARRAY['M3-2-u1-X08','M3-2-u1-X13']::text[],true,'{"seq":22,"concept":"M3-2-u1-C9","difficulty":3,"kind":"mc","stem":"우리에게 가죽이 44장 필요하고 걸리버에게는 그 20배가 필요해요. 천은 우리에게 126장 필요하고 걸리버에게는 그 7배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"1762장","correct":true},{"t":"880장","mis":"M3-2-u1-X08"},{"t":"882장","mis":"M3-2-u1-X08"},{"t":"170장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 44 × 20 = 880장.","천: 126 × 7 = 882장.","880 + 882 = 1762 — 모두 1762장이에요."],"variant_rule":{"alt":[{"stem":"우리에게 가죽이 27장 필요하고 걸리버에게는 그 30배가 필요해요. 천은 우리에게 163장 필요하고 걸리버에게는 그 5배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"1625장","correct":true},{"t":"810장","mis":"M3-2-u1-X08"},{"t":"815장","mis":"M3-2-u1-X08"},{"t":"190장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 27 × 30 = 810장.","천: 163 × 5 = 815장.","810 + 815 = 1625 — 모두 1625장이에요."],"asset":null},{"stem":"우리에게 가죽이 35장 필요하고 걸리버에게는 그 40배가 필요해요. 천은 우리에게 118장 필요하고 걸리버에게는 그 8배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"2344장","correct":true},{"t":"1400장","mis":"M3-2-u1-X08"},{"t":"944장","mis":"M3-2-u1-X08"},{"t":"153장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 35 × 40 = 1400장.","천: 118 × 8 = 944장.","1400 + 944 = 2344 — 모두 2344장이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#23','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C4',4,'sa','auto','수 카드 9, 4, 6, 2를 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-2-u1-C4","difficulty":4,"kind":"sa","stem":"수 카드 9, 4, 6, 2를 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.","answer":["5778"],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 9를 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 642를 만들어요.","642 × 9 = 5778 — 큰 수를 백의 자리에 놓은 964 × 2 = 1928보다 커요."],"variant_rule":{"alt":[{"stem":"수 카드 2, 5, 8, 3을 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.","answer":["4256"],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 8을 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 532를 만들어요.","532 × 8 = 4256 — 큰 수를 백의 자리에 놓은 853 × 2 = 1706보다 커요."],"asset":null},{"stem":"수 카드 6, 3, 7, 4를 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.","answer":["4501"],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 7을 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 643을 만들어요.","643 × 7 = 4501 — 큰 수를 백의 자리에 놓은 764 × 3 = 2292보다 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#24','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C8',4,'sa','auto','지유가 62 × 19를 이렇게 계산해 620이라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-2-u1-C8","difficulty":4,"kind":"sa","stem":"지유가 62 × 19를 이렇게 계산해 620이라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["1178"],"explanation":["지유 — 넷째 줄을 한 자리 밀어 쓰지 않았어요.","62 × 9 = 558, 62 × 10 = 620.","558 + 620 = 1178이에요."],"asset":{"type":"expr_grid","rows":[["","","","6","2"],["×","","","1","9"],["","","5","5","8"],["","","","6","2"],["","","6","2","0"]]},"variant_rule":{"alt":[{"stem":"시우가 58 × 24를 이렇게 계산해 1422라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["1392"],"explanation":["시우 — 셋째 줄의 올림을 넷째 줄에 다시 더했어요.","58 × 4 = 232, 58 × 20 = 1160.","232 + 1160 = 1392예요."],"asset":{"type":"expr_grid","rows":[["","","","5","8"],["×","","","2","4"],["","","2","3","2"],["","1","1","9",""],["","1","4","2","2"]]}},{"stem":"시우가 57 × 84를 이렇게 계산해 684라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["4788"],"explanation":["시우 — 넷째 줄을 한 자리 밀어 쓰지 않았어요.","57 × 4 = 228, 57 × 80 = 4560.","228 + 4560 = 4788이에요."],"asset":{"type":"expr_grid","rows":[["","","","5","7"],["×","","","8","4"],["","","2","2","8"],["","","4","5","6"],["","","6","8","4"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_c#25','math',3,2,'u1','','g3_2_math_u1_review_c','unit_review','M3-2-u1-C9',4,'essay','teacher','고구마를 한쪽은 6개씩 38상자, 다른 쪽은 12개씩 19상자에 담았어요. 어느 쪽 고구마가 더 많은지 곱셈으로 구하고 그 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u1-C9","difficulty":4,"kind":"essay","stem":"고구마를 한쪽은 6개씩 38상자, 다른 쪽은 12개씩 19상자에 담았어요. 어느 쪽 고구마가 더 많은지 곱셈으로 구하고 그 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 6 × 38 = 228, 12 × 19 = 228로 두 쪽이 같다. 한 상자에 담은 개수가 2배이면 상자 수가 반이어도 전체는 같다(38은 19의 2배).","scoring_points":["6 × 38 = 228을 구했는가","12 × 19 = 228을 구했는가","같다고 답하고 까닭을 썼는가"]},"explanation":["6 × 38 = 228.","12 × 19 = 228.","두 쪽이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#1','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C1',1,'sa','auto','130 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u1-C1","difficulty":1,"kind":"sa","stem":"130 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["390"],"explanation":["130을 100, 30, 0으로 갈라 곱해요: 100 × 3 = 300, 30 × 3 = 90, 0 × 3 = 0.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","300 + 90 + 0 = 390 — 어림한 100 × 3 = 300과 가까워요."],"variant_rule":{"alt":[{"stem":"243 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["486"],"explanation":["243을 200, 40, 3으로 갈라 곱해요: 200 × 2 = 400, 40 × 2 = 80, 3 × 2 = 6.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요.","400 + 80 + 6 = 486 — 어림한 200 × 2 = 400과 가까워요."],"asset":null},{"stem":"203 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["406"],"explanation":["203을 200, 0, 3으로 갈라 곱해요: 200 × 2 = 400, 0 × 2 = 0, 3 × 2 = 6.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","400 + 0 + 6 = 406 — 어림한 200 × 2 = 400과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#2','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C1',1,'sa','auto','420 × 2를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u1-C1","difficulty":1,"kind":"sa","stem":"420 × 2를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["800"],"explanation":["420을 400, 20, 0으로 갈라요.","□는 400 × 2 = 800이에요.","800 + 40 + 0 = 840 — 420 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["400 × 2","=",null],["20 × 2","=","40"],["0 × 2","=","0"],["□ + 40 + 0","=","840"]]},"variant_rule":{"alt":[{"stem":"122 × 2를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["200"],"explanation":["122를 100, 20, 2로 갈라요.","□는 100 × 2 = 200이에요.","200 + 40 + 4 = 244 — 122 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["100 × 2","=",null],["20 × 2","=","40"],["2 × 2","=","4"],["□ + 40 + 4","=","244"]]}},{"stem":"114 × 2를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["20"],"explanation":["114를 100, 10, 4로 갈라요.","□는 10 × 2 = 20이에요.","200 + 20 + 8 = 228 — 114 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["100 × 2","=","200"],["10 × 2","=",null],["4 × 2","=","8"],["200 + □ + 8","=","228"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#3','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C2',1,'sa','auto','215 × 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C2","difficulty":1,"kind":"sa","stem":"215 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["860"],"explanation":["215를 200, 10, 5로 갈라 곱해요: 200 × 4 = 800, 10 × 4 = 40, 5 × 4 = 20.","일의 자리 5 × 4 = 20 → 2 올림.","800 + 40 + 20 = 860 — 어림한 200 × 4 = 800과 가까워요."],"variant_rule":{"alt":[{"stem":"308 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["616"],"explanation":["308을 300, 0, 8로 갈라 곱해요: 300 × 2 = 600, 0 × 2 = 0, 8 × 2 = 16.","일의 자리 8 × 2 = 16 → 1 올림.","600 + 0 + 16 = 616 — 어림한 300 × 2 = 600과 가까워요."],"asset":null},{"stem":"146 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["292"],"explanation":["146을 100, 40, 6으로 갈라 곱해요: 100 × 2 = 200, 40 × 2 = 80, 6 × 2 = 12.","일의 자리 6 × 2 = 12 → 1 올림.","200 + 80 + 12 = 292 — 어림한 100 × 2 = 200과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#4','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C4',1,'sa','auto','318 × 8은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u1-C4","difficulty":1,"kind":"sa","stem":"318 × 8은 얼마인가요? 숫자로 쓰세요.","answer":["2544"],"explanation":["318을 300, 10, 8로 갈라 곱해요: 300 × 8 = 2400, 10 × 8 = 80, 8 × 8 = 64.","일의 자리 8 × 8 = 64 → 6 올림, 십의 자리 1 × 8 + 6 = 14 → 1 올림, 백의 자리 3 × 8 + 1 = 25 → 천의 자리.","2400 + 80 + 64 = 2544 — 어림한 300 × 8 = 2400과 가까워요."],"variant_rule":{"alt":[{"stem":"848 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["1696"],"explanation":["848을 800, 40, 8로 갈라 곱해요: 800 × 2 = 1600, 40 × 2 = 80, 8 × 2 = 16.","일의 자리 8 × 2 = 16 → 1 올림, 백의 자리 8 × 2 = 16 → 천의 자리.","1600 + 80 + 16 = 1696 — 어림한 800 × 2 = 1600과 가까워요."],"asset":null},{"stem":"779 × 5는 얼마인가요? 숫자로 쓰세요.","answer":["3895"],"explanation":["779를 700, 70, 9로 갈라 곱해요: 700 × 5 = 3500, 70 × 5 = 350, 9 × 5 = 45.","일의 자리 9 × 5 = 45 → 4 올림, 십의 자리 7 × 5 + 4 = 39 → 3 올림, 백의 자리 7 × 5 + 3 = 38 → 천의 자리.","3500 + 350 + 45 = 3895 — 어림한 800 × 5 = 4000과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#5','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C5',1,'sa','auto','40 × 20은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C5","difficulty":1,"kind":"sa","stem":"40 × 20은 얼마인가요? 숫자로 쓰세요.","answer":["800"],"explanation":["4 × 2 = 8이에요.","40 × 2 = 80, 곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","40 × 20 = 80의 10배 = 800이에요."],"variant_rule":{"alt":[{"stem":"50 × 90은 얼마인가요? 숫자로 쓰세요.","answer":["4500"],"explanation":["5 × 9 = 45예요.","50 × 9 = 450, 곱하는 수가 9에서 90으로 10배가 되면 곱도 10배예요.","50 × 90 = 450의 10배 = 4500이에요."],"asset":null},{"stem":"40 × 50은 얼마인가요? 숫자로 쓰세요.","answer":["2000"],"explanation":["4 × 5 = 20이에요.","40 × 5 = 200, 곱하는 수가 5에서 50으로 10배가 되면 곱도 10배예요.","40 × 50 = 200의 10배 = 2000이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#6','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C6',1,'sa','auto','3 × 31은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u1-C6","difficulty":1,"kind":"sa","stem":"3 × 31은 얼마인가요? 숫자로 쓰세요.","answer":["93"],"explanation":["곱하는 수 31을 30과 1로 갈라요.","3 × 1 = 3, 3 × 30 = 90이에요.","3 + 90 = 93이에요."],"variant_rule":{"alt":[{"stem":"4 × 41은 얼마인가요? 숫자로 쓰세요.","answer":["164"],"explanation":["곱하는 수 41을 40과 1로 갈라요.","4 × 1 = 4, 4 × 40 = 160이에요.","4 + 160 = 164예요."],"asset":null},{"stem":"4 × 83은 얼마인가요? 숫자로 쓰세요.","answer":["332"],"explanation":["곱하는 수 83을 80과 3으로 갈라요.","4 × 3 = 12, 4 × 80 = 320이에요.","12 + 320 = 332예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#7','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C7',1,'sa','auto','46 × 17은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u1-C7","difficulty":1,"kind":"sa","stem":"46 × 17은 얼마인가요? 숫자로 쓰세요.","answer":["782"],"explanation":["곱하는 수 17을 10과 7로 갈라요.","46 × 7 = 322, 46 × 10 = 460이에요.","322 + 460 = 782 — 어림한 50 × 20 = 1000과 가까워요."],"variant_rule":{"alt":[{"stem":"11 × 21은 얼마인가요? 숫자로 쓰세요.","answer":["231"],"explanation":["곱하는 수 21을 20과 1로 갈라요.","11 × 1 = 11, 11 × 20 = 220이에요.","11 + 220 = 231 — 어림한 10 × 20 = 200과 가까워요."],"asset":null},{"stem":"29 × 17은 얼마인가요? 숫자로 쓰세요.","answer":["493"],"explanation":["곱하는 수 17을 10과 7로 갈라요.","29 × 7 = 203, 29 × 10 = 290이에요.","203 + 290 = 493 — 어림한 30 × 20 = 600과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#8','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C3',1,'mc','auto','105 × 9를 어림하면 약 얼마인가요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],true,'{"seq":8,"concept":"M3-2-u1-C3","difficulty":1,"kind":"mc","stem":"105 × 9를 어림하면 약 얼마인가요?","options":[{"t":"약 900","correct":true},{"t":"약 109","mis":"M3-2-u1-X12"},{"t":"약 9000","mis":"M3-2-u1-X06"},{"t":"약 100","mis":"M3-2-u1-X12"}],"explanation":["105는 가까운 몇백 100으로 어림해요.","100 × 9 = 900이에요.","그래서 약 900이에요 — 실제 곱 945와 가까워요."],"variant_rule":{"alt":[{"stem":"327 × 3을 어림하면 약 얼마인가요?","options":[{"t":"약 900","correct":true},{"t":"약 600","mis":"M3-2-u1-X12"},{"t":"약 303","mis":"M3-2-u1-X12"},{"t":"약 9000","mis":"M3-2-u1-X06"}],"explanation":["327은 가까운 몇백 300으로 어림해요.","300 × 3 = 900이에요.","그래서 약 900이에요 — 실제 곱 981과 가까워요."],"asset":null},{"stem":"114 × 5를 어림하면 약 얼마인가요?","options":[{"t":"약 500","correct":true},{"t":"약 105","mis":"M3-2-u1-X12"},{"t":"약 5000","mis":"M3-2-u1-X06"},{"t":"약 100","mis":"M3-2-u1-X12"}],"explanation":["114는 가까운 몇백 100으로 어림해요.","100 × 5 = 500이에요.","그래서 약 500이에요 — 실제 곱 570과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#9','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C2',2,'sa','auto','121 × 5의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u1-C2","difficulty":2,"kind":"sa","stem":"121 × 5의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["5"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 1 × 5 = 5 → 5를 써요.","121 × 5 = 605 — 일의 자리 숫자는 5예요."],"asset":{"type":"expr_grid","rows":[["올림","","1","",""],["","","1","2","1"],["×","","","","5"],["","","6","0",null]]},"variant_rule":{"alt":[{"stem":"391 × 2의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["세로셈은 일의 자리부터 곱해요.","일의 자리: 1 × 2 = 2 → 2를 써요.","391 × 2 = 782 — 일의 자리 숫자는 2예요."],"asset":{"type":"expr_grid","rows":[["올림","","1","",""],["","","3","9","1"],["×","","","","2"],["","","7","8",null]]}},{"stem":"262 × 3의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["세로셈은 일의 자리부터 곱해요.","십의 자리: 6 × 3 = 18 → 8을 써요.","262 × 3 = 786 — 십의 자리 숫자는 8이에요."],"asset":{"type":"expr_grid","rows":[["올림","","1","",""],["","","2","6","2"],["×","","","","3"],["","","7",null,"6"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#10','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C4',2,'sa','auto','257 × 8의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u1-C4","difficulty":2,"kind":"sa","stem":"257 × 8의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["백의 자리 곱 2 × 8 + 올림 4 = 20이에요.","10을 넘은 2가 천의 자리로 가요.","257 × 8 = 2056 — 천의 자리 숫자는 2예요."],"variant_rule":{"alt":[{"stem":"635 × 2의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["백의 자리 곱 6 × 2 = 12예요.","10을 넘은 1이 천의 자리로 가요.","635 × 2 = 1270 — 천의 자리 숫자는 1이에요."],"asset":null},{"stem":"143 × 9의 곱에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["백의 자리 곱 1 × 9 + 올림 3 = 12예요.","10을 넘은 1이 천의 자리로 가요.","143 × 9 = 1287 — 천의 자리 숫자는 1이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#11','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C5',2,'sa','auto','55 × 4 = 220이에요. 그러면 55 × 40은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-2-u1-C5","difficulty":2,"kind":"sa","stem":"55 × 4 = 220이에요. 그러면 55 × 40은 얼마인가요? 숫자로 쓰세요.","answer":["2200"],"explanation":["곱하는 수 40은 4의 10배예요.","곱하는 수가 10배가 되면 곱도 10배가 돼요.","220의 10배 — 55 × 40 = 2200이에요."],"variant_rule":{"alt":[{"stem":"48 × 9 = 432예요. 그러면 48 × 90은 얼마인가요? 숫자로 쓰세요.","answer":["4320"],"explanation":["곱하는 수 90은 9의 10배예요.","곱하는 수가 10배가 되면 곱도 10배가 돼요.","432의 10배 — 48 × 90 = 4320이에요."],"asset":null},{"stem":"68 × 2 = 136이에요. 그러면 68 × 20은 얼마인가요? 숫자로 쓰세요.","answer":["1360"],"explanation":["곱하는 수 20은 2의 10배예요.","곱하는 수가 10배가 되면 곱도 10배가 돼요.","136의 10배 — 68 × 20 = 1360이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#12','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C6',2,'ox','auto','8 × 18의 곱과 18 × 8의 곱은 같아요.',ARRAY['M3-2-u1-X16']::text[],true,'{"seq":12,"concept":"M3-2-u1-C6","difficulty":2,"kind":"ox","stem":"8 × 18의 곱과 18 × 8의 곱은 같아요.","answer":"O","reason_options":[{"t":"곱하는 두 수의 순서를 바꾸어도 곱은 같아서","correct":true},{"t":"곱해지는 수가 커지면 곱도 커져서","mis":"M3-2-u1-X16"}],"mis":"M3-2-u1-X16","explanation":["8 × 18 = 144예요.","18 × 8 = 144예요.","순서를 바꾸어도 곱은 같아요 — 계산하기 쉬운 쪽으로 구해도 돼요."],"variant_rule":{"alt":[{"stem":"9 × 77의 곱과 77 × 9의 곱은 같아요.","answer":"O","reason_options":[{"t":"곱하는 두 수의 순서를 바꾸어도 곱은 같아서","correct":true},{"t":"곱해지는 수가 커지면 곱도 커져서","mis":"M3-2-u1-X16"}],"explanation":["9 × 77 = 693이에요.","77 × 9 = 693이에요.","순서를 바꾸어도 곱은 같아요 — 계산하기 쉬운 쪽으로 구해도 돼요."],"asset":null},{"stem":"6 × 98의 곱과 98 × 6의 곱은 같아요.","answer":"O","reason_options":[{"t":"곱하는 두 수의 순서를 바꾸어도 곱은 같아서","correct":true},{"t":"곱해지는 수가 커지면 곱도 커져서","mis":"M3-2-u1-X16"}],"explanation":["6 × 98 = 588이에요.","98 × 6 = 588이에요.","순서를 바꾸어도 곱은 같아요 — 계산하기 쉬운 쪽으로 구해도 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#13','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C7',2,'sa','auto','62 × 12를 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M3-2-u1-C7","difficulty":2,"kind":"sa","stem":"62 × 12를 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["124"],"explanation":["곱하는 수 12를 2와 10으로 갈라요.","□는 62 × 2 = 124예요.","124 + 620 = 744 — 62 × 12의 곱이에요."],"asset":{"type":"expr_grid","rows":[["62 × 2","=",null],["62 × 10","=","620"],["□ + 620","=","744"]]},"variant_rule":{"alt":[{"stem":"18 × 32를 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["540"],"explanation":["곱하는 수 32를 2와 30으로 갈라요.","□는 18 × 30 = 540이에요.","36 + 540 = 576 — 18 × 32의 곱이에요."],"asset":{"type":"expr_grid","rows":[["18 × 2","=","36"],["18 × 30","=",null],["36 + □","=","576"]]}},{"stem":"44 × 13을 곱하는 수를 갈라 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["132"],"explanation":["곱하는 수 13을 3과 10으로 갈라요.","□는 44 × 3 = 132예요.","132 + 440 = 572 — 44 × 13의 곱이에요."],"asset":{"type":"expr_grid","rows":[["44 × 3","=",null],["44 × 10","=","440"],["□ + 440","=","572"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#14','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C8',2,'sa','auto','49 × 57은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-2-u1-C8","difficulty":2,"kind":"sa","stem":"49 × 57은 얼마인가요? 숫자로 쓰세요.","answer":["2793"],"explanation":["곱하는 수 57을 50과 7로 갈라요.","49 × 7 = 343, 49 × 50 = 2450이에요.","343 + 2450 = 2793 — 어림한 50 × 60 = 3000과 가까워요."],"variant_rule":{"alt":[{"stem":"74 × 98은 얼마인가요? 숫자로 쓰세요.","answer":["7252"],"explanation":["곱하는 수 98을 90과 8로 갈라요.","74 × 8 = 592, 74 × 90 = 6660이에요.","592 + 6660 = 7252 — 어림한 70 × 100 = 7000과 가까워요."],"asset":null},{"stem":"29 × 69는 얼마인가요? 숫자로 쓰세요.","answer":["2001"],"explanation":["곱하는 수 69를 60과 9로 갈라요.","29 × 9 = 261, 29 × 60 = 1740이에요.","261 + 1740 = 2001 — 어림한 30 × 70 = 2100과 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#15','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C3',2,'mc','auto','57 × 82를 어림하면 곱은 어느 사이에 있나요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],true,'{"seq":15,"concept":"M3-2-u1-C3","difficulty":2,"kind":"mc","stem":"57 × 82를 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"4000보다 크고 5400보다 작아요","correct":true},{"t":"4000보다 작아요","mis":"M3-2-u1-X12"},{"t":"5400보다 커요","mis":"M3-2-u1-X12"},{"t":"400보다 크고 540보다 작아요","mis":"M3-2-u1-X06"}],"explanation":["57은 50과 60 사이, 82는 80과 90 사이예요.","50 × 80 = 4000, 60 × 90 = 5400이에요.","57 × 82 = 4674 — 그 사이에 들어요."],"variant_rule":{"alt":[{"stem":"39 × 78을 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"2100보다 크고 3200보다 작아요","correct":true},{"t":"2100보다 작아요","mis":"M3-2-u1-X12"},{"t":"3200보다 커요","mis":"M3-2-u1-X12"},{"t":"210보다 크고 320보다 작아요","mis":"M3-2-u1-X06"}],"explanation":["39는 30과 40 사이, 78은 70과 80 사이예요.","30 × 70 = 2100, 40 × 80 = 3200이에요.","39 × 78 = 3042 — 그 사이에 들어요."],"asset":null},{"stem":"87 × 72를 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"5600보다 크고 7200보다 작아요","correct":true},{"t":"5600보다 작아요","mis":"M3-2-u1-X12"},{"t":"7200보다 커요","mis":"M3-2-u1-X12"},{"t":"560보다 크고 720보다 작아요","mis":"M3-2-u1-X06"}],"explanation":["87은 80과 90 사이, 72는 70과 80 사이예요.","80 × 70 = 5600, 90 × 80 = 7200이에요.","87 × 72 = 6264 — 그 사이에 들어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#16','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C9',2,'sa','auto','우리에게 빵이 5개 필요해요. 걸리버에게는 49배가 필요해요. 걸리버에게 빵은 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-2-u1-C9","difficulty":2,"kind":"sa","stem":"우리에게 빵이 5개 필요해요. 걸리버에게는 49배가 필요해요. 걸리버에게 빵은 몇 개 필요한가요? 숫자로 쓰세요.","answer":["245"],"explanation":["「49배」는 5를 49번 더한 것 — 곱셈식 5 × 49로 세워요.","5 × 9 = 45, 5 × 40 = 200이에요.","5 × 49 = 245 — 245개예요."],"variant_rule":{"alt":[{"stem":"우리에게 단추가 4개 필요해요. 걸리버에게는 46배가 필요해요. 걸리버에게 단추는 몇 개 필요한가요? 숫자로 쓰세요.","answer":["184"],"explanation":["「46배」는 4를 46번 더한 것 — 곱셈식 4 × 46으로 세워요.","4 × 6 = 24, 4 × 40 = 160이에요.","4 × 46 = 184 — 184개예요."],"asset":null},{"stem":"우리에게 실이 8타래 필요해요. 걸리버에게는 62배가 필요해요. 걸리버에게 실은 몇 타래 필요한가요? 숫자로 쓰세요.","answer":["496"],"explanation":["「62배」는 8을 62번 더한 것 — 곱셈식 8 × 62로 세워요.","8 × 2 = 16, 8 × 60 = 480이에요.","8 × 62 = 496 — 496타래예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#17','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C1',3,'error','auto','430 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X05','M3-2-u1-X15']::text[],true,'{"seq":17,"concept":"M3-2-u1-C1","difficulty":3,"kind":"error","stem":"430 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「430 × 2 = 862야」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"시우 — 「430 × 2 = 860이야」","mis":"M3-2-u1-X15"},{"t":"하린 — 「어림하면 약 800이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","430 × 2 = 860이에요.","서윤은 862로 잘못 구했어요 — 0에 곱하면 0."],"variant_rule":{"alt":[{"stem":"210 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「210 × 3 = 633이야」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"시우 — 「210 × 3 = 630이야」","mis":"M3-2-u1-X15"},{"t":"태오 — 「3 × 210 = 630이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","210 × 3 = 630이에요.","도윤은 633으로 잘못 구했어요 — 0에 곱하면 0."],"asset":null},{"stem":"220 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「220 × 4 = 884야」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"하랑 — 「220 × 4 = 880이야」","mis":"M3-2-u1-X15"},{"t":"시우 — 「어림하면 약 800이야」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 자기 자리에 바로 써요. 0인 자리는 0이에요.","220 × 4 = 880이에요.","도윤은 884로 잘못 구했어요 — 0에 곱하면 0."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#18','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C2',3,'ox','auto','427 × 2를 계산하는데 일의 자리에서 십의 자리로 올림한 1을 더하지 않고 844라고 했어요. 바르게 계산했어요.',ARRAY['M3-2-u1-X02']::text[],true,'{"seq":18,"concept":"M3-2-u1-C2","difficulty":3,"kind":"ox","stem":"427 × 2를 계산하는데 일의 자리에서 십의 자리로 올림한 1을 더하지 않고 844라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수는 윗자리를 곱한 다음 꼭 더해야 해서","correct":true},{"t":"올림한 수는 작게 적어 두기만 하면 되어서","mis":"M3-2-u1-X02"}],"mis":"M3-2-u1-X02","explanation":["일의 자리 7 × 2 = 14 → 1 올림.","427 × 2 = 854예요.","844는 올림한 1을 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["올림","","","1",""],["","","4","2","7"],["×","","","","2"],["","",null,null,null]]},"variant_rule":{"alt":[{"stem":"107 × 4를 계산하는데 일의 자리에서 십의 자리로 올림한 2를 더하지 않고 408이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수는 윗자리를 곱한 다음 꼭 더해야 해서","correct":true},{"t":"올림한 수는 작게 적어 두기만 하면 되어서","mis":"M3-2-u1-X02"}],"explanation":["일의 자리 7 × 4 = 28 → 2 올림.","107 × 4 = 428이에요.","408은 올림한 2를 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["올림","","","2",""],["","","1","0","7"],["×","","","","4"],["","",null,null,null]]}},{"stem":"226 × 3을 계산하는데 일의 자리에서 십의 자리로 올림한 1을 더하지 않고 668이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수는 윗자리를 곱한 다음 꼭 더해야 해서","correct":true},{"t":"올림한 수는 작게 적어 두기만 하면 되어서","mis":"M3-2-u1-X02"}],"explanation":["일의 자리 6 × 3 = 18 → 1 올림.","226 × 3 = 678이에요.","668은 올림한 1을 빠뜨린 답이에요."],"asset":{"type":"expr_grid","rows":[["올림","","","1",""],["","","2","2","6"],["×","","","","3"],["","",null,null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#19','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C4',3,'error','auto','578 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X03','M3-2-u1-X15']::text[],true,'{"seq":19,"concept":"M3-2-u1-C4","difficulty":3,"kind":"error","stem":"578 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「578 × 7 = 4346이야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"서윤 — 「578 × 7 = 4046이야」","mis":"M3-2-u1-X15"},{"t":"시우 — 「어림하면 약 4200이야」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 8 × 7 = 56 → 5 올림, 십의 자리 7 × 7 + 5 = 54 → 5 올림, 백의 자리 5 × 7 + 5 = 40 → 천의 자리.","578 × 7 = 4046이에요.","하랑은 4346으로 잘못 구했어요 — 곱한 다음에 더하기."],"variant_rule":{"alt":[{"stem":"859 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「859 × 8 = 7362야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"도윤 — 「859 × 8 = 6872야」","mis":"M3-2-u1-X15"},{"t":"지유 — 「8 × 859 = 6872야」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 9 × 8 = 72 → 7 올림, 십의 자리 5 × 8 + 7 = 47 → 4 올림, 백의 자리 8 × 8 + 4 = 68 → 천의 자리.","859 × 8 = 6872예요.","서윤은 7362로 잘못 구했어요 — 곱한 다음에 더하기."],"asset":null},{"stem":"522 × 9를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「522 × 9 = 4778이야」","correct":true,"mis_target":"M3-2-u1-X03"},{"t":"서윤 — 「522 × 9 = 4698이야」","mis":"M3-2-u1-X15"},{"t":"하린 — 「어림하면 약 4500이야」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 2 × 9 = 18 → 1 올림, 십의 자리 2 × 9 + 1 = 19 → 1 올림, 백의 자리 5 × 9 + 1 = 46 → 천의 자리.","522 × 9 = 4698이에요.","태오는 4778로 잘못 구했어요 — 곱한 다음에 더하기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#20','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C5',3,'error','auto','77 × 50을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X06','M3-2-u1-X15']::text[],true,'{"seq":20,"concept":"M3-2-u1-C5","difficulty":3,"kind":"error","stem":"77 × 50을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「77 × 50 = 385야」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"지유 — 「77 × 50 = 3850이야」","mis":"M3-2-u1-X15"},{"t":"은우 — 「50 × 77 = 3850이야」","mis":"M3-2-u1-X15"}],"explanation":["곱하는 수가 5에서 50으로 10배가 되면 곱도 10배예요.","77 × 50 = 3850이에요.","시우는 385로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배."],"variant_rule":{"alt":[{"stem":"28 × 60을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「28 × 60 = 168이야」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"서윤 — 「28 × 60 = 1680이야」","mis":"M3-2-u1-X15"},{"t":"하랑 — 「어림하면 약 1800이야」","mis":"M3-2-u1-X15"}],"explanation":["곱하는 수가 6에서 60으로 10배가 되면 곱도 10배예요.","28 × 60 = 1680이에요.","은우는 168로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배."],"asset":null},{"stem":"34 × 80을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「34 × 80 = 272야」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"시우 — 「34 × 80 = 2720이야」","mis":"M3-2-u1-X15"},{"t":"서윤 — 「80 × 34 = 2720이야」","mis":"M3-2-u1-X15"}],"explanation":["곱하는 수가 8에서 80으로 10배가 되면 곱도 10배예요.","34 × 80 = 2720이에요.","하린은 272로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#21','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C8',3,'ox','auto','67 × 99를 세로셈으로 계산하는데 셋째 줄 67 × 9에서 올림한 6을 넷째 줄 67 × 9에도 더해 6693이라고 했어요. 바르게 계산했어요.',ARRAY['M3-2-u1-X10']::text[],true,'{"seq":21,"concept":"M3-2-u1-C8","difficulty":3,"kind":"ox","stem":"67 × 99를 세로셈으로 계산하는데 셋째 줄 67 × 9에서 올림한 6을 넷째 줄 67 × 9에도 더해 6693이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"줄마다 올림은 그 줄 안에서만 더해서","correct":true},{"t":"앞 줄에서 올림한 수는 다음 줄에도 더해야 해서","mis":"M3-2-u1-X10"}],"mis":"M3-2-u1-X10","explanation":["셋째 줄 67 × 9 = 603, 넷째 줄 67 × 9 = 603(한 자리 밀어).","603 + 6030 = 6633이에요.","6693은 앞 줄의 올림 6을 다시 더한 답이에요."],"asset":{"type":"expr_grid","rows":[["","","","6","7"],["×","","","9","9"],["","","6","0","3"],["","6","0","9",""],["",null,null,null,null]]},"variant_rule":{"alt":[{"stem":"86 × 62를 세로셈으로 계산하는데 셋째 줄 86 × 2에서 올림한 1을 넷째 줄 86 × 6에도 더해 5342라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"줄마다 올림은 그 줄 안에서만 더해서","correct":true},{"t":"앞 줄에서 올림한 수는 다음 줄에도 더해야 해서","mis":"M3-2-u1-X10"}],"explanation":["셋째 줄 86 × 2 = 172, 넷째 줄 86 × 6 = 516(한 자리 밀어).","172 + 5160 = 5332예요.","5342는 앞 줄의 올림 1을 다시 더한 답이에요."],"asset":{"type":"expr_grid","rows":[["","","","8","6"],["×","","","6","2"],["","","1","7","2"],["","5","1","7",""],["",null,null,null,null]]}},{"stem":"36 × 64를 세로셈으로 계산하는데 셋째 줄 36 × 4에서 올림한 2를 넷째 줄 36 × 6에도 더해 2324라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"줄마다 올림은 그 줄 안에서만 더해서","correct":true},{"t":"앞 줄에서 올림한 수는 다음 줄에도 더해야 해서","mis":"M3-2-u1-X10"}],"explanation":["셋째 줄 36 × 4 = 144, 넷째 줄 36 × 6 = 216(한 자리 밀어).","144 + 2160 = 2304예요.","2324는 앞 줄의 올림 2를 다시 더한 답이에요."],"asset":{"type":"expr_grid","rows":[["","","","3","6"],["×","","","6","4"],["","","1","4","4"],["","2","1","8",""],["",null,null,null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#22','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C9',3,'mc','auto','우리에게 가죽이 19장 필요하고 걸리버에게는 그 30배가 필요해요. 천은 우리에게 234장 필요하고 걸리버에게는 그 4배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?',ARRAY['M3-2-u1-X08','M3-2-u1-X13']::text[],true,'{"seq":22,"concept":"M3-2-u1-C9","difficulty":3,"kind":"mc","stem":"우리에게 가죽이 19장 필요하고 걸리버에게는 그 30배가 필요해요. 천은 우리에게 234장 필요하고 걸리버에게는 그 4배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"1506장","correct":true},{"t":"570장","mis":"M3-2-u1-X08"},{"t":"936장","mis":"M3-2-u1-X08"},{"t":"253장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 19 × 30 = 570장.","천: 234 × 4 = 936장.","570 + 936 = 1506 — 모두 1506장이에요."],"variant_rule":{"alt":[{"stem":"우리에게 가죽이 41장 필요하고 걸리버에게는 그 20배가 필요해요. 천은 우리에게 129장 필요하고 걸리버에게는 그 6배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"1594장","correct":true},{"t":"820장","mis":"M3-2-u1-X08"},{"t":"774장","mis":"M3-2-u1-X08"},{"t":"170장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 41 × 20 = 820장.","천: 129 × 6 = 774장.","820 + 774 = 1594 — 모두 1594장이에요."],"asset":null},{"stem":"우리에게 가죽이 25장 필요하고 걸리버에게는 그 40배가 필요해요. 천은 우리에게 141장 필요하고 걸리버에게는 그 7배가 필요해요. 걸리버에게 필요한 가죽과 천은 모두 몇 장인가요?","options":[{"t":"1987장","correct":true},{"t":"1000장","mis":"M3-2-u1-X08"},{"t":"987장","mis":"M3-2-u1-X08"},{"t":"166장","mis":"M3-2-u1-X13"}],"explanation":["가죽: 25 × 40 = 1000장.","천: 141 × 7 = 987장.","1000 + 987 = 1987 — 모두 1987장이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#23','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C4',4,'sa','auto','수 카드 5, 3, 8, 4를 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-2-u1-C4","difficulty":4,"kind":"sa","stem":"수 카드 5, 3, 8, 4를 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.","answer":["4344"],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 8을 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 543을 만들어요.","543 × 8 = 4344 — 큰 수를 백의 자리에 놓은 854 × 3 = 2562보다 커요."],"variant_rule":{"alt":[{"stem":"수 카드 7, 2, 6, 9를 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.","answer":["6858"],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 9를 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 762를 만들어요.","762 × 9 = 6858 — 큰 수를 백의 자리에 놓은 976 × 2 = 1952보다 커요."],"asset":null},{"stem":"수 카드 4, 6, 3, 2를 한 번씩 놓아 (세 자리 수) × (한 자리 수)를 만들어요. 곱이 가장 클 때의 곱은 얼마인가요? 숫자로 쓰세요.","answer":["2592"],"explanation":["곱하는 수(한 자리)는 세 자리 수의 모든 자리에 곱해져 영향이 가장 커요.","그래서 가장 큰 수 6을 곱하는 수 자리에, 남은 수로 가장 큰 세 자리 수 432를 만들어요.","432 × 6 = 2592 — 큰 수를 백의 자리에 놓은 643 × 2 = 1286보다 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#24','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C8',4,'sa','auto','서윤이 59 × 56을 이렇게 계산해 3354라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-2-u1-C8","difficulty":4,"kind":"sa","stem":"서윤이 59 × 56을 이렇게 계산해 3354라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["3304"],"explanation":["서윤 — 셋째 줄의 올림을 넷째 줄에 다시 더했어요.","59 × 6 = 354, 59 × 50 = 2950.","354 + 2950 = 3304예요."],"asset":{"type":"expr_grid","rows":[["","","","5","9"],["×","","","5","6"],["","","3","5","4"],["","3","0","0",""],["","3","3","5","4"]]},"variant_rule":{"alt":[{"stem":"지유가 47 × 93을 이렇게 계산해 564라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["4371"],"explanation":["지유 — 넷째 줄을 한 자리 밀어 쓰지 않았어요.","47 × 3 = 141, 47 × 90 = 4230.","141 + 4230 = 4371이에요."],"asset":{"type":"expr_grid","rows":[["","","","4","7"],["×","","","9","3"],["","","1","4","1"],["","","4","2","3"],["","","5","6","4"]]}},{"stem":"은우가 98 × 77을 이렇게 계산해 7596이라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["7546"],"explanation":["은우 — 셋째 줄의 올림을 넷째 줄에 다시 더했어요.","98 × 7 = 686, 98 × 70 = 6860.","686 + 6860 = 7546이에요."],"asset":{"type":"expr_grid","rows":[["","","","9","8"],["×","","","7","7"],["","","6","8","6"],["","6","9","1",""],["","7","5","9","6"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u1_review_d#25','math',3,2,'u1','','g3_2_math_u1_review_d','unit_review','M3-2-u1-C5',4,'essay','teacher','45 × 30을 두 가지 방법으로 계산하고, 답이 같은지 확인해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u1-C5","difficulty":4,"kind":"essay","stem":"45 × 30을 두 가지 방법으로 계산하고, 답이 같은지 확인해 보세요.","answer_guide":{"answer":"예: 방법 1 — 45 × 3 = 135의 10배인 1350. 방법 2 — 45 × 10 = 450의 3배인 1350. 두 방법 모두 1350이다.","scoring_points":["45 × 3의 10배로 구했는가","45 × 10의 3배로 구했는가","1350으로 같음을 확인했는가"]},"explanation":["45 × 3 = 135 → 10배 1350.","45 × 10 = 450 → 3배 1350.","두 길 모두 1350."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
